// Anmeldung an der Kachel: mit der eigenen PIN. Die PIN wird auf dem
// Server geprüft (Funktion "pin-anmelden", SQL pin-anmeldung.sql), nach
// 5 falschen Versuchen ist das Konto 5 Minuten gesperrt. Früher stand
// hier ein gemeinsames Passwort offen im Code, das ist abgeschafft.
async function pinAnmelden(email, pin) {
  let antwort;
  try {
    antwort = await zeitlimit(db.functions.invoke("pin-anmelden",
      { body: { email: email, pin: String(pin) } }), 15000, "Anmeldung");
  } catch (f) {
    return { status: "fehler", text: fehlertext(f) };
  }
  const d = antwort && antwort.data;
  if (!d || antwort.error) return { status: "fehler", text: "nicht eingerichtet" };
  if (d.status !== "ok") return d;
  // Den einmaligen Schlüssel gegen eine Sitzung tauschen
  let r = await db.auth.verifyOtp({ token_hash: d.token_hash, type: "email" });
  if (r.error) r = await db.auth.verifyOtp({ token_hash: d.token_hash, type: "magiclink" });
  if (r.error) return { status: "fehler", text: fehlertext(r.error) };
  return { status: "ok" };
}

// Was die Person nach einem PIN-Versuch zu lesen bekommt
function pinMeldung(e) {
  if (e.status === "falsch") {
    return e.rest === 1 ? "PIN falsch. Noch 1 Versuch, dann 5 Minuten Pause."
      : "PIN falsch. Noch " + e.rest + " Versuche.";
  }
  if (e.status === "gesperrt") {
    const min = Math.max(1, Math.ceil((e.sekunden || 300) / 60));
    return "Zu viele falsche Versuche. Bitte in " + min
      + (min === 1 ? " Minute" : " Minuten") + " wieder versuchen.";
  }
  if (e.status === "keine_pin") return "Für dich ist noch keine PIN hinterlegt. Bitte beim Admin melden.";
  if (e.status === "falsch_eingabe") return "Die PIN hat 4 bis 8 Ziffern.";
  return "PIN-Anmeldung geht gerade nicht. Bitte Passwort eingeben.";
}

