// Schliesst ein Fenster mit Escape und beim Klick daneben.
// Wichtig: nur wenn Druck UND Loslassen daneben passieren, sonst
// bricht das Markieren von Text im Fenster die Eingabe ab.
// Escape geht eine Ebene zurück, wenn kein Fenster offen ist:
// vom Teil zum Kunden, vom Kunden zum Bereich, vom Bereich zur
// Übersicht — und beim Typ vom Aufbau zur Liste.
function escapeZurueck() {
  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    // Ein offenes Fenster hat Vorrang, das schliesst sich selbst
    if (document.querySelector(".dialog-huelle")) return;
    // In einem Eingabefeld ist Escape zum Verwerfen da
    const a = document.activeElement;
    if (a && /^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName)) return;

    // zeichneSeite baut die aktuelle Seite neu auf und kennt den
    // Container selbst — seiteProduktion braucht ihn als Argument.
    if (prod.hocoOffen) { prod.hocoOffen = null; zeichneSeite(); return; }
    if (prod.hocoKunde) { prod.hocoKunde = null; zeichneSeite(); return; }
    if (prod.hocoBereich) { prod.hocoBereich = null; zeichneSeite(); return; }
    if (prod.typOffen) { prod.typOffen = null; zeichneSeite(); return; }

    // Sonst: von einem Unterreiter zurück auf den ersten
    const wo = location.hash.replace(/^#\/?/, "").split("/")[0];
    if (wo === "produktion" && prod.ansicht && prod.ansicht !== "erfassen") {
      prod.ansicht = "erfassen"; zeichneSeite(); return;
    }
    if (wo === "bestellungen" && best.ansicht && best.ansicht !== "offen") {
      best.ansicht = "offen"; zeichneSeite(); return;
    }
  });
}

// =================================================================
//  Fenster zentral schliessen
//  Zurück im Browser und Escape schliessen immer das oberste Fenster,
//  egal von welcher Stelle es geöffnet wurde. Beobachtet wird, was
//  am Seitenkörper auftaucht — so gilt es auch für Fenster, die ihre
//  eigene Schliesslogik mitbringen.
// =================================================================

const fensterStapel = [];
// Die App führt Buch, statt zu raten: wie viele Verlaufseinträge zu
// offenen Fenstern gehören, wie viele Rücksprünge sie selbst ausgelöst
// hat und wie viele Einträge der Nutzer mit Zurück schon verbraucht hat.
// Wird ein Fenster im selben Augenblick durch ein anderes ersetzt —
// etwa beim Kopieren —, ändert sich am Verlauf nichts. Vorher ging die
// App dabei einen Schritt zu weit zurück, bis auf die Startseite.
let fensterEintraege = 0;
let eigeneZurueck = 0;
let schonZurueck = 0;
let zurueckIntern = false;   // bleibt für ältere Stellen, die danach fragen

function fensterZumachen(el) {
  if (el.id === "pad") {
    if (typeof padSchliessen === "function") padSchliessen();
    else el.remove();
    return;
  }
  // Der eigene Schliessknopf weiss am besten, was aufzuräumen ist
  const knopf = el.querySelector("[data-nein], [data-zu], [data-padzu], #pl-nein,"
    + " .dialog__knoepfe .knopf--still");
  if (knopf) knopf.click();
  else el.remove();
}

function oberstesFensterSchliessen() {
  for (let i = fensterStapel.length - 1; i >= 0; i--) {
    const el = fensterStapel[i];
    if (!document.body.contains(el)) { fensterStapel.splice(i, 1); continue; }
    fensterZumachen(el);
    return true;
  }
  return false;
}

(function fensterUeberwachen() {
  const beobachter = new MutationObserver((meldungen) => {
    let dazu = 0, weg = 0;
    meldungen.forEach((m) => {
      m.addedNodes.forEach((n) => {
        if (n.nodeType !== 1 || !n.classList) return;
        if (!n.classList.contains("dialog-huelle") && n.id !== "pad") return;
        if (n.classList.contains("dialog-huelle")) bewegungFenster(n);
        fensterStapel.push(n);
        dazu++;
      });
      m.removedNodes.forEach((n) => {
        const i = fensterStapel.indexOf(n);
        if (i === -1) return;
        fensterStapel.splice(i, 1);
        weg++;
      });
    });
    // Was der Nutzer mit Zurück schon abgeräumt hat, zählt nicht noch einmal
    const verbraucht = Math.min(weg, schonZurueck);
    schonZurueck -= verbraucht;
    weg -= verbraucht;

    const netto = dazu - weg;
    if (netto > 0) {
      // Je neues Fenster ein Eintrag, damit Zurück es trifft
      for (let k = 0; k < netto; k++) {
        try { history.pushState({ fenster: true }, ""); fensterEintraege++; } catch (f) { /* egal */ }
      }
    } else if (netto < 0) {
      // Die eigenen Einträge wieder abräumen, in einem Schritt
      const n = Math.min(-netto, fensterEintraege);
      if (n > 0 && history.state && history.state.fenster) {
        fensterEintraege -= n;
        eigeneZurueck++;
        try { history.go(-n); } catch (f) { eigeneZurueck--; }
      }
    }
  });
  beobachter.observe(document.body, { childList: true });

  window.addEventListener("popstate", () => {
    if (eigeneZurueck > 0) { eigeneZurueck--; return; }
    // Zurück vom Nutzer: dessen Eintrag ist verbraucht, das oberste
    // Fenster geht zu — ohne dass die App deshalb nochmals zurückgeht
    if (fensterEintraege > 0) {
      fensterEintraege--;
      schonZurueck++;
      if (!oberstesFensterSchliessen()) schonZurueck = Math.max(0, schonZurueck - 1);
    }
  });

  // Escape zuerst hier: Fenster mit eigener Behandlung merken danach,
  // dass sie schon zu sind, und tun nichts mehr.
  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    if (oberstesFensterSchliessen()) { e.preventDefault(); return; }
    // Kein richtiges Fenster offen: dann das kleine Infofenster der
    // Planwand, das beim Antippen eines Balkens stehen bleibt
    const infos = document.querySelectorAll(".pw-info");
    if (infos.length) { infos.forEach((x) => x.remove()); e.preventDefault(); }
  }, true);
})();

function dialogSchliessen(huelle, zu) {
  let startAussen = false;

  huelle.addEventListener("pointerdown", (e) => {
    startAussen = (e.target === huelle);
  });

  huelle.addEventListener("click", (e) => {
    if (e.target === huelle && startAussen) zu();
    startAussen = false;
  });

  const taste = (e) => {
    if (e.key !== "Escape") return;
    if (!document.body.contains(huelle)) {
      document.removeEventListener("keydown", taste);
      return;
    }
    // Die zentrale Behandlung oben hat schon das oberste Fenster
    // geschlossen. Liegt dieses darunter, bleibt es offen — sonst
    // schloss Escape in einem Unterfenster gleich beide.
    if (e.defaultPrevented) return;
    e.preventDefault();
    document.removeEventListener("keydown", taste);
    zu();
  };
  document.addEventListener("keydown", taste);
}

// Bild quadratisch zuschneiden. Zeigt eine Vorschau und liefert
function bildZuschneiden(datei, kante) {
  return new Promise((fertig) => {
    const leser = new FileReader();
    leser.onload = () => {
      const bild = new Image();
      bild.onload = () => {
        const huelle = document.createElement("div");
        huelle.className = "dialog-huelle";
        huelle.innerHTML = '<div class="dialog">'
          + '<h2>Bild zuschneiden</h2>'
          + '<p class="klein">Ziehe das Bild zurecht und stelle die Grösse ein. '
          + 'Der gezeigte Ausschnitt wird gespeichert.</p>'
          + '<div class="zuschnitt" id="zs-buehne">'
          + '<canvas id="zs-leinwand"></canvas></div>'
          + '<label class="feld"><span>Grösse</span>'
          + '<input type="range" id="zs-zoom" min="100" max="300" value="100"></label>'
          + '<div class="dialog__knoepfe">'
          + '<button class="knopf knopf--still" id="zs-nein">Abbrechen</button>'
          + '<button class="knopf knopf--haupt" id="zs-ja">Übernehmen</button>'
          + '</div></div>';
        document.body.appendChild(huelle);

        const leinwand = huelle.querySelector("#zs-leinwand");
        const ctx = leinwand.getContext("2d");
        const seite = 260;
        leinwand.width = seite;
        leinwand.height = seite;

        let zoom = 1, vx = 0, vy = 0;
        const grund = Math.max(seite / bild.width, seite / bild.height);

        const zeichnen = () => {
          const f = grund * zoom;
          const bw = bild.width * f, bh = bild.height * f;
          vx = Math.min(0, Math.max(seite - bw, vx));
          vy = Math.min(0, Math.max(seite - bh, vy));
          ctx.fillStyle = "#1c2229";
          ctx.fillRect(0, 0, seite, seite);
          ctx.drawImage(bild, vx, vy, bw, bh);
        };
        zeichnen();

        let zieht = false, lx = 0, ly = 0;
        leinwand.addEventListener("pointerdown", (e) => {
          zieht = true; lx = e.clientX; ly = e.clientY;
          leinwand.setPointerCapture(e.pointerId);
        });
        leinwand.addEventListener("pointermove", (e) => {
          if (!zieht) return;
          vx += e.clientX - lx; vy += e.clientY - ly;
          lx = e.clientX; ly = e.clientY;
          zeichnen();
        });
        leinwand.addEventListener("pointerup", () => { zieht = false; });

        huelle.querySelector("#zs-zoom").oninput = (e) => {
          zoom = Number(e.target.value) / 100;
          zeichnen();
        };

        const zu = (wert) => { huelle.remove(); fertig(wert); };
        huelle.querySelector("#zs-nein").onclick = () => zu(null);
        dialogSchliessen(huelle, () => zu(null));

        huelle.querySelector("#zs-ja").onclick = () => {
          const ziel = document.createElement("canvas");
          const g = kante || 400;
          ziel.width = g; ziel.height = g;
          ziel.getContext("2d").drawImage(leinwand, 0, 0, seite, seite, 0, 0, g, g);
          ziel.toBlob((blob) => zu(blob), "image/jpeg", 0.88);
        };
      };
      bild.src = leser.result;
    };
    leser.readAsDataURL(datei);
  });
}

function bildVerkleinern(datei, maxKante) {
  return new Promise((fertig, ablehnen) => {
    const leser = new FileReader();
    leser.onload = () => {
      const bild = new Image();
      bild.onload = () => {
        const max = maxKante || 1200;
        let bw = bild.width, bh = bild.height;
        if (bw > max || bh > max) {
          const f = Math.min(max / bw, max / bh);
          bw = Math.round(bw * f); bh = Math.round(bh * f);
        }
        const c = document.createElement("canvas");
        c.width = bw; c.height = bh;
        c.getContext("2d").drawImage(bild, 0, 0, bw, bh);
        c.toBlob((blob) => blob ? fertig(blob) : ablehnen(new Error("Bild nicht lesbar")),
          "image/jpeg", 0.85);
      };
      bild.onerror = () => ablehnen(new Error("Bild nicht lesbar"));
      bild.src = leser.result;
    };
    leser.onerror = () => ablehnen(new Error("Datei nicht lesbar"));
    leser.readAsDataURL(datei);
  });
}

// =================================================================
//  RÜCKGÄNGIG
//  Jede Änderung, die sich sauber zurücknehmen lässt, wird hier
//  abgelegt. Strg + Z oder der Knopf nimmt den letzten Schritt zurück.
// =================================================================

const rueckgaengigListe = [];

function merkeSchritt(text, zuruecknehmen) {
  rueckgaengigListe.push({ text: text, tun: zuruecknehmen });
  if (rueckgaengigListe.length > 30) rueckgaengigListe.shift();
  knopfRueckgaengigZeigen();
}

function knopfRueckgaengigZeigen() {
  const k = document.getElementById("rueck-knopf");
  if (!k) return;
  k.hidden = false;
  k.disabled = rueckgaengigListe.length === 0;
  k.title = rueckgaengigListe.length
    ? "Rückgängig: " + rueckgaengigListe[rueckgaengigListe.length - 1].text
    : "";
}

async function schrittZurueck() {
  const letzter = rueckgaengigListe.pop();
  knopfRueckgaengigZeigen();
  if (!letzter) { meldung("Nichts zum Zurücknehmen.", "warn"); return; }

  try {
    // Auf der Planwand gleiten die Balken an ihren alten Platz zurück
    planFliessenAnmelden();
    await letzter.tun();
    meldung("Zurückgenommen: " + letzter.text);
  } catch (f) {
    meldung("Zurücknehmen fehlgeschlagen: " + fehlertext(f), "fehler");
  }
}

// In einem Textfeld nimmt Strg+Z den getippten Text zurück — das soll
// so bleiben. Schieberegler, Haken und Knöpfe zählen aber nicht als
// Textfeld: Nach dem Ziehen am Zeitraum blieb der Fokus dort hängen,
// und Strg+Z tat nichts mehr.
function istTextfeld(el) {
  if (!el) return false;
  if (el.isContentEditable || el.tagName === "TEXTAREA") return true;
  if (el.tagName !== "INPUT") return false;
  const typ = String(el.type || "text").toLowerCase();
  return ["range", "checkbox", "radio", "button", "submit", "reset", "color", "file", "image"]
    .indexOf(typ) === -1;
}

document.addEventListener("keydown", (e) => {
  if (!((e.ctrlKey || e.metaKey) && !e.shiftKey && e.key.toLowerCase() === "z")) return;
  if (istTextfeld(e.target)) return;
  // Offenes Fenster: dort gibt es nichts zurückzunehmen
  if (document.querySelector(".dialog-huelle")) return;
  e.preventDefault();
  schrittZurueck();
});

// Grosser Ziffernblock für ein Zahlenfeld. Nützlich am Tablet
// oder wenn die Bildschirmtastatur stört.
function zahlNumpad(feld) {
  if (!feld) return;
  const huelle = document.createElement("div");
  huelle.className = "dialog-huelle";
  huelle.innerHTML = '<div class="dialog dialog--numpad">'
    + '<div class="numpad-anzeige" id="np-anzeige">' + esc(feld.value || "0") + '</div>'
    + '<div class="numpad-tasten">'
    + [7,8,9,4,5,6,1,2,3].map((z) => '<button class="numpad-taste" data-np="' + z
        + '">' + z + '</button>').join("")
    + '<button class="numpad-taste" data-npc="loeschen">⌫</button>'
    + '<button class="numpad-taste" data-np="0">0</button>'
    + '<button class="numpad-taste" data-npc="leeren">C</button>'
    + '</div>'
    + '<div class="dialog__knoepfe">'
    + '<button class="knopf knopf--still" id="np-nein">Abbrechen</button>'
    + '<button class="knopf knopf--haupt" id="np-ja">Übernehmen</button>'
    + '</div></div>';
  document.body.appendChild(huelle);

  let wert = (feld.value || "").replace(/[^\d]/g, "");
  const anzeige = huelle.querySelector("#np-anzeige");
  const zeigen = () => { anzeige.textContent = wert || "0"; };

  huelle.querySelectorAll("[data-np]").forEach((k) => {
    k.onclick = () => { wert = (wert + k.dataset.np).replace(/^0+(?=\d)/, ""); zeigen(); };
  });
  huelle.querySelector('[data-npc="loeschen"]').onclick = () => {
    wert = wert.slice(0, -1); zeigen();
  };
  huelle.querySelector('[data-npc="leeren"]').onclick = () => { wert = ""; zeigen(); };

  const zu = () => huelle.remove();
  huelle.querySelector("#np-nein").onclick = zu;
  dialogSchliessen(huelle, zu);

  huelle.querySelector("#np-ja").onclick = () => {
    feld.value = wert;
    feld.dispatchEvent(new Event("change", { bubbles: true }));
    zu();
  };
}

function esc(w) {
  if (w === null || w === undefined) return "";
  return String(w).replaceAll("&", "&amp;").replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;").replaceAll('"', "&quot;");
}

function zeitlimit(versprechen, ms, name) {
  return Promise.race([
    versprechen,
    new Promise((_, ab) => setTimeout(() => ab(new Error("Zeitüberschreitung bei " + name)), ms)),
  ]);
}

// Nach einer eigenen Änderung merkt sich der Abgleich den neuen Stand,
// damit die Seite nicht gleich nochmal aufgebaut wird.
function stempelAuffrischen() {
  if (!sync.pfad) return;
  seitenStempel(sync.pfad).then((w) => { sync.stempel = w; });
}

// =================================================================
//  OFFLINE
//  Eine Schicht zwischen App und Supabase, die jede Anfrage sieht:
//
//   · Lesen: jede erfolgreiche Antwort wird auf dem Gerät gemerkt.
//     Ohne Netz liefert die App den letzten bekannten Stand.
//   · Schreiben: ohne Netz landen Änderungen in einer Warteschlange
//     und gehen raus, sobald wieder Verbindung da ist — in derselben
//     Reihenfolge, in der sie gemacht wurden.
//   · Oben erscheint ein Hinweis mit dem Stand und der Zahl der
//     wartenden Änderungen.
//
//  Dateien (Zeichnungen, Bilder) lassen sich offline nicht hochladen;
//  das meldet die App wie bisher als Fehler.
// =================================================================

const OFFLINE = {
  cache: "hofer-daten-v1",
  schlange: "hofer.warteschlange",
  standZeit: "hofer.offline.stand",
  offline: false,
  auth: null,          // letzte gültige Anmeldung, für das Nachsenden
  apikey: null,
  sendet: false,
};

function offlineSchlange() {
  try { return JSON.parse(localStorage.getItem(OFFLINE.schlange) || "[]"); }
  catch (f) { return []; }
}
function offlineSchlangeSetzen(liste) {
  try { localStorage.setItem(OFFLINE.schlange, JSON.stringify(liste)); } catch (f) { /* voll */ }
  offlineHinweis();
}

function istDatenAnfrage(url) {
  return /\/rest\/v1\//.test(url);
}

(function fetchUmlegen() {
  if (window.__offlineAktiv) return;
  window.__offlineAktiv = true;
  const echt = window.fetch.bind(window);

  window.fetch = async function (eingabe, optionen) {
    const url = typeof eingabe === "string" ? eingabe : (eingabe && eingabe.url) || "";
    if (!istDatenAnfrage(url)) return echt(eingabe, optionen);

    const methode = String((optionen && optionen.method)
      || (eingabe && eingabe.method) || "GET").toUpperCase();
    const kopf = new Headers((optionen && optionen.headers) || (eingabe && eingabe.headers) || {});
    if (kopf.get("authorization")) OFFLINE.auth = kopf.get("authorization");
    if (kopf.get("apikey")) OFFLINE.apikey = kopf.get("apikey");

    // ---------- Lesen ----------
    if (methode === "GET" || methode === "HEAD") {
      try {
        const antwort = await echt(eingabe, optionen);
        if (antwort.ok && methode === "GET") {
          try {
            const c = await caches.open(OFFLINE.cache);
            await c.put(url, antwort.clone());
            localStorage.setItem(OFFLINE.standZeit, new Date().toISOString());
          } catch (f) { /* Speicher voll oder nicht erlaubt */ }
        }
        offlineStatus(false);
        return antwort;
      } catch (netzfehler) {
        offlineStatus(true);
        try {
          const c = await caches.open(OFFLINE.cache);
          const gemerkt = await c.match(url);
          if (gemerkt) return gemerkt;
        } catch (f) { /* nichts gemerkt */ }
        throw netzfehler;
      }
    }

    // ---------- Schreiben ----------
    let koerper = optionen && optionen.body;
    if (koerper && typeof koerper !== "string") {
      try { koerper = await new Response(koerper).text(); } catch (f) { koerper = null; }
    }

    const inSchlange = () => {
      const liste = offlineSchlange();
      liste.push({ zeit: new Date().toISOString(), methode: methode, url: url,
                   koerper: koerper || null,
                   prefer: kopf.get("prefer") || null,
                   typ: kopf.get("content-type") || "application/json" });
      offlineSchlangeSetzen(liste);
      // Eine Antwort, mit der die App weiterarbeiten kann: das, was
      // geschrieben werden sollte, als hätte der Server es bestätigt
      let echo = "[]";
      try {
        const d = koerper ? JSON.parse(koerper) : null;
        echo = JSON.stringify(Array.isArray(d) ? d : (d ? [d] : []));
      } catch (f) { /* bleibt leer */ }
      return new Response(methode === "DELETE" ? "" : echo, {
        status: methode === "DELETE" ? 204 : 201,
        headers: { "content-type": "application/json", "x-offline": "1" } });
    };

    // Warten schon Änderungen, kommt diese dahinter — sonst stimmt
    // die Reihenfolge nicht mehr
    if (OFFLINE.offline || offlineSchlange().length) return inSchlange();

    try {
      const antwort = await echt(eingabe, optionen);
      offlineStatus(false);
      return antwort;
    } catch (netzfehler) {
      offlineStatus(true);
      return inSchlange();
    }
  };
  OFFLINE.echt = echt;
})();

// Die Warteschlange abarbeiten, sobald wieder Netz da ist
async function offlineNachsenden() {
  if (OFFLINE.sendet) return;
  let liste = offlineSchlange();
  if (!liste.length) return;
  OFFLINE.sendet = true;
  offlineHinweis();
  let gesendet = 0;
  try {
    while (liste.length) {
      const e = liste[0];
      const kopf = { "content-type": e.typ || "application/json" };
      if (OFFLINE.auth) kopf.authorization = OFFLINE.auth;
      if (OFFLINE.apikey) kopf.apikey = OFFLINE.apikey;
      if (e.prefer) kopf.prefer = e.prefer;
      let antwort;
      try {
        antwort = await OFFLINE.echt(e.url, { method: e.methode, headers: kopf,
                                              body: e.koerper || undefined });
      } catch (netzfehler) { offlineStatus(true); break; }       // wieder weg
      if (!antwort.ok) {
        // Der Server lehnt ab — nicht endlos wiederholen, sondern
        // festhalten und weiter mit dem Rest
        let text = "";
        try { text = await antwort.text(); } catch (f) { /* egal */ }
        fehlerMerken("Offline nachgesendet, abgelehnt",
          e.methode + " " + e.url.split("/rest/v1/")[1], text.slice(0, 300));
      } else {
        gesendet++;
      }
      liste.shift();
      offlineSchlangeSetzen(liste);
    }
  } finally {
    OFFLINE.sendet = false;
    offlineHinweis();
  }
  if (gesendet) {
    meldung(gesendet === 1 ? "1 Änderung nachgesendet." : gesendet + " Änderungen nachgesendet.");
    stammVergessen();
    if (typeof zeichneSeite === "function") zeichneSeite();
  }
}

function offlineStatus(weg) {
  if (OFFLINE.offline === weg) return;
  OFFLINE.offline = weg;
  offlineHinweis();
  if (!weg) offlineNachsenden();
}

window.addEventListener("online", () => { offlineStatus(false); offlineNachsenden(); });
window.addEventListener("offline", () => offlineStatus(true));
// Auch ohne Ereignis regelmässig prüfen — manche Tablets melden es nicht
setInterval(() => {
  if (offlineSchlange().length && navigator.onLine) offlineNachsenden();
}, 30000);

// Der Hinweis oben: offline, Stand, wartende Änderungen
function offlineHinweis() {
  let el = document.getElementById("offline-hinweis");
  const warten = offlineSchlange().length;
  const zeigen = OFFLINE.offline || warten || OFFLINE.sendet;
  if (!zeigen) { if (el) el.remove(); return; }
  if (!el) {
    el = document.createElement("div");
    el.id = "offline-hinweis";
    document.body.appendChild(el);
  }
  const stand = localStorage.getItem(OFFLINE.standZeit);
  el.className = "offline-hinweis" + (OFFLINE.offline ? " offline-hinweis--weg" : "");
  el.innerHTML = OFFLINE.sendet
    ? '<span>⟳ Änderungen werden übertragen …</span>'
    : (OFFLINE.offline
        ? '<b>Offline</b><span>Stand ' + (stand ? esc(datumZeitKurz(stand)) : "unbekannt") + '</span>'
        : '<b>Wieder online</b>')
      + (warten ? '<span class="offline-hinweis__zahl">' + warten
          + (warten === 1 ? " Änderung wartet" : " Änderungen warten") + '</span>' : "");
}

// Beim Start: noch wartende Änderungen vom letzten Mal?
setTimeout(() => { offlineHinweis(); if (navigator.onLine) offlineNachsenden(); }, 1500);

// Die App selbst auf dem Gerät halten, damit sie ohne Netz startet
if ("serviceWorker" in navigator && location.protocol === "https:") {
  navigator.serviceWorker.register("./sw.js").catch(() => { /* ohne geht es auch */ });
}

// =================================================================
//  EXTERNE GERÄTE
//  Partner wie Zurbrügg öffnen die App über einen eigenen Link mit
//  "#/extern". Das Gerät merkt sich das. Dort zeigt die Anmeldung keine
//  Kacheln eurer Leute, sondern nur die Konten, die sich auf genau
//  diesem Gerät schon angemeldet haben — beim ersten Mal also nur
//  E-Mail und Passwort, danach die eigene Kachel.
// =================================================================

const GERAET_SCHLUESSEL = "hofer.geraet";
const GERAET_KONTEN = "hofer.geraet.konten";

(function geraetMarkieren() {
  try {
    if (/^#\/?extern\b/i.test(location.hash) || /[?&]geraet=extern\b/i.test(location.search)) {
      localStorage.setItem(GERAET_SCHLUESSEL, "extern");
      history.replaceState(null, "", location.pathname);
    }
    // Umgekehrt: "#/intern" macht ein versehentlich markiertes Gerät
    // wieder zu einem eigenen
    if (/^#\/?intern\b/i.test(location.hash) || /[?&]geraet=intern\b/i.test(location.search)) {
      localStorage.removeItem(GERAET_SCHLUESSEL);
      history.replaceState(null, "", location.pathname);
    }
  } catch (f) { /* ohne Speicher bleibt es ein normales Gerät */ }
})();

function istExternGeraet() {
  try { return localStorage.getItem(GERAET_SCHLUESSEL) === "extern"; } catch (f) { return false; }
}

function geraetKontoMerken(email) {
  try {
    const e = String(email || "").trim().toLowerCase();
    if (!e) return;
    const liste = JSON.parse(localStorage.getItem(GERAET_KONTEN) || "[]");
    if (liste.indexOf(e) === -1) liste.push(e);
    localStorage.setItem(GERAET_KONTEN, JSON.stringify(liste));
  } catch (f) { /* egal */ }
}

function geraetKonten() {
  try { return JSON.parse(localStorage.getItem(GERAET_KONTEN) || "[]"); } catch (f) { return []; }
}

// =================================================================
//  FEHLERPROTOKOLL
//  Jede Fehlermeldung, die jemand zu sehen bekommt, und jeder Fehler
//  im Hintergrund landet hier: mit Zeit, Person, Seite und Wortlaut.
//  Die letzten 200 bleiben auf dem Gerät. In den Einstellungen lässt
//  sich die Liste ansehen und als Datei herunterladen.
// =================================================================

const FEHLER_SCHLUESSEL = "hofer.fehlerprotokoll";
const FEHLER_HOECHSTENS = 200;

function fehlerLesen() {
  try { return JSON.parse(localStorage.getItem(FEHLER_SCHLUESSEL) || "[]"); }
  catch (f) { return []; }
}

function fehlerMerken(art, text, zusatz) {
  try {
    const liste = fehlerLesen();
    const eintrag = {
      zeit: new Date().toISOString(),
      art: art,
      text: String(text || "").slice(0, 600),
      seite: (location.hash || "#start").replace(/^#\/?/, "") || "start",
      person: (typeof profil !== "undefined" && profil)
        ? (profil.full_name || profil.email || "") : "",
      version: typeof APP_VERSION !== "undefined" ? APP_VERSION : "",
      geraet: (navigator.userAgent.match(/iPad|iPhone|Android|Windows|Macintosh/) || ["?"])[0],
    };
    if (zusatz) eintrag.zusatz = String(zusatz).slice(0, 800);
    // Gleiche Meldung kurz hintereinander nur einmal
    const letzte = liste[liste.length - 1];
    if (letzte && letzte.text === eintrag.text
        && Date.now() - new Date(letzte.zeit).getTime() < 3000) return;
    liste.push(eintrag);
    while (liste.length > FEHLER_HOECHSTENS) liste.shift();
    localStorage.setItem(FEHLER_SCHLUESSEL, JSON.stringify(liste));
  } catch (f) { /* Protokoll darf nie selbst stören */ }
}

window.addEventListener("error", (e) => {
  fehlerMerken("Programmfehler", e.message,
    (e.filename ? e.filename.split("/").pop() : "") + (e.lineno ? ":" + e.lineno : ""));
});
window.addEventListener("unhandledrejection", (e) => {
  const g = e.reason;
  fehlerMerken("Programmfehler", (g && (g.message || g.error_description)) || String(g),
    g && g.stack ? String(g.stack).split("\n").slice(0, 3).join(" | ") : "");
});

function fehlerAlsDatei() {
  const liste = fehlerLesen();
  const zeilen = ["Zeit;Art;Seite;Person;Version;Gerät;Meldung;Zusatz"].concat(
    liste.map((e) => [e.zeit, e.art, e.seite, e.person, e.version, e.geraet,
                      e.text, e.zusatz || ""]
      .map((v) => '"' + String(v || "").replace(/"/g, '""') + '"').join(";")));
  const blob = new Blob(["\ufeff" + zeilen.join("\r\n")], { type: "text/csv;charset=utf-8" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = "Fehlerprotokoll_" + isoDatum(new Date()) + ".csv";
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 2000);
}

function meldung(text, art) {
  if (art === "fehler") fehlerMerken("Meldung", text);
  stempelAuffrischen();
  let box = document.querySelector(".toast-bereich");
  if (!box) {
    box = document.createElement("div");
    box.className = "toast-bereich";
    document.body.appendChild(box);
  }
  const t = document.createElement("div");
  t.className = "toast toast--" + (art || "ok");
  t.textContent = text;
  box.appendChild(t);
  setTimeout(() => t.classList.add("toast--weg"), 3200);
  setTimeout(() => t.remove(), 3600);
}

