// Einstellungen, die nur dieses Gerät betreffen
// Einstellungen hängen am Konto, nicht am Gerät. Der Zwischenspeicher
// im Browser bleibt trotzdem gefüllt, damit die App beim Start sofort
// richtig aussieht, bevor das Profil geladen ist.
// Einstellungen gehören zur Person, nicht zum Gerät. Am Konto
// gespeichert gelten sie überall; auf dem Gerät wird je Person ein
// eigener Zwischenspeicher geführt. So bekommt an einem geteilten PC
// niemand mehr die Höhe oder die Tage seines Vorgängers.
function einstellungSchluessel(name) {
  return "hudson." + (profil && profil.id ? profil.id + "." : "") + name;
}

function einstellungRoh(name) {
  if (profil && profil.einstellungen && profil.einstellungen[name] !== undefined) {
    return String(profil.einstellungen[name]);
  }
  try { return localStorage.getItem(einstellungSchluessel(name)); }
  catch (e) { return null; }
}

function einstellung(name) {
  const w = einstellungRoh(name);
  return w === "true" || w === "1";
}

function einstellungWert(name, standard) {
  const w = einstellungRoh(name);
  return w === null || w === undefined ? standard : w;
}

// Schreibt in den Zwischenspeicher dieser Person und ans Konto
function einstellungAblegen(name, wert) {
  try { localStorage.setItem(einstellungSchluessel(name), String(wert)); }
  catch (e) { /* im privaten Modus nicht verfügbar */ }

  if (!profil || !profil.id || !db) return;
  profil.einstellungen = profil.einstellungen || {};
  profil.einstellungen[name] = wert;

  db.from("profiles").update({ einstellungen: profil.einstellungen })
    .eq("id", profil.id)
    .then((r) => {
      // Sichtbar im Fehlerprotokoll, nicht nur in der Entwicklerkonsole
      if (r && r.error) fehlerMerken("Einstellung nicht am Konto gespeichert", name + ": " + r.error.message);
    });
}

// Nach dem An- oder Abmelden gelten die Werte der neuen Person
function einstellungenNeuLesen() {
  try {
    plan.tageWunsch = null;
    plan.vskala = null;
    plan.breiteFest = false;
  } catch (f) { /* beim allerersten Start gibt es die Planwand noch nicht */ }
}

// Gewählte Themenfarbe, gemerkt wie die übrigen Einstellungen
function themaJetzt() {
  return einstellungWert("thema", "blau") || "blau";
}

function themaSetzen(wert) {
  einstellungSetzenWert("thema", wert);
  themaAnwenden();
}

function themaAnwenden() {
  const w = themaJetzt();
  if (w === "blau") document.body.removeAttribute("data-thema");
  else document.body.setAttribute("data-thema", w);
}

function einstellungSetzenWert(name, wert) {
  einstellungAblegen(name, String(wert));
}

function einstellungSetzen(name, wert) {
  einstellungAblegen(name, wert ? "1" : "0");
}

function fehlertext(e) {
  if (!e) return "Unbekannter Fehler";
  const m = e.message || String(e);
  if (m.includes("Invalid login credentials")) return "E-Mail oder Passwort stimmt nicht.";
  if (m.includes("Email not confirmed")) return "Die E-Mail-Adresse wurde noch nicht bestätigt.";
  if (m.includes("idx_jobs_fa_eindeutig")) {
    return "Diese FA Nr. ist schon auf einem anderen Auftrag. "
      + "Jede Nummer gibt es nur einmal.";
  }
  if (m.includes("Password should be")) {
    // Diese Schranke sitzt in Supabase selbst, nicht in der App.
    return "Supabase lehnt das Passwort ab. Die Mindestlänge steht dort unter "
      + "Authentication → Policies und lässt sich auf 1 setzen.";
  }
  if (m.includes("row-level security")) return "Dafür fehlen dir die Rechte.";
  if (m.includes("Failed to fetch")) return "Keine Verbindung zum Server. WLAN prüfen.";
  if (m.includes("foreign key") || m.includes("violates foreign key"))
    return "Das lässt sich nicht löschen, weil noch Buchungen oder Bestellungen daran hängen. "
         + "Deaktivieren geht aber immer.";
  if (m.includes("idx_jobs_laeuft") || m.includes("idx_jobs_laufend"))
    return "Auf dieser Maschine läuft bereits ein Auftrag. "
         + "Beende ihn zuerst oder setze ihn auf einen anderen Zustand.";
  if (m.includes("duplicate key")) return "Dieser Eintrag existiert bereits.";
  if (m.includes("duplicate key") || m.includes("bereits vorhanden"))
    return "Dieser Eintrag existiert bereits.";
  if (m.includes("foreign key"))
    return "Das lässt sich nicht löschen, weil noch Daten daran hängen "
         + "(zum Beispiel Bestände, Bewegungen oder Bestellungen). "
         + "Bitte stattdessen deaktivieren.";
  return m;
}

