const ANBIETER = [
  "https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm",
  "https://esm.sh/@supabase/supabase-js@2",
];

let db = null;

async function verbinden() {
  let letzter = null;
  for (const adresse of ANBIETER) {
    try {
      const modul = await zeitlimit(import(adresse), 8000, "Bibliothek");
      if (modul && modul.createClient) {
        return modul.createClient(SUPABASE_URL, SUPABASE_KEY, {
          auth: {
            persistSession: true,
            autoRefreshToken: true,
            detectSessionInUrl: true,
            // Die Browsersperre wird umgangen. Sie kann sich in
            // manchen Browsern selbst blockieren, und dann antwortet
            // die Anmeldung nie.
            lock: async (_n, _t, aufgabe) => await aufgabe(),
          },
        });
      }
    } catch (f) {
      letzter = f;
      console.warn("Anbieter nicht erreichbar:", adresse, f.message);
    }
  }
  throw new Error("Programmbibliothek nicht ladbar. " + (letzter ? letzter.message : ""));
}

