// =================================================================
//  SOLARANLAGE
//  Zeigt, was die Anlage gerade erzeugt, was der Betrieb zieht und
//  ob gerade eingespeist oder bezogen wird. Die Werte kommen aus
//  der Tabelle solar_werte, gefüllt von aussen.
// =================================================================

// Welche Spanne der Verlauf zeigt: Tag, Woche oder Monat
let solarSpanne = "tag";

// Längere Spannen: alle Messwerte holen, blockweise, und zu Stunden-
// oder Tagesmitteln verdichten — sonst wird die Kurve unlesbar und
// die Seite langsam.
async function solarVerlaufLaden(spanne) {
  const tage = spanne === "monat" ? 30 : 7;
  const seit = new Date(Date.now() - tage * 24 * 3600 * 1000).toISOString();
  const alle = [];
  for (let von = 0; von < 60000; von += 1000) {
    const { data, error } = await zeitlimit(
      db.from("solar_werte").select("gemessen, produktion_w, verbrauch_w")
        .gte("gemessen", seit).order("gemessen", { ascending: true })
        .range(von, von + 999),
      12000, "Solarverlauf");
    if (error) throw error;
    alle.push(...(data || []));
    if (!data || data.length < 1000) break;
  }
  const schritt = spanne === "monat" ? 24 * 3600 * 1000 : 3600 * 1000;
  const eimer = new Map();
  alle.forEach((x) => {
    const t = new Date(x.gemessen).getTime();
    const k = Math.floor(t / schritt) * schritt;
    const e = eimer.get(k) || { n: 0, p: 0, v: 0 };
    e.n += 1; e.p += Number(x.produktion_w) || 0; e.v += Number(x.verbrauch_w) || 0;
    eimer.set(k, e);
  });
  return [...eimer.entries()].sort((a, b) => a[0] - b[0]).map(([k, e]) => ({
    gemessen: new Date(k + schritt / 2).toISOString(),
    produktion_w: e.p / e.n, verbrauch_w: e.v / e.n,
  }));
}

async function solarLaden() {
  const seit = new Date(Date.now() - 24 * 3600 * 1000).toISOString();
  const { data, error } = await zeitlimit(
    db.from("solar_werte").select("*").gte("gemessen", seit)
      .order("gemessen", { ascending: true }).limit(600),
    10000, "Solarwerte");
  if (error) throw error;
  return data || [];
}

function solarKw(w) {
  const z = Number(w) || 0;
  if (Math.abs(z) >= 1000) return (z / 1000).toFixed(2).replace(".", ",") + " kW";
  return Math.round(z) + " W";
}

// Der Fluss: Anlage → Betrieb → Netz. Die Linien sind bewegt, die
// Geschwindigkeit richtet sich nach der Leistung — man sieht auf
// einen Blick, wo gerade viel unterwegs ist.
function solarFluss(j) {
  const prod = Number(j.produktion_w) || 0;
  const verb = Number(j.verbrauch_w) || 0;
  const netz = Number(j.netz_w) || 0;
  const bezug = netz > 0;
  const eigen = Math.max(0, Math.min(prod, verb));
  const anteil = verb > 0 ? Math.round((eigen / verb) * 100) : 0;
  const gross = Math.max(1, prod, verb, Math.abs(netz));

  // Je mehr Leistung, desto schneller läuft die Linie
  const tempo = (w) => (6 - (Math.abs(w) / gross) * 4.4).toFixed(2) + "s";
  const dick = (w) => (2.5 + (Math.abs(w) / gross) * 4).toFixed(1);

  const ring = 2 * Math.PI * 34;
  const gefuellt = (ring * Math.min(100, anteil)) / 100;

  return '<div class="sol">'
    + '<div class="sol__karten">'

    // Erzeugung
    + '<div class="sol-kachel sol-kachel--sonne">'
    + '<svg viewBox="0 0 24 24" class="sol-sym"><circle cx="12" cy="12" r="5"/>'
    + '<path d="M12 2v3M12 19v3M2 12h3M19 12h3M4.9 4.9l2.1 2.1M17 17l2.1 2.1'
    + 'M17 7l2.1-2.1M4.9 19.1L7 17" stroke-linecap="round"/></svg>'
    + '<span class="sol-kachel__name">Erzeugung</span>'
    + '<span class="sol-kachel__wert">' + solarKw(prod) + '</span>'
    + '</div>'

    // Verbrauch
    + '<div class="sol-kachel sol-kachel--haus">'
    + '<svg viewBox="0 0 24 24" class="sol-sym">'
    + '<path d="M3 11l9-7 9 7v9a1 1 0 01-1 1H4a1 1 0 01-1-1z"/>'
    + '<path d="M9 21v-6h6v6"/></svg>'
    + '<span class="sol-kachel__name">Verbrauch</span>'
    + '<span class="sol-kachel__wert">' + solarKw(verb) + '</span>'
    + '</div>'

    // Netz
    + '<div class="sol-kachel ' + (bezug ? "sol-kachel--bezug" : "sol-kachel--speisung")
    + '">'
    + '<svg viewBox="0 0 24 24" class="sol-sym">'
    + (bezug
        ? '<path d="M13 2L4 14h6l-1 8 9-12h-6z" stroke-linejoin="round"/>'
        : '<path d="M12 21V8M12 3v2M7 8h10M8 12h8M9 16h6" stroke-linecap="round"/>')
    + '</svg>'
    + '<span class="sol-kachel__name">' + (bezug ? "Netzbezug" : "Einspeisung") + '</span>'
    + '<span class="sol-kachel__wert">' + solarKw(Math.abs(netz)) + '</span>'
    + '</div>'
    + '</div>'

    // Die Verbindungen dazwischen
    + '<svg viewBox="0 0 440 60" class="sol-fluss" preserveAspectRatio="none">'
    + (eigen > 1
        ? '<path d="M78 30H210" class="sol-linie sol-linie--sonne" stroke-width="'
          + dick(eigen) + '" style="--tempo:' + tempo(eigen) + '"/>' : "")
    + (Math.abs(netz) > 1
        ? (bezug
            ? '<path d="M362 30H230" class="sol-linie sol-linie--bezug" stroke-width="'
              + dick(netz) + '" style="--tempo:' + tempo(netz) + '"/>'
            : '<path d="M230 30H362" class="sol-linie sol-linie--speisung" stroke-width="'
              + dick(netz) + '" style="--tempo:' + tempo(netz) + '"/>')
        : "")
    + '</svg>'

    // Eigenverbrauch als Ring
    + '<div class="sol-ring">'
    + '<svg viewBox="0 0 80 80">'
    + '<circle cx="40" cy="40" r="34" class="sol-ring__spur"/>'
    + '<circle cx="40" cy="40" r="34" class="sol-ring__voll"'
    + ' stroke-dasharray="' + gefuellt.toFixed(1) + ' ' + ring.toFixed(1) + '"/>'
    + '</svg>'
    + '<div class="sol-ring__mitte"><span class="sol-ring__zahl">' + anteil
    + '<small>%</small></span></div>'
    + '</div>'
    + '<p class="sol-ring__text">vom Dach gedeckt</p>'
    + '</div>';
}

// Verlauf des Tages als Flächengrafik: Erzeugung gefüllt, Verbrauch
// als Linie darüber. Gezeichnet wird als SVG, ohne fremde Bibliothek.
function solarVerlauf(reihe) {
  const punkte = (reihe || []).filter((x) => x && x.gemessen);
  if (punkte.length < 2) return "";

  const B = 600, H = 120;                       // Zeichenfläche
  const zeit = (x) => new Date(x.gemessen).getTime();
  const t0 = zeit(punkte[0]), t1 = zeit(punkte[punkte.length - 1]);
  const spanne = Math.max(1, t1 - t0);
  const gross = Math.max(1000,
    ...punkte.map((x) => Math.max(Number(x.produktion_w) || 0, Number(x.verbrauch_w) || 0)));

  const x = (p) => ((zeit(p) - t0) / spanne) * B;
  const y = (w) => H - ((Number(w) || 0) / gross) * (H - 6) - 3;

  const linie = (feld) => punkte
    .map((p, i) => (i ? "L" : "M") + x(p).toFixed(1) + " " + y(p[feld]).toFixed(1))
    .join(" ");

  const flaeche = linie("produktion_w")
    + " L" + B + " " + H + " L0 " + H + " Z";

  // Stundenraster, damit man die Tageszeit einordnen kann
  const striche = [];
  for (let k = 1; k < 6; k++) {
    const px = (B / 6) * k;
    striche.push('<line x1="' + px + '" y1="0" x2="' + px + '" y2="' + H
      + '" class="sol-gitter"/>');
  }

  // Beschriftung passend zur Spanne: Uhrzeit am Tag, Datum sonst
  const langeSpanne = spanne > 30 * 3600 * 1000;
  const vonU = langeSpanne ? kurzDatum(isoDatum(new Date(punkte[0].gemessen)))
    : uhrzeit(punkte[0].gemessen);
  const bisU = langeSpanne ? kurzDatum(isoDatum(new Date(punkte[punkte.length - 1].gemessen)))
    : uhrzeit(punkte[punkte.length - 1].gemessen);

  return '<div class="sol-verlauf">'
    + '<svg viewBox="0 0 ' + B + ' ' + H + '" preserveAspectRatio="none">'
    + '<defs><linearGradient id="solFuellung" x1="0" y1="0" x2="0" y2="1">'
    + '<stop offset="0%" stop-color="#ffc940" stop-opacity=".55"/>'
    + '<stop offset="100%" stop-color="#ffc940" stop-opacity="0"/>'
    + '</linearGradient></defs>'
    + striche.join("")
    + '<path d="' + flaeche + '" class="sol-flaeche"/>'
    + '<path d="' + linie("produktion_w") + '" class="sol-kurve sol-kurve--prod"/>'
    + '<path d="' + linie("verbrauch_w") + '" class="sol-kurve sol-kurve--verb"/>'
    + '</svg>'
    + '<div class="sol-verlauf__achse"><span>' + esc(vonU) + '</span>'
    + '<span class="sol-verlauf__mitte">'
    + '<span class="sol-spanne">'
    + [["tag", "Tag"], ["woche", "Woche"], ["monat", "Monat"]].map(([w, t]) =>
        '<button type="button" class="sol-spanne__knopf'
        + ((solarSpanne || "tag") === w ? " aktiv" : "") + '" data-solspanne="' + w + '">'
        + t + '</button>').join("")
    + '</span></span>'
    + '<span>' + esc(bisU) + '</span></div>'
    + '</div>';
}

function uhrzeit(iso) {
  try {
    return new Date(iso).toLocaleTimeString("de-CH",
      { hour: "2-digit", minute: "2-digit" });
  } catch (f) { return ""; }
}

async function solarKachel(ziel) {
  let reihe = [];
  try { reihe = await solarLaden(); }
  catch (f) {
    // Genau sagen, woran es liegt — sonst sucht man im Dunkeln
    const text = fehlertext(f);
    ziel.innerHTML = '<section class="karte"><h2>Solaranlage</h2>'
      + '<p class="hinweis">' + esc(text) + '</p>'
      + '<p class="klein">'
      + (/relation|does not exist|schema cache/i.test(text)
          ? "Die Tabelle solar_werte fehlt. Bitte solar.sql im SQL-Editor ausführen."
          : (/permission|policy|row-level/i.test(text)
              ? "Die Leseregel greift nicht. In solar.sql steht die Regel dafür — "
                + "bitte die Datei noch einmal ausführen."
              : "Falls das SQL schon gelaufen ist, schick mir diese Meldung."))
      + '</p></section>';
    return;
  }

  if (!reihe.length) {
    ziel.innerHTML = '<section class="karte"><h2>Solaranlage</h2>'
      + '<p class="hinweis">Noch keine Werte eingetroffen. Sobald etwas in die '
      + 'Tabelle geschrieben wird, erscheint hier die Anzeige.</p></section>';
    return;
  }

  const j = reihe[reihe.length - 1];
  const sek = Math.round((Date.now() - new Date(j.gemessen).getTime()) / 1000);
  const alt = Math.round(sek / 60);

  const prod = Number(j.produktion_w) || 0;
  const verb = Number(j.verbrauch_w) || 0;
  const netz = Number(j.netz_w) || 0;
  const bezug = netz > 0;
  const eigen = Math.max(0, Math.min(prod, verb));
  const anteil = verb > 0 ? Math.round((eigen / verb) * 100) : 0;
  const ring = 2 * Math.PI * 26;
  const gefuellt = (ring * Math.min(100, anteil)) / 100;

  const zahl = (wert, name, art) => '<div class="sol-zahl sol-zahl--' + art + '">'
    + '<span class="sol-zahl__name">' + name + '</span>'
    + '<span class="sol-zahl__wert">' + solarKw(wert) + '</span></div>';

  ladeFertig(ziel);
  ziel.innerHTML = '<section class="karte solar solar--schmal">'
    + '<div class="sol-kopf">'
    + '<span class="sol-kopf__titel">Solaranlage</span>'
    + '<span class="sol-kopf__stand">' + (alt < 2 ? "live" : "vor " + alt + " Min.") + '</span>'
    + '</div>'

    // Werte und Eigenverbrauch in einer Zeile
    + '<div class="sol-reihe">'
    + zahl(prod, "Erzeugung", "prod")
    + zahl(verb, "Verbrauch", "verb")
    + zahl(Math.abs(netz), bezug ? "Netzbezug" : "Einspeisung", bezug ? "bezug" : "speisung")
    + '<div class="sol-ring sol-ring--klein">'
    + '<svg viewBox="0 0 64 64">'
    + '<circle cx="32" cy="32" r="26" class="sol-ring__spur"/>'
    + '<circle cx="32" cy="32" r="26" class="sol-ring__voll"'
    + ' stroke-dasharray="' + gefuellt.toFixed(1) + ' ' + ring.toFixed(1) + '"/>'
    + '</svg>'
    + '<div class="sol-ring__mitte"><span class="sol-ring__zahl">' + anteil
    + '<small>%</small></span></div>'
    + '<span class="sol-ring__unten">Eigen</span>'
    + '</div>'
    + '</div>'

    + '<div id="sol-verlauf-platz">' + solarVerlauf(reihe) + '</div>'

    + '<div class="solar-tag">'
    + (j.ertrag_tag_kwh !== null && j.ertrag_tag_kwh !== undefined
        ? '<div><span>Ertrag heute</span>'
          + Number(j.ertrag_tag_kwh).toFixed(1).replace(".", ",") + ' kWh</div>' : "")
    + (j.eingespeist_tag_kwh !== null && j.eingespeist_tag_kwh !== undefined
        ? '<div><span>Eingespeist</span>'
          + Number(j.eingespeist_tag_kwh).toFixed(1).replace(".", ",") + ' kWh</div>' : "")
    + (j.bezug_tag_kwh !== null && j.bezug_tag_kwh !== undefined
        ? '<div><span>Bezogen</span>'
          + Number(j.bezug_tag_kwh).toFixed(1).replace(".", ",") + ' kWh</div>' : "")
    + '</div>'
    + '</section>';

  solarSpanneBinden(ziel, reihe);
}

// Umschalten zwischen Tag, Woche und Monat — nur der Verlauf wird
// neu gezeichnet, nicht die ganze Kachel
function solarSpanneBinden(ziel, reiheTag) {
  ziel.querySelectorAll("[data-solspanne]").forEach((el) => {
    el.onclick = async () => {
      solarSpanne = el.dataset.solspanne;
      const platz = ziel.querySelector("#sol-verlauf-platz");
      if (!platz) return;
      let reihe = reiheTag;
      if (solarSpanne !== "tag") {
        platz.classList.add("sol-laedt");
        try { reihe = await solarVerlaufLaden(solarSpanne); }
        catch (f) { meldung(fehlertext(f), "fehler"); platz.classList.remove("sol-laedt"); return; }
      }
      platz.innerHTML = solarVerlauf(reihe);
      platz.classList.remove("sol-laedt");
      solarSpanneBinden(ziel, reiheTag);
    };
  });
}

