// Alle betroffenen Aufträge in einem Fenster, nicht nur die nächsten
function vorbereitungFenster(liste, titel) {
  const heute = isoDatum(new Date());
  const sortiert = liste.slice().sort((a, c) =>
    String(a.planned_from || "").localeCompare(String(c.planned_from || "")));

  const huelle = document.createElement("div");
  huelle.className = "dialog-huelle";
  huelle.innerHTML = '<div class="dialog dialog--breit">'
    + '<div class="blatt__kopf"><h2>' + esc(titel) + '</h2>'
    + '<span class="marke">' + sortiert.length + '</span>'
    + '<button class="knopf knopf--still" data-zu>Schliessen</button></div>'
    + (sortiert.length
      ? '<table class="tabelle"><thead><tr><th>Auftrag</th><th>Maschine</th>'
        + '<th>Start</th><th>Fehlt</th></tr></thead><tbody>'
        + sortiert.map((j) => '<tr' + (j.planned_from && j.planned_from <= heute
              ? ' class="bz-zeile--spaet"' : "") + '>'
            + '<td><button class="linkknopf" data-vzeigen="' + esc(j.job_number)
            + '"><strong>' + esc(j.job_number) + '</strong></button></td>'
            + '<td>' + (j.maschine_nr
                ? '<b>' + esc(j.maschine_nr) + '</b> ' : "")
            + esc(j.maschine || "") + '</td>'
            + '<td class="nowrap">' + esc(kurzDatum(j.planned_from))
            + (j.planned_from && j.planned_from <= heute
                ? ' <span class="bz-spaet">läuft schon</span>' : "") + '</td>'
            + '<td class="nowrap">'
            + (!j.fa_erstellt ? '<span class="fehltchip">FA</span> ' : "")
            + (!j.material_ok ? '<span class="fehltchip">Material</span>' : "")
            + '</td></tr>').join("")
        + '</tbody></table>'
      : '<p class="hinweis">Nichts offen.</p>')
    + '<p class="klein">Ein Klick auf die Nummer springt zum Auftrag auf der '
    + 'Planwand.</p></div>';

  document.body.appendChild(huelle);
  const zu = () => huelle.remove();
  huelle.querySelector("[data-zu]").onclick = zu;
  dialogSchliessen(huelle, zu);

  huelle.querySelectorAll("[data-vzeigen]").forEach((el) => {
    el.onclick = () => { zu(); aufPlanwandZeigen(el.dataset.vzeigen); };
  });
}

function begruessung() {
  const h = new Date().getHours();
  if (h < 11) return "Guten Morgen";
  if (h < 18) return "Guten Tag";
  return "Guten Abend";
}



// =================================================================
//  DATENSICHERUNG
//  Lädt alle Daten als eine Datei herunter. Wichtig, weil der
//  kostenlose Tarif keine automatischen Sicherungen macht.
// =================================================================

const SICHERUNG_TABELLEN = [
  "profiles", "machine_parks", "machines", "jobs", "production_records",
  "suppliers", "articles", "order_items", "todos",
  "shopping_items", "vacations",
];

async function datenSichern(knopf) {
  const urspruenglich = knopf.textContent;
  knopf.disabled = true;

  const alles = { erstellt_am: new Date().toISOString(), version: APP_VERSION, daten: {} };
  const fehler = [];

  for (let i = 0; i < SICHERUNG_TABELLEN.length; i++) {
    const t = SICHERUNG_TABELLEN[i];
    knopf.textContent = "Sichere … " + (i + 1) + "/" + SICHERUNG_TABELLEN.length;
    try {
      const { data, error } = await zeitlimit(db.from(t).select("*"), 20000, t);
      if (error) throw error;
      alles.daten[t] = data || [];
    } catch (f) {
      fehler.push(t);
      alles.daten[t] = { fehler: f.message };
    }
  }

  const datum = isoDatum(new Date());
  ladeHerunter(JSON.stringify(alles, null, 2),
    "hudson-tool-sicherung-" + datum + ".json", "application/json");

  // Zusätzlich die wichtigsten Tabellen als CSV für Excel
  const csvTabellen = ["articles", "stock_balances", "production_records", "order_items"];
  csvTabellen.forEach((t) => {
    const zeilen = alles.daten[t];
    if (Array.isArray(zeilen) && zeilen.length) {
      ladeHerunter(alsCsv(zeilen), "hudson-" + t + "-" + datum + ".csv", "text/csv");
    }
  });

  knopf.disabled = false;
  knopf.textContent = urspruenglich;

  if (fehler.length) meldung("Gesichert, aber nicht lesbar: " + fehler.join(", "), "warn");
  else meldung("Sicherung heruntergeladen.");
}

function alsCsv(zeilen) {
  const spalten = Object.keys(zeilen[0]);
  const feld = (w) => {
    if (w === null || w === undefined) return "";
    const t = typeof w === "object" ? JSON.stringify(w) : String(w);
    return /[";\n]/.test(t) ? '"' + t.replaceAll('"', '""') + '"' : t;
  };
  return "\uFEFF" + spalten.join(";") + "\n"
    + zeilen.map((z) => spalten.map((sp) => feld(z[sp])).join(";")).join("\n");
}

function ladeHerunter(inhalt, dateiname, art) {
  const blob = new Blob([inhalt], { type: art + ";charset=utf-8" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = dateiname;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 1000);
}

