// Auf welche Maschinenparks hat der angemeldete Benutzer Zugriff?
// Leere Liste heisst: alle.
function meineParks() {
  return (profil && Array.isArray(profil.parks)) ? profil.parks : [];
}

// Externe Partner sehen nur Parks, die ihnen zugewiesen sind — ohne
// Zuweisung die Parks mit "extern", "Lohn" oder "fremd" im Namen
function istExtern() { return meineRolle() === "extern"; }

function parkErlaubt(parkId) {
  if (istAdmin() || meineRolle() === "planwand") return true;
  if (istExtern()) {
    const zu = meineParks();
    if (zu.length) return zu.indexOf(parkId) !== -1;
    const park = (prod.parks || []).concat(plan.parksAlle || []).find((p) => p.id === parkId);
    return /extern|lohn|fremd/i.test(String((park && park.name) || ""));
  }

  // Ausdrücklich zugewiesene Parks haben Vorrang
  const zugewiesen = meineParks();
  if (zugewiesen.length) return zugewiesen.indexOf(parkId) !== -1;

  // Sonst entscheidet der Name des Parks zur Rolle
  const park = (prod.parks || []).concat(plan.parksAlle || [])
    .find((p) => p.id === parkId);
  const name = ((park && park.name) || "").toLowerCase();
  const r = meineRolle();
  if (r === "kurzdreher") return name.includes("kurz");
  if (r === "langdreher") return name.includes("lang");
  return true;
}

function meineRolle() { return (profil && profil.role) || "produktion"; }
function istAdmin() { return meineRolle() === "admin"; }
function darfSchreiben() {
  const r = meineRolle();
  return r === "admin" || r === "planwand"
    || r === "langdreher" || r === "kurzdreher";
}

// Mitarbeiter dürfen überall zusehen, aber nur im Einkauf mitmachen.
function darfEinkaufen() {
  return darfSchreiben() || meineRolle() === "mitarbeiter";
}

