// ---------- Datumshelfer ----------

function isoDatum(d) {
  const p = (n) => String(n).padStart(2, "0");
  return d.getFullYear() + "-" + p(d.getMonth() + 1) + "-" + p(d.getDate());
}

function ausIso(text) {
  const [j, m, t] = text.split("-").map(Number);
  return new Date(j, m - 1, t);
}

function plusTage(text, n) {
  const d = ausIso(text);
  d.setDate(d.getDate() + n);
  return isoDatum(d);
}

function wochenStart(text) {
  const d = ausIso(text);
  d.setDate(d.getDate() - ((d.getDay() + 6) % 7));
  return isoDatum(d);
}

// Kalenderwoche nach ISO
function kalenderwoche(text) {
  const d = ausIso(text);
  const ziel = new Date(d.getFullYear(), d.getMonth(), d.getDate());
  ziel.setDate(ziel.getDate() + 3 - ((ziel.getDay() + 6) % 7));
  const ersterDo = new Date(ziel.getFullYear(), 0, 4);
  ersterDo.setDate(ersterDo.getDate() + 3 - ((ersterDo.getDay() + 6) % 7));
  return 1 + Math.round((ziel - ersterDo) / (7 * 86400000));
}

function datumMitJahr(text) {
  if (!text) return "";
  const d = ausIso(text);
  return String(d.getDate()).padStart(2, "0") + "."
    + String(d.getMonth() + 1).padStart(2, "0") + "." + d.getFullYear();
}

// Datum mit Jahr, z. B. 04.09.2026
function langDatum(text) {
  if (!text) return "";
  const d = ausIso(text);
  const p2 = (n) => String(n).padStart(2, "0");
  return p2(d.getDate()) + "." + p2(d.getMonth() + 1) + "." + d.getFullYear();
}

function kurzDatum(text) {
  const d = ausIso(text);
  return String(d.getDate()).padStart(2, "0") + "." + String(d.getMonth() + 1).padStart(2, "0") + ".";
}

const WOCHENTAGE = ["Montag", "Dienstag", "Mittwoch", "Donnerstag", "Freitag", "Samstag", "Sonntag"];
const WT_KURZ = ["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"];
const MONATE = ["Januar", "Februar", "März", "April", "Mai", "Juni",
                "Juli", "August", "September", "Oktober", "November", "Dezember"];

function wochentagName(text) { return WOCHENTAGE[(ausIso(text).getDay() + 6) % 7]; }
// Zeichen für die Zielart einer Lieferung
function zielZeichen(art) {
  if (art === "maschine") return "⚙";
  if (art === "person") return "◉";
  if (art === "andere") return "→";
  return "▤";
}

function zahlText(n) { return Number(n || 0).toLocaleString("de-CH"); }

// Minuten als Stunden, ohne unnötige Nullen: 450 wird zu 7.5, 480 zu 8
function stundenText(minuten) {
  const h = (Number(minuten) || 0) / 60;
  return String(Math.round(h * 100) / 100);
}

// Anzeigename einer Person. Fehlt der hinterlegte Name, wird er aus
// der Mailadresse gebaut: tristan.ecker@… wird zu Tristan Ecker.
// Vorher stand dort die rohe Adresse, was unschön aussah.
function personName(p2, ersatz) {
  if (!p2) return ersatz || "unbekannt";
  const voll = (p2.full_name || "").trim();
  if (voll) return voll;

  const teil = String(p2.email || "").split("@")[0];
  if (!teil) return ersatz || "unbekannt";

  return teil.split(/[._-]+/).filter((x) => x)
    .map((x) => x.charAt(0).toUpperCase() + x.slice(1))
    .join(" ");
}

function leistungText(n) {
  if (n === null || n === undefined) return "";
  return (n > 0 ? "+" : "") + zahlText(n);
}

