// =================================================================
//  Kurzzeitgedächtnis für Stammdaten
//  Parks, Maschinen und Typen ändern sich selten, werden aber bei
//  jeder Kleinigkeit neu geholt. Das kostet auf dem Handy spürbar
//  Zeit. Sie werden deshalb kurz gemerkt und beim Ändern verworfen.
// =================================================================

const stammGedaechtnis = { werte: {}, zeit: {} };
const STAMM_MS = 30000;

async function stammGemerkt(schluessel, holen) {
  const jetzt = Date.now();
  if (stammGedaechtnis.werte[schluessel] !== undefined
      && jetzt - (stammGedaechtnis.zeit[schluessel] || 0) < STAMM_MS) {
    return stammGedaechtnis.werte[schluessel];
  }
  const wert = await holen();
  stammGedaechtnis.werte[schluessel] = wert;
  stammGedaechtnis.zeit[schluessel] = jetzt;
  return wert;
}

// Nach jeder Änderung an Parks, Maschinen oder Typen
function stammVergessen() {
  stammGedaechtnis.werte = {};
  stammGedaechtnis.zeit = {};
}

async function ladeParks(auchInaktive) {
  return stammGemerkt("parks" + (auchInaktive ? "-alle" : ""),
    () => ladeParksFrisch(auchInaktive));
}

async function ladeMaschinen(auchInaktive) {
  return stammGemerkt("maschinen" + (auchInaktive ? "-alle" : ""),
    () => ladeMaschinenFrisch(auchInaktive));
}

async function ladeParksFrisch(auchInaktive) {
  let a = db.from("machine_parks").select("*").order("name");
  if (!auchInaktive) a = a.eq("is_active", true);
  const { data, error } = await zeitlimit(a, 10000, "Maschinenparks");
  if (error) throw error;
  // Alle Parks merken, damit der Namensvergleich funktioniert
  plan.parksAlle = data || [];
  // Eigene Parks nach Name, externe Maschinen immer zuletzt
  const extern = (p) => /extern|lohn|fremd/i.test(String(p.name || "")) ? 1 : 0;
  return (data || []).filter((p) => parkErlaubt(p.id))
    .sort((a, b) => extern(a) - extern(b)
      || String(a.name || "").localeCompare(String(b.name || ""), "de"));
}

async function ladeMaschinenFrisch(auchInaktive) {
  let a = db.from("machines").select("*").order("sort_order").order("name");
  if (!auchInaktive) a = a.eq("is_active", true);
  const { data, error } = await zeitlimit(a, 10000, "Maschinen");
  if (error) throw error;
  return (data || []).filter((m) => parkErlaubt(m.park_id));
}

// Alle Maschinen, ohne Rücksicht auf die Parkzuweisung. Für die
// Produktion ist der Filter richtig — man sieht nur die eigenen
// Maschinen. Wohin eine Lieferung gehen soll, ist davon aber
// unabhängig: dort müssen alle zur Auswahl stehen.
async function ladeAlleMaschinen() {
  const { data, error } = await zeitlimit(
    db.from("machines").select("*").eq("is_active", true)
      .order("sort_order").order("name"),
    10000, "Maschinen");
  if (error) throw error;
  return data || [];
}

// Text, wie die Maschine in einer Bestellung steht
function maschineZielText(m) {
  return m.name + (m.machine_number ? " " + m.machine_number : "");
}

async function ladeLaufendeAuftraege() {
  const { data, error } = await zeitlimit(
    db.from("jobs").select("*").is("ended_at", null), 10000, "Aufträge");
  if (error) throw error;
  // Stehen mehrere offene Aufträge auf derselben Maschine (einer
  // läuft, ein anderer ist erst geplant), gewinnt immer der, der
  // wirklich läuft — sonst hing die Stückzahl-Erfassung zufällig
  // davon ab, welcher zuletzt aus der Datenbank kam.
  // Laufend ist nur, was auch auf "läuft" steht — dieselbe Wahrheit
  // wie auf der Planwand. Vorher genügte "noch nicht beendet", und so
  // zeigte die Produktion einen nur geplanten Auftrag als laufend an
  // und buchte die Stückzahl auf ihn.
  // An der Maschine ist, was läuft, gerüstet oder geprüft wird. Nur
  // "geplant" zählt nicht — sonst wanderte ein Auftrag aus der
  // Produktion, sobald man ihn auf Rüsten oder QS setzt.
  // Gibt es mehrere, hat "läuft" Vorrang, dann Rüsten, dann QS.
  const RANG = { laeuft: 3, ruesten: 2, qs: 1 };
  const karte = {};
  (data || []).forEach((j) => {
    const rang = RANG[j.plan_status] || 0;
    if (!rang) return;
    const vorhanden = karte[j.machine_id];
    const rangDa = vorhanden ? (RANG[vorhanden.plan_status] || 0) : -1;
    if (!vorhanden || rang > rangDa
        || (rang === rangDa && String(j.started_at || "") > String(vorhanden.started_at || ""))) {
      karte[j.machine_id] = j;
    }
  });
  await standsNachtragen(Object.values(karte));
  return karte;
}

// Holt Einträge im Zeitraum plus etwas Vorlauf, damit die
// Tagesleistung als Differenz berechnet werden kann.
async function ladeZaehlerstaende(von, bis, maschinenIds) {
  if (!maschinenIds.length) return { proSchluessel: {}, proMaschine: {} };

  const { data, error } = await zeitlimit(
    db.from("production_records")
      .select("machine_id, record_date, quantity, job_id, updated_at")
      .gte("record_date", plusTage(von, -120)).lte("record_date", bis)
      .in("machine_id", maschinenIds)
      .order("record_date"),
    12000, "Stückzahlen");
  if (error) throw error;

  const proMaschine = {};
  (data || []).forEach((z) => {
    (proMaschine[z.machine_id] = proMaschine[z.machine_id] || []).push(z);
  });

  // Tagesleistung = Differenz zum vorherigen Eintrag DESSELBEN Auftrags.
  // Seit ein Tag mehrere Zeilen je Maschine haben kann — eine je
  // Auftrag —, wird je Auftrag gezählt, nicht einfach der Vorgänger
  // in der Liste genommen.
  const proSchluessel = {};
  Object.keys(proMaschine).forEach((mid) => {
    const liste = proMaschine[mid];
    const letzter = {};
    const laeuft = (prod.auftraege && prod.auftraege[mid]) ? prod.auftraege[mid].id : null;
    liste.forEach((z) => {
      const vorher = letzter[z.job_id];
      z.leistung = vorher ? z.quantity - vorher.quantity : z.quantity;
      letzter[z.job_id] = z;

      // Genaue Ablage je Auftrag
      proSchluessel[mid + "|" + z.record_date + "|" + z.job_id] = z;

      // Für die Tagesansicht: gibt es an einem Tag mehrere Zeilen, zählt
      // die des laufenden Auftrags, sonst die zuletzt geänderte
      const k = mid + "|" + z.record_date;
      const da = proSchluessel[k];
      if (!da
          || (z.job_id === laeuft && da.job_id !== laeuft)
          || (da.job_id !== laeuft
              && String(z.updated_at || "") >= String(da.updated_at || ""))) {
        proSchluessel[k] = z;
      }
    });
  });

  return { proSchluessel: proSchluessel, proMaschine: proMaschine };
}

// Ein Zählerstand gehört zu Maschine, Tag UND Auftrag. Vorher war der
// Schlüssel nur Maschine und Tag: Wurde am selben Tag ein Auftrag
// beendet und der nächste gestartet, überschrieb die neue Eingabe die
// Zeile des alten — und hängte sie dabei auch noch an den neuen.
// Ist die Datenbank noch nicht umgestellt (stueckzahl.sql), greift
// der alte Schlüssel als Rückfall, damit das Speichern nicht bricht.
async function speichereStand(maschineId, datum, stand, auftragId) {
  const zeile = { machine_id: maschineId, record_date: datum,
                  quantity: stand, job_id: auftragId };
  let r = await zeitlimit(
    db.from("production_records").upsert(zeile,
      { onConflict: "machine_id,record_date,job_id" }),
    12000, "Speichern");
  if (r.error && /ON CONFLICT|unique or exclusion|no unique/i.test(r.error.message || "")) {
    r = await zeitlimit(
      db.from("production_records").upsert(zeile,
        { onConflict: "machine_id,record_date" }),
      12000, "Speichern");
  }
  if (r.error) throw r.error;
}

