// Samstag und Sonntag werden auf der Planwand übersprungen.
function istWochenende(datum) {
  const t = ausIso(datum).getDay();
  return t === 0 || t === 6;
}

function naechsterArbeitstag(datum) {
  let d = datum;
  while (istWochenende(d)) d = plusTage(d, 1);
  return d;
}

// Zählt n Arbeitstage weiter, Wochenenden übersprungen.
// Gleiches Ergebnis wie Tag für Tag zu zählen, aber in einem Sprung:
// fünf Arbeitstage sind immer eine volle Woche. Der Zeitregler fragt bei
// jedem Schritt bis zu 1'800 Arbeitstage weit — vorher wurde jeder Tag
// einzeln gerechnet. Ergebnisse werden zusätzlich gemerkt.
const arbeitstagePlusGemerkt = new Map();
function arbeitstagePlus(datum, n) {
  const schluessel = datum + "|" + n;
  const gemerkt = arbeitstagePlusGemerkt.get(schluessel);
  if (gemerkt) return gemerkt;
  let d = naechsterArbeitstag(datum);
  if (n >= 0) {
    // ganze Wochen auf einmal, den Rest Tag für Tag
    const wochen = Math.floor(n / 5);
    if (wochen > 0) d = plusTage(d, wochen * 7);
    for (let i = 0; i < n - wochen * 5; i++) { d = naechsterArbeitstag(plusTage(d, 1)); }
  } else {
    // Negative Werte gehen rückwärts, Wochenenden werden übersprungen
    const m = -n;
    const wochen = Math.floor(m / 5);
    if (wochen > 0) d = plusTage(d, -wochen * 7);
    for (let i = 0; i < m - wochen * 5; i++) {
      d = plusTage(d, -1);
      while ([0, 6].indexOf(ausIso(d).getDay()) !== -1) d = plusTage(d, -1);
    }
  }
  if (arbeitstagePlusGemerkt.size > 20000) arbeitstagePlusGemerkt.clear();
  arbeitstagePlusGemerkt.set(schluessel, d);
  return d;
}

// Liste von n Arbeitstagen ab einem Datum
// Dieselben Arbeitstage werden beim Zeichnen sehr oft gebraucht — einmal
// gerechnet, gemerkt. Zurück kommt immer eine eigene Kopie, damit niemand
// die gemerkte Liste versehentlich verändert.
const arbeitstageGemerkt = new Map();
function arbeitstage(ab, anzahl) {
  const schluessel = ab + "|" + anzahl;
  let liste = arbeitstageGemerkt.get(schluessel);
  if (!liste) {
    liste = [];
    let d = naechsterArbeitstag(ab);
    for (let i = 0; i < anzahl; i++) { liste.push(d); d = naechsterArbeitstag(plusTage(d, 1)); }
    if (arbeitstageGemerkt.size > 30000) arbeitstageGemerkt.clear();
    arbeitstageGemerkt.set(schluessel, liste);
  }
  return liste.slice();
}

// Grob vorab: Kann ein Eintrag überhaupt im gezeigten Zeitraum liegen?
// Fünf Arbeitstage sind höchstens neun Kalendertage, dazu ein Wochenende
// Luft. So muss nicht für jeden alten Auftrag gerechnet werden.
function koennteSichtbar(von, dauer, sichtVon, sichtBis) {
  if (!von || von > sichtBis) return false;
  const kalendertage = Math.ceil((Number(dauer) || 1) * 7 / 5) + 4;
  return plusTage(von, kalendertage) >= sichtVon;
}

// Erster freier Tag auf einer Maschine: hinter dem letzten geplanten Auftrag.
function naechsterFreierTag(maschineId) {
  const heute = naechsterArbeitstag(isoDatum(new Date()));
  const eigene = (plan.auftraege || []).filter(
    (j) => j.machine_id === maschineId && j.planned_from && j.plan_status !== "fertig");
  if (!eigene.length) return heute;

  let spaetestes = heute;
  eigene.forEach((j) => {
    const ende = arbeitstagePlus(j.planned_from, j.planned_days || 1);
    if (ende > spaetestes) spaetestes = ende;
  });
  return naechsterArbeitstag(spaetestes);
}

// Schriftfarbe zu einer Hintergrundfarbe: dunkel auf hell, hell auf dunkel
function schriftZu(hex) {
  const h = String(hex || "").replace("#", "");
  if (h.length !== 6) return "#fff";
  const r = parseInt(h.slice(0, 2), 16), g = parseInt(h.slice(2, 4), 16), b = parseInt(h.slice(4, 6), 16);
  return (0.299 * r + 0.587 * g + 0.114 * b) > 150 ? "#10161d" : "#fff";
}

function farbeVon(wert) {
  // Eine beliebige Farbe als Hexwert — so kommen die Farben aus
  // infoBoard unverändert auf die Wand
  if (/^#[0-9a-f]{6}$/i.test(String(wert || ""))) {
    const hex = String(wert).toLowerCase();
    return { wert: hex, name: hex, hex: hex, schrift: schriftZu(hex), material: "", buchstabe: "" };
  }
  const f = PLANFARBEN.find((x) => x.wert === wert) || PLANFARBEN[0];
  const zu = FARBZUTEILUNG[f.wert];
  // Material und Kürzel kommen aus der Zuteilung in den Einstellungen
  return { ...f, material: zu ? zu.material : "", buchstabe: zu ? (zu.buchstabe || "") : "" };
}

// Materialgrösse: erst der Durchmesser, dann die Toleranz.
// "Ø20h9", "20 h9", "Ø12g6" und "12" werden alle verstanden.
function groesseZerlegen(text) {
  const t = String(text || "").replace(",", ".").trim();
  // Die Zahl muss vorne stehen, sonst ist es keine Grösse:
  // "g6" allein wäre sonst als Durchmesser 6 gelesen worden.
  const m = t.match(/^[Ø⌀\s]*(\d+(?:\.\d+)?)\s*([A-Za-z]{1,3}\s*\d{0,2})?/);
  if (!m) return null;
  const tol = (m[2] || "").replace(/\s+/g, "").trim();
  return { dm: Number(m[1]), toleranz: tol || null };
}

function groesseBauen(dm, toleranz) {
  if (dm === null || dm === undefined || dm === "") return "";
  return "Ø" + dm + (toleranz ? " " + toleranz : "");
}

// Macht eine Farbe kräftig und leuchtend: Sättigung hoch, Helligkeit
// auf einen Wert, bei dem sie noch strahlt, aber Text darauf lesbar
// bleibt. Zurück kommt der Hintergrund und die passende Schriftfarbe.
function leuchtend(hex) {
  const h = String(hex || "#888888").replace("#", "");
  const voll = h.length === 3 ? h.split("").map((c) => c + c).join("") : h;
  const r = parseInt(voll.slice(0, 2), 16) / 255;
  const g = parseInt(voll.slice(2, 4), 16) / 255;
  const b = parseInt(voll.slice(4, 6), 16) / 255;

  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  let farbton = 0;
  const helle = (max + min) / 2;
  const spanne = max - min;
  let saettigung = spanne === 0 ? 0
    : spanne / (1 - Math.abs(2 * helle - 1));

  if (spanne !== 0) {
    if (max === r) farbton = ((g - b) / spanne) % 6;
    else if (max === g) farbton = (b - r) / spanne + 2;
    else farbton = (r - g) / spanne + 4;
    farbton *= 60;
    if (farbton < 0) farbton += 360;
  }

  // Sättigung anheben, Helligkeit auf ein kräftiges Mittel bringen.
  // Fast farblose Töne — Weiss, Grau — bleiben, wie sie sind.
  const sNeu = saettigung < 0.12 ? saettigung : Math.min(0.78, saettigung * 1.15 + 0.08);
  let lNeu = saettigung < 0.12 ? Math.max(helle, 0.82)
    : Math.min(0.74, Math.max(0.58, helle * 0.3 + 0.5));

  // Aus Ton, Sättigung und Helligkeit wieder eine Farbe machen
  const bauen = (l) => {
    const c = (1 - Math.abs(2 * l - 1)) * sNeu;
    const x = c * (1 - Math.abs(((farbton / 60) % 2) - 1));
    const m = l - c / 2;
    let rr = 0, gg = 0, bb = 0;
    if (farbton < 60) { rr = c; gg = x; }
    else if (farbton < 120) { rr = x; gg = c; }
    else if (farbton < 180) { gg = c; bb = x; }
    else if (farbton < 240) { gg = x; bb = c; }
    else if (farbton < 300) { rr = x; bb = c; }
    else { rr = c; bb = x; }
    const zahl = (v) => Math.max(0, Math.min(255, Math.round((v + m) * 255)));
    return [zahl(rr), zahl(gg), zahl(bb)];
  };

  // Die Schrift bleibt überall schwarz. Deshalb wird die Farbe nur so
  // kräftig, wie es dafür reicht — ist sie zu dunkel, wird sie
  // schrittweise aufgehellt, bis Schwarz darauf sicher lesbar ist.
  const wahrgenommen = ([r2, g2, b2]) => 0.299 * r2 + 0.587 * g2 + 0.114 * b2;
  let ton = bauen(lNeu);
  let schutz = 0;
  while (wahrgenommen(ton) < 168 && lNeu < 0.94 && schutz++ < 40) {
    lNeu += 0.02;
    ton = bauen(lNeu);
  }

  const hintergrund = "#" + ton
    .map((v) => v.toString(16).padStart(2, "0")).join("");
  return { hg: hintergrund, vg: "#10151c" };
}

// Mischt eine Farbe mit Weiss. anteil 0 = unverändert, 1 = weiss.
function aufhellen(hex, anteil) {
  const h = String(hex || "#888888").replace("#", "");
  const voll = h.length === 3 ? h.split("").map((c) => c + c).join("") : h;
  const misch = (i) => {
    const w = parseInt(voll.slice(i, i + 2), 16);
    return Math.round(w + (255 - w) * anteil).toString(16).padStart(2, "0");
  };
  return "#" + misch(0) + misch(2) + misch(4);
}

// ---------- Aufträge dürfen sich auf einer Maschine nicht überlagern ----------

// Letzter Arbeitstag eines Auftrags
function planEnde(von, tage) {
  return letzterArbeitstag(von, Math.max(1, tage || 1));
}

// Liegt der Zeitraum frei? Gibt sonst den störenden Auftrag zurück.
function planKonflikt(maschineId, von, tage, ausserId) {
  const bis = planEnde(von, tage);
  return (plan.auftraege || []).find((x) => {
    if (x.id === ausserId || x.machine_id !== maschineId || !x.planned_from) return false;
    const xBis = planEnde(x.planned_from, x.planned_days || 1);
    return x.planned_from <= bis && von <= xBis;
  }) || null;
}

// Schiebt nach hinten, bis der Zeitraum frei ist.
function freierStart(maschineId, wunsch, tage, ausserId) {
  let von = wunsch;
  for (let i = 0; i < 400; i++) {
    const stoerer = planKonflikt(maschineId, von, tage, ausserId);
    if (!stoerer) return von;
    von = naechsterArbeitstag(
      arbeitstagePlus(stoerer.planned_from, stoerer.planned_days || 1));
  }
  return von;
}

// Räumt eine Maschine auf: Der Auftrag mit der Kennung festId bleibt,
// wo er ist, alle anderen weichen ihm aus und rücken so weit nach
// hinten, wie nötig. Die Reihenfolge nach Datum bleibt erhalten.
// Gibt die alten Daten zurück, damit sich alles zurücknehmen lässt.
// Viele kleine Änderungen auf einmal abschicken, statt eine nach der
// anderen abzuwarten. Höchstens acht gleichzeitig, damit der Server
// nicht überrannt wird. Vorher dauerte ein Verschieben mit 25
// nachrückenden Aufträgen über drei Sekunden, jetzt ein paar Zehntel.
async function parallelSenden(aufgaben, gleichzeitig) {
  const liste = aufgaben.slice();
  let fehler = null;
  const arbeiter = Array.from({ length: Math.min(gleichzeitig || 8, liste.length) }, async () => {
    while (liste.length) {
      const a = liste.shift();
      try {
        const r = await a();
        if (r && r.error && !fehler) fehler = r.error;
      } catch (f) { if (!fehler) fehler = f; }
    }
  });
  await Promise.all(arbeiter);
  if (fehler) throw fehler;
}

// Rechnet aus, was einem fest gesetzten Auftrag ausweichen muss, und
// setzt es sofort in der Anzeige — ohne auf den Server zu warten.
// Gibt die Änderungen zurück; abgeschickt werden sie danach am Stück.
function planKonflikteRechnen(maschineId, festId) {
  planFliessenAnmelden();   // was ausweicht, gleitet statt zu springen
  const alle = (plan.auftraege || [])
    .filter((x) => x.machine_id === maschineId && x.planned_from
      // Abgeschlossene Aufträge bleiben, wo sie waren — die Geschichte
      // wird beim Verschieben nicht umgeschrieben
      && (x.id === festId || x.plan_status !== "fertig"))
    .sort((a, c) => a.planned_from < c.planned_from ? -1
      : (a.planned_from > c.planned_from ? 1 : String(a.id).localeCompare(String(c.id))));

  const gesetzt = [];
  const fest = alle.find((x) => x.id === festId);
  if (fest) gesetzt.push(fest);

  const vorher = [];

  for (const x of alle) {
    if (x.id === festId) continue;
    let von = x.planned_from;

    let nochmal = true, schutz = 0;
    while (nochmal && schutz++ < 400) {
      nochmal = false;
      for (const g of gesetzt) {
        const gBis = planEnde(g.planned_from, g.planned_days || 1);
        const xBis = planEnde(von, x.planned_days || 1);
        if (von <= gBis && g.planned_from <= xBis) {
          von = naechsterArbeitstag(
            arbeitstagePlus(g.planned_from, g.planned_days || 1));
          nochmal = true;
        }
      }
    }

    if (von !== x.planned_from) {
      vorher.push({ id: x.id, von: x.planned_from, nach: von });
      x.planned_from = von;
    }
    gesetzt.push(x);
  }
  return vorher;
}

async function planKonflikteLoesen(maschineId, festId) {
  const vorher = planKonflikteRechnen(maschineId, festId);
  await parallelSenden(vorher.map((v) => () =>
    db.from("jobs").update({ planned_from: v.nach }).eq("id", v.id)));
  return vorher;
}

// Packt alle offenen Aufträge einer Maschine ab einem Tag lückenlos
// hintereinander. Gibt die vorherigen Daten zurück, damit sich der
// Schritt zurücknehmen lässt.
async function planAufruecken(maschineId, abDatum, ausserId) {
  planFliessenAnmelden();
  const reihe = (plan.auftraege || [])
    .filter((x) => x.machine_id === maschineId && x.planned_from
      && x.id !== ausserId && x.planned_from >= abDatum
      && x.plan_status !== "fertig")
    .sort((a, c) => a.planned_from < c.planned_from ? -1
      : (a.planned_from > c.planned_from ? 1 : String(a.id).localeCompare(String(c.id))));

  const vorher = [];
  let zeiger = naechsterArbeitstag(abDatum);

  for (const x of reihe) {
    // Nie über einen Auftrag drüber, der nicht mitwandert
    zeiger = freierStart(maschineId, zeiger, x.planned_days || 1, x.id);
    if (zeiger !== x.planned_from) {
      vorher.push({ id: x.id, von: x.planned_from, nach: zeiger });
      x.planned_from = zeiger;
    }
    zeiger = naechsterArbeitstag(arbeitstagePlus(zeiger, x.planned_days || 1));
  }
  await parallelSenden(vorher.map((v) => () =>
    db.from("jobs").update({ planned_from: v.nach }).eq("id", v.id)));
  return vorher;
}

// Nur Farben, denen ein Material zugeteilt wurde, stehen im
// Auftragsfenster zur Auswahl.
function farbenZurWahl() {
  const genutzt = PLANFARBEN.filter((f) => FARBZUTEILUNG[f.wert]);
  if (!genutzt.length) return PLANFARBEN;   // solange nichts zugeteilt ist
  return genutzt.sort((a, b2) =>
    (FARBZUTEILUNG[a.wert].sortierung || 0) - (FARBZUTEILUNG[b2.wert].sortierung || 0));
}

// Wer plant, wird in den Einstellungen angehakt. Nur diese
// Personen erscheinen im Auftragsfenster zur Auswahl.
let PLANER = [];

async function planerLaden() {
  PLANER = [];
  try {
    const { data, error } = await db.from("profiles")
      .select("id, full_name, email, initialen, ist_planer")
      .eq("is_active", true).eq("ist_planer", true).order("full_name");
    if (error) throw error;
    PLANER = (data || []).filter((u) => (u.initialen || "").trim());
  } catch (f) {
    // Fehlt die Spalte ist_planer in der Datenbank, schlug die ganze
    // Abfrage fehl und die Liste blieb still leer — dann verschwand
    // "Eingeplant von" aus dem Auftragsfenster, ohne dass jemand
    // wusste warum. Jetzt gilt ersatzweise: wer ein Kürzel hat, plant.
    try {
      const r = await db.from("profiles")
        .select("id, full_name, email, initialen")
        .eq("is_active", true).order("full_name");
      PLANER = (r.data || []).filter((u) => (u.initialen || "").trim());
    } catch (g) { PLANER = []; }
  }
}

// Alle Personen mit Name und Kürzel — für "zuletzt geändert von".
// Einmal geholt, fünf Minuten gemerkt.
let PERSONEN = {};
let personenZeit = 0;

async function personenLaden() {
  if (Date.now() - personenZeit < 300000 && Object.keys(PERSONEN).length) return;
  try {
    const r = await zeitlimit(db.from("profiles").select("id, full_name, email, initialen"),
      8000, "Personen");
    if (r.error) throw r.error;
    PERSONEN = {};
    (r.data || []).forEach((u) => { PERSONEN[u.id] = u; });
    personenZeit = Date.now();
  } catch (f) { /* ohne Namen zeigt der Balken eben kein Kürzel */ }
}

// Kürzel einer Person: die hinterlegten Initialen, sonst aus dem Namen
function personKuerzel(id) {
  const u = PERSONEN[id];
  if (!u) return "";
  if ((u.initialen || "").trim()) return u.initialen.trim();
  const name = (u.full_name || u.email || "").split("@")[0];
  const teile = name.split(/[\s._-]+/).filter(Boolean);
  return teile.length > 1 ? (teile[0][0] + teile[teile.length - 1][0]).toUpperCase()
    : name.slice(0, 2).toUpperCase();
}

function personVoll(id) {
  const u = PERSONEN[id];
  return u ? (u.full_name || u.email || "") : "";
}

// Kürzel der angemeldeten Person, falls sie selbst plant
function meineInitialen() {
  const ich = PLANER.find((u) => u.id === (profil && profil.id));
  return ich ? (ich.initialen || "").trim() : "";
}

// =================================================================
//  WERKSTOFFE
//  Aus der Materialbezeichnung die Gruppe erkennen — und damit die
//  Farbe auf der Planwand und wie die Späne entsorgt werden. Grundlage
//  sind eure Werkstofftabellen. Erkannt wird in dieser Reihenfolge:
//
//    1. was jemand in den Einstellungen von Hand zugeordnet hat
//    2. die Werkstoffnummern und Bezeichnungen aus den Tabellen
//    3. Regeln für alles, was einer Norm folgt (X…CrNi…, CuZn, AW-…)
//
//  Was nicht erkannt wird, bleibt ohne Gruppe und lässt sich in den
//  Einstellungen einmal zuordnen; die App merkt es sich.
// =================================================================

const WERKSTOFFGRUPPEN = {
  stahl:      { name: "Automatenstahl", farbe: "blau",   zusatz: "magnetisch" },
  v2a:        { name: "V2A",            farbe: "rot",    zusatz: "rostfrei" },
  v4a:        { name: "V4A",            farbe: "grau",   zusatz: "rostfrei, mit Molybdän" },
  chrom:      { name: "Chromstahl",     farbe: "rosa",   zusatz: "rostfrei, magnetisch" },
  alu:        { name: "Aluminium",      farbe: "weiss",  zusatz: "" },
  neusilber:  { name: "Neusilber",      farbe: "orange", zusatz: "",
                spaene: "1608 Neusilber Späne Pb", schrott: "1606 Neusilber Schrott Pb" },
  messing:    { name: "Messing",        farbe: "gelb",   zusatz: "",
                spaene: "1427 MS 58 Späne", schrott: "1414 MS 58 Schrott" },
  messing_ohne_pb: { name: "Messing ohne Blei", farbe: "senf",
                zusatz: "unbedingt separat halten",
                spaene: "1499 MS ohne Pb", schrott: "1499 MS ohne Pb" },
  titan:      { name: "Titan",          farbe: "violett", zusatz: "" },
  kunststoff: { name: "Kunststoff",     farbe: "tuerkis", zusatz: "" },
};

// Aus euren Tabellen, Werkstoffnummer und Bezeichnung
const WERKSTOFF_LISTE = {
  v2a: ["1.4301", "1.4307", "1.4310", "1.4305", "1.4541", "1.4550",
        "X5CrNi18-10", "X2CrNi18-9", "X10CrNi18-8", "X8CrNiS18-9",
        "X6CrNiTi18-10", "X6CrNiNb18-10", "AISI 304", "AISI 304L", "AISI 301",
        "AISI 303", "AISI 321", "AISI 347"],
  v4a: ["1.4401", "1.4404", "1.4435", "1.4436", "1.4439", "1.4571", "1.4539",
        "X5CrNiMo17-12-2", "X2CrNiMo17-12-2", "X2CrNiMo18-14-3", "X3CrNiMo17-13-3",
        "X2CrNiMoN17-13-5", "X6CrNiMoTi17-12-2", "X1NiCrMoCu25-20-5",
        "AISI 316", "AISI 316L", "AISI 316Ti", "AISI 904L"],
  chrom: ["1.4000", "1.4003", "1.4016", "1.4021", "1.4028", "1.4104", "1.4113",
          "1.4125", "1.4135", "1.4150", "1.4160", "1.4191", "1.4201", "1.4211",
          "1.4292", "1.4044", "1.4057", "1.4197", "1.4108", "1.4105", "1.4112",
          "1.4034", "1.4124",
          "X5CrNi12", "X6Cr17", "X20Cr13", "X30Cr13", "X2CrNi12", "X6CrNi17-1",
          "X6CrNiMo17-1", "X20CrNi12", "X14CrNi12", "X4CrNi12", "X25CrMo17",
          "X35CrMo17", "X2CrNi17", "X2CrNi17-1", "X17CrNi16-2", "X20CrNiMoS13-1",
          "X30CrMoN15-1", "X6CrMoS17", "X90CrMoV18", "X46Cr13", "X14CrMoS17",
          "X105CrMo17"],
  stahl: ["1.0737", "1.7131", "1.5752", "1.7139", "1.7142", "1.1191", "1.6587",
          "1.8519", "1.7227", "1.7225",
          "46MnSi4", "16MnCr5", "14NiCr14", "20MnCr5", "21MnCr5", "C45",
          "18CrNiMo7-6", "31CrMoV9", "42CrMo4", "42CrMoS4"],
  alu: ["AW-1050", "AW-2011", "AW-6026", "AW-6060", "AW-6061", "AW-6082",
        "AW-6012", "AW-6023", "Al99,5", "AlCuBiPb", "AlMgSiPb", "AlMgSi",
        "AlMg1SiCu", "AlSi1MgMn"],
  neusilber: ["CW400J", "2.0730"],
  messing: ["CW713R", "2.0371", "2.0401"],
  messing_ohne_pb: ["SW1"],
};

// Von Hand zugeordnete Bezeichnungen, aus app_config
let WERKSTOFF_GELERNT = {};

// Der Teil, der den Werkstoff nennt — ohne Durchmesser, Toleranz, Form
function werkstoffKern(bez) {
  return String(bez || "")
    .split(/\s(?:rd|Ø|ø|sw|6kt|4kt|vk|fl|rohr)\b|\s\d+(?:[.,]\d+)?\s?mm\b/i)[0]
    .trim();
}

function werkstoffSchluessel(bez) {
  return werkstoffKern(bez).toLowerCase().replace(/\s+/g, " ");
}

function werkstoffErkennen(bez) {
  const roh = String(bez || "").trim();
  if (!roh) return null;
  const kern = werkstoffKern(roh);
  const klein = kern.toLowerCase();
  const ganz = roh.toLowerCase();
  const mit = (key) => Object.assign({ key: key, kern: kern }, WERKSTOFFGRUPPEN[key]);

  // 1. Von Hand zugeordnet
  const gelernt = WERKSTOFF_GELERNT[werkstoffSchluessel(roh)];
  if (gelernt && WERKSTOFFGRUPPEN[gelernt]) return Object.assign(mit(gelernt), { gelernt: true });

  // 2. Aus den Tabellen — ganzes Wort, damit 1.4301 nicht in 1.43015 steckt
  const woerter = ganz.replace(/[()]/g, " ");
  for (const key of Object.keys(WERKSTOFF_LISTE)) {
    for (const w of WERKSTOFF_LISTE[key]) {
      const muster = new RegExp("(^|[\\s/;,])" + w.toLowerCase()
        .replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "($|[\\s/;,])");
      if (muster.test(woerter)) return mit(key);
    }
  }

  // 3. Regeln
  if (/ecobrass|cuzn21si3p|\bsw1\b/.test(ganz)) return mit("messing_ohne_pb");
  if (/neusilber|cuni\d*zn|cw4\d\dj|2\.07\d\d/.test(ganz)) return mit("neusilber");
  if (/messing|\bms\s?58|cuzn|cw[5-7]\d\d[a-z]|2\.0[34]\d\d/.test(ganz)) return mit("messing");
  if (/\ben\s?aw|\baw-?\d{4}|\bal(mg|cu|si|zn|99)|3\.[0-3]\d{3}|aluminium/.test(ganz)) return mit("alu");
  if (/titan|\bti(al|\s|-|\d)|3\.7\d{3}|grade\s?[1-5]\b/.test(ganz)) return mit("titan");
  if (/\b(peek|pom|pa6|pa66|ptfe|pvdf|pe-?hd|pp|pet|pvc|pom-c)\b/.test(ganz)) return mit("kunststoff");

  // Rostfreie nach Norm: X…Cr…Ni…Mo… mit den Gehalten dahinter
  const x = kern.match(/^x\d+([a-z]+)(\d+(?:-\d+)*)/i);
  if (x) {
    const elemente = x[1].toLowerCase();
    const zahlen = x[2].split("-").map(Number);
    const hatNi = elemente.includes("ni");
    // Nickel: bei X5CrNi18-10 die zweite Zahl, bei X1NiCr… die erste
    const niGehalt = elemente.startsWith("ni") ? zahlen[0] : (zahlen[1] || 0);
    if (hatNi && niGehalt >= 8) return mit(elemente.includes("mo") ? "v4a" : "v2a");
    if (elemente.includes("cr")) return mit("chrom");
  }
  // Werkstoffnummern 1.4xxx grob nach Bereich
  const nr = ganz.match(/\b1\.4(\d)(\d{2})\b/);
  if (nr) {
    if (nr[1] === "0" || nr[1] === "1" || nr[1] === "2") return mit("chrom");
    if (nr[1] === "4") return mit("v4a");
    if (nr[1] === "3") return mit("v2a");
  }
  // Stähle: Automatenstähle, Werkstoffnummern 1.0–1.8, gängige Namen
  if (/\d+s(mn|mnpb|pb)\d*|\betg\s?\d+|automatenstahl|steeltec|\b1\.[0-35-8]\d{3}\b|\bc\d{2}\b|\b\d{2,3}(mncr|crmo|nicr|crnimo|mnsi|cr\d)/.test(ganz)
      || /\bs235|\bs355|\b11smn|\b9smn/.test(ganz)) return mit("stahl");

  return null;
}

async function werkstoffeGelerntLaden() {
  try {
    const r = await zeitlimit(db.from("app_config").select("wert")
      .eq("schluessel", "werkstoff_zuordnung").maybeSingle(), 6000, "Werkstoffe");
    WERKSTOFF_GELERNT = (!r.error && r.data && r.data.wert) ? JSON.parse(r.data.wert) : {};
  } catch (f) { WERKSTOFF_GELERNT = {}; }
}

async function werkstoffZuordnen(bez, gruppe) {
  const s = werkstoffSchluessel(bez);
  if (!s) return;
  if (gruppe) WERKSTOFF_GELERNT[s] = gruppe;
  else delete WERKSTOFF_GELERNT[s];
  const { error } = await db.from("app_config").upsert(
    { schluessel: "werkstoff_zuordnung", wert: JSON.stringify(WERKSTOFF_GELERNT) });
  if (error) throw error;
}

