// {datum}, {name} und {lieferant} werden beim Erstellen ersetzt.
const BESTELLMAIL_VORGABE = "Guten Tag\n\n"
  + "Im Anhang erhalten Sie unsere Bestellung vom {datum}.\n"
  + "Wir bitten um eine kurze Bestätigung mit dem voraussichtlichen Liefertermin.\n\n"
  + "Freundliche Grüsse\n\n"
  + "{name}\n"
  + "Hofer + Co. Präzisionsdrehteile\n"
  + "Alte Bernstrasse 24, CH-4573 Lohn-Ammannsegg\n"
  + "Tel. 032 677 55 77";
let BESTELLMAIL_TEXT = BESTELLMAIL_VORGABE;
// Für das Einstellungsfenster in React
function bestellmailText() { return BESTELLMAIL_TEXT || BESTELLMAIL_VORGABE; }
function bestellmailSetzen(wert) { BESTELLMAIL_TEXT = wert || BESTELLMAIL_VORGABE; }

// Die zwei Logos unten in jeder Bestellmail, je mit Link. Die Bilder
// stecken in der Mail selbst — Outlook zeigt sie sofort, ohne
// "Bilder herunterladen". Doppelt so gross gespeichert wie angezeigt,
// damit sie auf scharfen Bildschirmen nicht verschwimmen.
const MAIL_LOGOS = [
  { id: "hofer-logo@hoferco.ch", datei: "hofer-co.png", alt: "Hofer + Co.",
    link: "https://www.hoferco.ch/", breite: 241, hoehe: 90,
    bild: "" },
  { id: "salt-pepper-logo@hoferco.ch", datei: "salt-pepper.png", alt: "salt-pepper.ch",
    link: "https://www.salt-pepper.ch/", breite: 160, hoehe: 124,
    bild: "" },
];

// Der Text als schlichte, saubere HTML-Mail: Absätze, dann eine feine
// Linie und darunter die Logos nebeneinander, getrennt durch einen
// senkrechten Strich
function bestellmailHtml(text) {
  // Schrift wie intern in Outlook: Aptos 12 — wo es Aptos nicht gibt,
  // die nächstverwandten. Darunter die beiden Logos nebeneinander, ohne
  // Linien, mit gleichmässigem Abstand.
  const schrift = "font-family:Aptos,'Aptos Display',Calibri,Arial,Helvetica,sans-serif;font-size:12pt;";
  const absaetze = String(text || "").replace(/\r/g, "").split(/\n{2,}/)
    .map((a) => '<p style="margin:0 0 12pt 0;' + schrift + 'line-height:1.35;color:#000000;">'
      + esc(a).replace(/\n/g, "<br>") + '</p>').join("");
  const logo = (l) => '<a href="' + l.link + '" style="text-decoration:none;">'
    + '<img src="cid:' + l.id + '" width="' + l.breite + '" height="' + l.hoehe + '" alt="' + esc(l.alt) + '"'
    + ' style="display:block;border:0;outline:none;"></a>';
  return '<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="margin:0;padding:0;">'
    + '<div style="' + schrift + 'color:#000000;">'
    + absaetze
    + '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin-top:14pt;">'
    + '<tr>'
    + '<td style="vertical-align:middle;padding:0 40px 0 0;">' + logo(MAIL_LOGOS[0]) + '</td>'
    + '<td style="vertical-align:middle;padding:0;">' + logo(MAIL_LOGOS[1]) + '</td>'
    + '</tr></table>'
    + '</div></body></html>';
}

