// Auf der Planwand darf jeder alles sehen. Geändert wird erst,
// Auf dem Handy ist die Planwand reine Ansicht, unabhängig von der
// Rolle. Bearbeitet wird am Computer.
function isMobil() {
  return window.matchMedia("(max-width: 720px)").matches;
}

// Wird mit dem Finger bedient — Handy oder Tablet. Die Breite reicht
// dafür nicht: ein iPad ist breiter als 720 Pixel, hat aber keine
// Maus. Alles, was am Finger hängt, richtet sich hiernach.
function istTippgeraet() {
  // Ein iPad meldet mit angeschlossener Tastatur oder Maus "hover:
  // hover" und "pointer: fine" — dann galt es bisher als Computer
  // und das Wischen war aus. Die Anzahl der Berührungspunkte ist
  // das verlässlichere Merkmal.
  return (navigator.maxTouchPoints || 0) > 0
    || window.matchMedia("(hover: none) and (pointer: coarse)").matches
    || isMobil();
}

// Wer bekommt den Bearbeiten-Knopf überhaupt zu sehen? Administratoren
// nicht: sie dürfen ohnehin immer. Auf dem Handy sieht ihn niemand.
function darfBearbeitenKnopf() {
  return !isMobil();
}

function darfWirklichBearbeiten() {
  if (isMobil()) return false;
  return istAdmin() || meineRolle() === "planwand"
    || (profil && profil.darf_bearbeiten === true);
}

// Darf gerade auf der Planwand geändert werden?
function darfPlanen() {
  if (isMobil()) return false;
  if (istAdmin()) return true;
  if (profil && profil.darf_bearbeiten === true) return true;
  return meineRolle() === "planwand" && plan.pinOk === true;
}

