// =================================================================
//  MASCHINENTYPEN
//  Typ → Path → Werkzeugplatz → Werkzeug(e)
//  Die Bestückung hängt am Typ. Jede Maschine bekommt einen Typ
//  zugewiesen und erbt damit den ganzen Aufbau.
// =================================================================

async function ladeTypen() {
  return stammGemerkt("typen", ladeTypenFrisch);
}

async function ladeTypenFrisch() {
  const { data, error } = await zeitlimit(
    db.from("machine_types").select("*").order("name"), 10000, "Maschinentypen");
  if (error) throw error;
  return data || [];
}

// Vergleicht Toolnummern so, wie man sie liest: T2 vor T10, T100 vor
// T1100, 11.1 vor 11.2. Zahlen werden als Zahlen verglichen, der Rest
// als Text — so passt es für jede Schreibweise, ohne sie vorzugeben.
// Farbe eines Paths — dieselbe in der Vorschau am Typ und auf dem
// fertigen Werkzeugblatt.
const PATHFARBEN = ["#003884", "#1c6b42", "#a4231c", "#5b2a9e", "#9c4a0c", "#0d7b8a"];
function pathFarbe(i) { return PATHFARBEN[i % PATHFARBEN.length]; }

// Der Hinweis, wo das Material liegt, steckt als eigene Zeile in der
// Notiz — mit dem Vorsatz "Material:". So braucht es keine neue
// Spalte in der Datenbank, und beides bleibt trotzdem trennbar.
const MATERIALZEILE = /^\s*Material:\s*(.*)$/i;

function notizTrennen(text) {
  const zeilen = String(text || "").split("\n");
  let ort = "";
  const rest = [];
  zeilen.forEach((z) => {
    const t = z.match(MATERIALZEILE);
    if (t && !ort) ort = t[1].trim();
    else rest.push(z);
  });
  return { notiz: rest.join("\n").trim(), ort: ort };
}

function notizZusammen(notiz, ort) {
  const teile = [];
  if ((notiz || "").trim()) teile.push(notiz.trim());
  if ((ort || "").trim()) teile.push("Material: " + ort.trim());
  return teile.join("\n") || null;
}

function toolVergleich(a, b) {
  const teile = (x) => String(x || "").trim().toUpperCase().match(/\d+|\D+/g) || [];
  const ta = teile(a), tb = teile(b);
  for (let i = 0; i < Math.max(ta.length, tb.length); i++) {
    const x = ta[i], y = tb[i];
    if (x === undefined) return -1;
    if (y === undefined) return 1;
    const nx = /^\d+$/.test(x), ny = /^\d+$/.test(y);
    if (nx && ny) {
      const d = Number(x) - Number(y);
      if (d) return d;
    } else if (x !== y) {
      return x < y ? -1 : 1;
    }
  }
  return 0;
}

// Fügt einen neuen Platz an der Stelle ein, an die seine Toolnummer
// gehört. Die übrige Reihenfolge bleibt, wie sie ist — sonst würde
// jedes Anlegen ein von Hand verschobenes Werkzeug zurückwerfen.
async function platzEinreihen(pathId, neuId, neuNr) {
  const r = await db.from("type_slots").select("id, tool_nr, sortierung").eq("path_id", pathId);
  if (r.error) throw r.error;
  const liste = (r.data || [])
    .filter((x) => x.id !== neuId)
    .sort((a, c) => ((a.sortierung || 0) - (c.sortierung || 0))
      || toolVergleich(a.tool_nr, c.tool_nr));

  let stelle = liste.findIndex((x) => toolVergleich(x.tool_nr, neuNr) > 0);
  if (stelle === -1) stelle = liste.length;
  liste.splice(stelle, 0, { id: neuId });

  for (let i = 0; i < liste.length; i++) {
    const e = await db.from("type_slots")
      .update({ sortierung: i + 1, platz_nr: i + 1 }).eq("id", liste[i].id);
    if (e.error) throw e.error;
  }
}

// Ordnet alle Plätze eines Paths nach Toolnummer. Wird nur noch
// gebraucht, wenn jemand die ganze Reihenfolge zurücksetzen will.
async function pathSortieren(pathId) {
  const r = await db.from("type_slots").select("id, tool_nr").eq("path_id", pathId);
  const liste = ((r && r.data) || []).slice().sort((a, b) => toolVergleich(a.tool_nr, b.tool_nr));
  for (let i = 0; i < liste.length; i++) {
    await db.from("type_slots").update({
      platz_nr: i + 1, sortierung: i + 1,
      bezeichnung: liste[i].tool_nr || ("Platz " + (i + 1)),
    }).eq("id", liste[i].id);
  }
}

// Paths mit ihren Plätzen und den Werkzeugen darauf, in einem Zug
async function ladeTypAufbau(typId) {
  const { data, error } = await zeitlimit(
    db.from("type_paths").select("*, type_slots(*)")
      .eq("type_id", typId).order("sortierung"),
    12000, "Aufbau des Typs");
  if (error) throw error;
  return (data || []).map((p) => {
    p.type_slots = (p.type_slots || []).slice()
      .sort((a, c) => (a.sortierung - c.sortierung) || (a.platz_nr - c.platz_nr));
    return p;
  });
}

// =================================================================
//  HOCO Nr.
//  Stammdaten je Teil: Bezeichnung, Material, Materialgrösse.
//  Dazu die Einrichtblätter, die dafür hinterlegt
//  sind — je Maschinentyp eines, manchmal mehrere.
// =================================================================

async function ladeHoco(suche) {
  // Einmal alle holen und merken, dann im Gerät filtern. So löst das
  // Tippen im Suchfeld keine neue Abfrage aus.
  const alle = await stammGemerkt("hoco:alle", () => ladeHocoFrisch(""));
  const t = (suche || "").trim().toLowerCase();
  if (!t) return alle;
  return alle.filter((x) => [x.hoco_nr, x.bezeichnung, x.material]
    .some((f) => String(f || "").toLowerCase().includes(t)));
}

async function ladeHocoFrisch(suche) {
  let abfrage = db.from("hoco_parts").select("*");
  const t = (suche || "").trim();
  if (t) {
    abfrage = abfrage.or("hoco_nr.ilike.%" + t + "%,bezeichnung.ilike.%" + t
      + "%,material.ilike.%" + t + "%");
  }
  // Seitenweise alles holen. Eine feste Grenze von 200 hat bei
  // vielen Nummern einfach den Rest weggelassen.
  const alle = [];
  const stufe = 1000;
  for (let seite = 0; seite < 20; seite++) {
    const r = await zeitlimit(
      abfrage.order("hoco_nr").range(seite * stufe, seite * stufe + stufe - 1),
      12000, "HOCO Nummern");
    if (r.error) throw r.error;
    const teil = r.data || [];
    alle.push(...teil);
    if (teil.length < stufe) break;
  }
  return alle;
}

// Alle HOCO Nummern, die auf der Planwand vorkommen. Daraus wird
// gezeigt, wofür noch keine Stammdaten hinterlegt sind.
async function ladeHocoAusAuftraegen() {
  return stammGemerkt("hocoausauftraegen", ladeHocoAusAuftraegenFrisch);
}

async function ladeHocoAusAuftraegenFrisch() {
  const { data, error } = await zeitlimit(
    db.from("jobs")
      .select("job_number, material_bez, drawing_url, plan_status, ended_at")
      .order("created_at", { ascending: false }).limit(1000),
    12000, "Aufträge");
  if (error) throw error;
  // Je Nummer der jüngste Auftrag, der noch nicht abgeschlossen ist.
  // Ein fertiger Durchlauf soll die Stammdaten nicht mehr bestimmen —
  // dort zählt der letzte Stand. Gibt es nur fertige, wird eben der
  // jüngste davon genommen, sonst stünde gar nichts da.
  const karte = {}, ersatz = {};
  (data || []).forEach((j) => {
    if (!j.job_number) return;
    const fertig = j.ended_at || j.plan_status === "fertig";
    if (fertig) {
      if (!ersatz[j.job_number]) ersatz[j.job_number] = j;
      return;
    }
    if (!karte[j.job_number]) karte[j.job_number] = j;
  });
  Object.keys(ersatz).forEach((nr) => {
    if (!karte[nr]) karte[nr] = ersatz[nr];
  });
  return karte;
}

// Aus Durchmesser und Toleranz des Auftrags wird die Materialgrösse
function groesseAusAuftrag(j) {
  return (j && j.material_bez) || "";
}

async function ladeBlaetter(hocoNr) {
  const { data, error } = await zeitlimit(
    db.from("einrichtblaetter").select("*").eq("hoco_nr", hocoNr).order("created_at"),
    12000, "Einrichtblätter");
  if (error) throw error;
  return data || [];
}



// =================================================================
//  PAD MODE
//  Eigene Oberfläche für die Tablets an den Maschinen. Schwarzer
//  Hintergrund wegen OLED, grosse Kacheln, wenig Text.
//  Aufbau: Start → Parks → Maschinen → Dashboard.
// =================================================================

const pad = { wo: "start", parkId: null, maschineId: null, daten: {} };

const LEERLAUF_MS = 5 * 60 * 1000;     // fünf Minuten
const WARNUNG_MS = 20 * 1000;          // so lange vorher warnen
let leerlauf = { letzte: Date.now(), takt: null, abmelden: null, hinweis: null };

function leerlaufAktiv() {
  leerlauf.letzte = Date.now();
  if (leerlauf.hinweis) { leerlauf.hinweis.remove(); leerlauf.hinweis = null; }
}

function leerlaufStarten(abmelden) {
  leerlaufStoppen();
  leerlauf.abmelden = abmelden;
  leerlauf.letzte = Date.now();
  ["pointerdown", "keydown", "wheel", "touchstart", "input"].forEach((art) =>
    document.addEventListener(art, leerlaufAktiv, { capture: true, passive: true }));
  // Mausbewegung zählt auch, aber nur alle paar Sekunden — sonst wird
  // bei jedem Pixel gerechnet
  let zuletzt = 0;
  leerlauf.bewegt = () => {
    const jetzt = Date.now();
    if (jetzt - zuletzt > 3000) { zuletzt = jetzt; leerlaufAktiv(); }
  };
  document.addEventListener("mousemove", leerlauf.bewegt, { passive: true });
  leerlauf.sichtbar = () => { if (!document.hidden) leerlaufPruefen(); };
  document.addEventListener("visibilitychange", leerlauf.sichtbar);
  leerlauf.takt = setInterval(leerlaufPruefen, 2000);
}

function leerlaufStoppen() {
  if (leerlauf.takt) clearInterval(leerlauf.takt);
  leerlauf.takt = null;
  ["pointerdown", "keydown", "wheel", "touchstart", "input"].forEach((art) =>
    document.removeEventListener(art, leerlaufAktiv, { capture: true }));
  if (leerlauf.bewegt) document.removeEventListener("mousemove", leerlauf.bewegt);
  if (leerlauf.sichtbar) document.removeEventListener("visibilitychange", leerlauf.sichtbar);
  if (leerlauf.hinweis) { leerlauf.hinweis.remove(); leerlauf.hinweis = null; }
}

function leerlaufPruefen() {
  if (!leerlauf.takt || !profil) return;
  // Wer den Haken "Angemeldet bleiben" gesetzt hat, wird nicht
  // abgemeldet — wie bisher.
  if (einstellung("angemeldetbleiben")) {
    if (leerlauf.hinweis) { leerlauf.hinweis.remove(); leerlauf.hinweis = null; }
    return;
  }

  // Im Pad Mode wird nicht abgemeldet. Das Tablet liegt an der
  // Maschine und soll den ganzen Tag zeigen, was läuft.
  if (document.getElementById("pad")) {
    leerlauf.letzte = Date.now();
    if (leerlauf.hinweis) { leerlauf.hinweis.remove(); leerlauf.hinweis = null; }
    return;
  }

  const ruhe = Date.now() - leerlauf.letzte;

  if (ruhe >= LEERLAUF_MS) {
    const abmelden = leerlauf.abmelden;
    leerlaufStoppen();
    if (abmelden) {
      // Die Meldung erst nach dem Aufbau der Anmeldeseite zeigen,
      // sonst verschwindet sie mit dem alten Inhalt
      abmelden().then(() => setTimeout(() =>
        meldung("Automatische Abmeldung."), 400));
    }
    return;
  }

  if (ruhe >= LEERLAUF_MS - WARNUNG_MS) {
    const rest = Math.ceil((LEERLAUF_MS - ruhe) / 1000);
    if (!leerlauf.hinweis) {
      leerlauf.hinweis = document.createElement("div");
      leerlauf.hinweis.className = "leerlauf-hinweis";
      document.body.appendChild(leerlauf.hinweis);
    }
    leerlauf.hinweis.innerHTML = '<strong>Abmeldung in ' + rest + ' Sekunden</strong>'
      + '<span>Tippe irgendwo, um angemeldet zu bleiben.</span>';
  }
}

function padOeffnen() {
  if (document.getElementById("pad")) return;
  const h = document.createElement("div");
  h.id = "pad";
  h.className = "pad" + (einstellung("dunkel") ? " pad--dunkel" : "");
  document.body.appendChild(h);
  document.body.classList.add("pad-offen");
  // Das Pad legt sich über die Seite, statt hart umzuschalten
  if (typeof h.animate === "function") {
    h.animate(wenigBewegung()
      ? [{ opacity: 0 }, { opacity: 1 }]
      : [{ opacity: 0, transform: "scale(1.015)" }, { opacity: 1, transform: "none" }],
      { duration: 280, easing: "cubic-bezier(.16,1,.3,1)" });
  }
  // Die Seite darunter leeren, solange das Pad offen ist: Zeigt das Pad
  // dieselbe Seite, gäbe es sonst jedes Feld doppelt
  const inhalt = document.getElementById("inhalt");
  if (inhalt) inhalt.innerHTML = "";
  if (typeof syncStoppen === "function") syncStoppen();
  pad.wo = "start";
  padZeichnen();
}

function padSchliessen() {
  const h = document.getElementById("pad");
  padAbbauen();
  if (h) h.remove();
  document.body.classList.remove("pad-offen");
  // Die Seite darunter wieder aufbauen
  if (document.getElementById("inhalt")) zeichneSeite();
}

// Das Zeichnen des Pads (Kopf, Start, Parks, Typen, Maschinen und
// das Dashboard einer Maschine) ist in src/pad/. padZeichnen kommt
// von dort.

// Wenig Text: gross. Viel Text: kleiner. Sehr viel: kleinste Schrift
// und nur dieser Teil wird scrollbar. Die Grösse wird ausprobiert, bis
// alles in die Kachel passt.
function padTextEinpassen() {
  const text = document.querySelector("#pad .pad-hocotext");
  if (!text) return;
  text.classList.remove("pad-hocotext--rollen");
  const passt = () => text.scrollHeight <= text.clientHeight + 1;
  let stufe = 1.9;
  text.style.setProperty("--pad-tg", stufe);
  while (!passt() && stufe > 0.95) {
    stufe = Math.round((stufe - 0.05) * 100) / 100;
    text.style.setProperty("--pad-tg", stufe);
  }
  if (!passt()) text.classList.add("pad-hocotext--rollen");
}
let padEinpassenTakt = null;
window.addEventListener("resize", () => {
  clearTimeout(padEinpassenTakt);
  padEinpassenTakt = setTimeout(padTextEinpassen, 150);
});

// =================================================================
//  ZIFFERBLOCK
//  Grosse Tasten statt Handytastatur — an der Maschine wird mit
//  Handschuhen oder öligen Fingern getippt. Liefert die Zahl oder null.
// =================================================================

function zifferblock({ titel, hinweis, wert, schritte }) {
  return new Promise((fertig) => {
    let eingabe = String(wert == null ? "" : wert).replace(/\D/g, "");
    const huelle = document.createElement("div");
    huelle.className = "dialog-huelle";
    huelle.innerHTML = '<div class="dialog zifferblock">'
      + '<h2>' + esc(titel) + '</h2>'
      + (hinweis ? '<p class="klein">' + esc(hinweis) + '</p>' : "")
      + '<div class="zb-anzeige" id="zb-anzeige"></div>'
      + (schritte && schritte.length
          ? '<div class="zb-schritte">' + schritte.map((n) =>
              '<button type="button" data-zbplus="' + n + '">+' + zahlText(n) + '</button>').join("")
            + '</div>' : "")
      + '<div class="zb-tasten">'
      + ["7", "8", "9", "4", "5", "6", "1", "2", "3", "C", "0", "⌫"].map((t) =>
          '<button type="button" data-zb="' + t + '"'
          + (t === "C" || t === "⌫" ? ' class="zb-taste--neben"' : "") + '>' + t + '</button>').join("")
      + '</div>'
      + '<div class="zb-knoepfe">'
      + '<button type="button" class="knopf knopf--still" data-zbnein>Abbrechen</button>'
      + '<button type="button" class="knopf knopf--haupt" data-zbja>Eintragen</button>'
      + '</div></div>';
    document.body.appendChild(huelle);

    const anzeige = huelle.querySelector("#zb-anzeige");
    const zeigen = () => {
      anzeige.textContent = eingabe ? zahlText(Number(eingabe)) : "0";
      anzeige.classList.toggle("zb-anzeige--leer", !eingabe);
    };
    zeigen();

    const zu = (ergebnis) => {
      document.removeEventListener("keydown", tasten, true);
      huelle.remove();
      fertig(ergebnis);
    };
    huelle.querySelectorAll("[data-zb]").forEach((el) => {
      el.onclick = () => {
        const t = el.dataset.zb;
        if (t === "C") eingabe = "";
        else if (t === "⌫") eingabe = eingabe.slice(0, -1);
        else if (eingabe.length < 9) eingabe = (eingabe === "0" ? "" : eingabe) + t;
        zeigen();
      };
    });
    huelle.querySelectorAll("[data-zbplus]").forEach((el) => {
      el.onclick = () => {
        eingabe = String((Number(eingabe) || 0) + Number(el.dataset.zbplus));
        zeigen();
      };
    });
    huelle.querySelector("[data-zbnein]").onclick = () => zu(null);
    huelle.querySelector("[data-zbja]").onclick = () => zu(eingabe === "" ? null : Number(eingabe));
    huelle.onclick = (e) => { if (e.target === huelle) zu(null); };

    // Mit einer echten Tastatur geht es auch
    function tasten(e) {
      if (!document.body.contains(huelle)) return;
      if (/^\d$/.test(e.key)) { if (eingabe.length < 9) eingabe = (eingabe === "0" ? "" : eingabe) + e.key; }
      else if (e.key === "Backspace") eingabe = eingabe.slice(0, -1);
      else if (e.key === "Enter") { e.preventDefault(); zu(eingabe === "" ? null : Number(eingabe)); return; }
      else if (e.key === "Escape") { zu(null); return; }
      else return;
      e.preventDefault();
      zeigen();
    }
    document.addEventListener("keydown", tasten, true);
  });
}

// ---------- Werkzeugwechsel ----------

async function werkzeugWechselDialog(maschine, auftrag) {
  // Alle Werkzeugplätze des Typs, nach Path sortiert. Angetippt
  // werden alle, die in dieser Runde gewechselt wurden.
  let paths = [];
  try { paths = await ladeTypAufbau(maschine.type_id); }
  catch (f) { meldung(fehlertext(f), "fehler"); return; }

  const reihen = paths
    .sort((x, y) => (x.nummer === 2 ? 99 : x.nummer) - (y.nummer === 2 ? 99 : y.nummer))
    .map((p) => ({ name: p.name, plaetze: (p.type_slots || []).filter((s) => s.tool_nr) }))
    .filter((p) => p.plaetze.length);

  if (!reihen.length) {
    meldung("Für diesen Maschinentyp sind noch keine Werkzeugplätze angelegt.", "warn");
    return;
  }

  const gewaehlt = new Set();
  const nr = "ww" + (++dialogZaehler) + "-";
  const huelle = document.createElement("div");
  huelle.className = "dialog-huelle";
  huelle.innerHTML = '<div class="dialog dialog--breit">'
    + '<div class="wz-kopf"><h2>Werkzeugwechsel</h2>'
    // Die Historie hat keinen eigenen Knopf mehr am Dashboard, sie
    // sitzt dort, wo man sie braucht: neben dem Wechsel.
    + '<button class="knopf knopf--klein" data-wzhistorie>Historie</button></div>'
    + '<p class="klein">Alle Werkzeuge antippen, die gewechselt wurden.</p>'
    + reihen.map((p) => '<div class="wz-path">'
        + '<div class="wz-path__name">' + esc(p.name) + '</div>'
        + '<div class="wz-gitter">'
        + p.plaetze.map((sl) => '<button type="button" class="wz-platz"'
            + ' data-tool="' + esc(sl.tool_nr) + '">'
            + '<span class="wz-platz__nr">' + esc(sl.tool_nr) + '</span>'
            + '<span class="wz-platz__art">' + esc(sl.bezeichnung || "") + '</span>'
            + '</button>').join("")
        + '</div></div>').join("")
    + '<div class="dialog__knoepfe">'
    + '<button class="knopf knopf--still" data-nein>Abbrechen</button>'
    + '<button class="knopf knopf--haupt" id="' + nr + 'weiter" disabled>Weiter</button>'
    + '</div></div>';
  document.body.appendChild(huelle);

  const zu = () => huelle.remove();
  huelle.querySelector("[data-nein]").onclick = zu;
  dialogSchliessen(huelle, zu);

  const weiter = huelle.querySelector("#" + nr + "weiter");
  const histKnopf = huelle.querySelector("[data-wzhistorie]");
  if (histKnopf) histKnopf.onclick = () => { huelle.remove(); wechselHistorie(maschine, auftrag); };

  huelle.querySelectorAll("[data-tool]").forEach((el) => {
    el.onclick = () => {
      const t = el.dataset.tool;
      if (gewaehlt.has(t)) gewaehlt.delete(t); else gewaehlt.add(t);
      el.classList.toggle("wz-platz--an", gewaehlt.has(t));
      weiter.disabled = gewaehlt.size === 0;
      weiter.textContent = gewaehlt.size
        ? "Weiter · " + gewaehlt.size : "Weiter";
    };
  });

  weiter.onclick = async () => {
    const liste = [...gewaehlt];
    zu();

    const w = await dialogFelder({ titel: "Stückzahl beim Wechsel",
      felder: [
        { name: "stk", label: "Jetzige Stückzahl", typ: "number", pflicht: true,
          wert: auftrag ? (auftrag.stand || 0) : "",
          hinweis: liste.length + (liste.length === 1 ? " Werkzeug" : " Werkzeuge") },
        { name: "notiz", label: "Notiz", wert: "" },
      ], bestaetigen: "Wechsel eintragen" });
    if (!w) return;

    const stand = Math.max(0, Math.round(Number(w.stk) || 0));

    // Wie viele Stück das Werkzeug gehalten hat: Abstand zur
    // Stückzahl beim letzten Wechsel desselben Platzes.
    const vorher = {};
    try {
      const r = await db.from("tool_changes")
        .select("tool_nr, stueckzahl, gewechselt_am")
        .eq("machine_id", maschine.id).in("tool_nr", liste)
        .order("gewechselt_am", { ascending: false }).limit(200);
      (r.data || []).forEach((z) => {
        if (vorher[z.tool_nr] === undefined) vorher[z.tool_nr] = z.stueckzahl;
      });
    } catch (f) { /* dann bleibt die Spalte leer */ }

    // Alle Zeilen einer Runde bekommen denselben Zeitpunkt
    const zeitpunkt = new Date().toISOString();
    const zeilen = liste.map((t) => ({
      machine_id: maschine.id,
      job_id: auftrag ? auftrag.id : null,
      hoco_nr: auftrag ? auftrag.job_number : null,
      tool_nr: t,
      stueckzahl: stand,
      gehalten_stk: (vorher[t] === undefined || vorher[t] === null)
        ? null : Math.max(0, stand - vorher[t]),
      notiz: w.notiz || null,
      gewechselt_am: zeitpunkt,
    }));

    // Über den Einfüger, der Spalten weglässt, die es in der Tabelle
    // nicht gibt — sonst scheitert der ganze Eintrag an einem Feld.
    try {
      await einfuegenOhneUnbekannte("tool_changes", zeilen);
    } catch (f) { meldung(fehlertext(f), "fehler"); return; }
    meldung(liste.length + (liste.length === 1 ? " Werkzeug" : " Werkzeuge")
      + " bei " + zahlText(stand) + " Stück eingetragen.");
  };
}

async function wechselHistorie(maschine, auftrag) {
  let liste = [];
  try {
    const r = await zeitlimit(db.from("werkzeugwechsel").select("*")
      .eq("machine_id", maschine.id)
      .order("gewechselt_am", { ascending: false }).limit(300),
      12000, "Werkzeugwechsel");
    if (r.error) throw r.error;
    liste = r.data || [];
  } catch (f) { meldung(fehlertext(f), "fehler"); return; }

  // Nach Runden gruppieren: alle Zeilen einer Runde teilen sich
  // Zeitpunkt und Stückzahl.
  const runden = [];
  liste.forEach((z) => {
    const schluessel = z.gewechselt_am + "|" + (z.stueckzahl === null ? "" : z.stueckzahl);
    let r = runden.find((x) => x.schluessel === schluessel);
    if (!r) {
      r = { schluessel: schluessel, wann: z.gewechselt_am, stk: z.stueckzahl,
            person: z.person, auftrag: z.auftrag_nr, notiz: z.notiz, zeilen: [] };
      runden.push(r);
    }
    r.zeilen.push(z);
  });

  const tabelle = runden.length
    ? '<table class="tabelle"><thead><tr><th>Stückzahl</th><th>Gewechselt</th>'
      + '<th>Auftrag</th><th>Wann</th><th>Wer</th></tr></thead><tbody>'
      + runden.map((r) => '<tr>'
          + '<td class="nowrap"><strong>'
          + (r.stk === null || r.stk === undefined ? "—" : zahlText(r.stk))
          + '</strong></td>'
          + '<td>' + r.zeilen.map((z) => '<span class="wz-marke">' + esc(z.tool_nr)
              + (z.gehalten_stk !== null && z.gehalten_stk !== undefined
                  ? ' <i>' + zahlText(z.gehalten_stk) + ' Stk</i>' : "")
              + '</span>').join(" ")
          + (r.notiz ? '<div class="klein">' + esc(r.notiz) + '</div>' : "")
          + '</td>'
          + '<td class="klein">' + esc(r.auftrag || "") + '</td>'
          + '<td class="klein nowrap">' + esc(datumZeitKurz(r.wann)) + '</td>'
          + '<td class="klein">' + esc(r.person || "") + '</td>'
          + '</tr>').join("") + '</tbody></table>'
    : '<p class="hinweis">Noch kein Wechsel eingetragen.</p>';

  const huelle = document.createElement("div");
  huelle.className = "dialog-huelle";
  huelle.innerHTML = '<div class="dialog dialog--breit">'
    + '<div class="blatt__kopf"><h2>Werkzeugwechsel · ' + esc(maschine.name) + '</h2>'
    + (runden.length
        ? '<button class="knopf knopf--klein" data-wzpdf>Als PDF ablegen</button>' : "")
    + '<button class="knopf knopf--still" data-zu>Schliessen</button></div>'
    + tabelle
    + '<p class="klein">Die Zahl hinter einem Werkzeug sagt, wie viele Stück es seit '
    + 'dem letzten Wechsel gehalten hat. Die Standzeit im Einrichtblatt bleibt davon '
    + 'unberührt und wird dort von Hand gepflegt.</p>'
    + '</div>';
  document.body.appendChild(huelle);
  const zu = () => huelle.remove();
  huelle.querySelector("[data-zu]").onclick = zu;
  dialogSchliessen(huelle, zu);

  const pdfKnopf = huelle.querySelector("[data-wzpdf]");
  if (pdfKnopf) pdfKnopf.onclick = () => historieAblegen(maschine, auftrag, runden);
}

// Die Historie als PDF in dieselbe Ablage wie die Warenbegleit-
// blätter, und am Auftrag vermerkt — dort steht sie neben der WBG.
async function historieAblegen(maschine, auftrag, runden) {
  const fenster = window.open("", "_blank");
  if (!fenster) { meldung("Das Fenster wurde blockiert.", "warn"); return; }

  const titel = "Werkzeugwechsel_"
    + (auftrag && auftrag.fa_nr ? auftrag.fa_nr : maschine.name).replace(/[^A-Za-z0-9]+/g, "_")
    + "_" + isoDatum(new Date());

  fenster.document.write('<!doctype html><html lang="de"><head><meta charset="utf-8">'
    + '<title>' + esc(titel) + '</title><style>'
    + '@page { size: A4; margin: 14mm }'
    + 'body { font-family: Calibri, Arial, sans-serif; font-size: 10pt; margin: 0;'
    + '       -webkit-print-color-adjust: exact; print-color-adjust: exact }'
    + 'h1 { font-size: 15pt; margin: 0 0 2mm }'
    + '.kopf { color: #445; font-size: 9pt; margin-bottom: 5mm }'
    + 'table { width: 100%; border-collapse: collapse }'
    + 'th { text-align: left; font-size: 8pt; letter-spacing: .06em; color: #003884;'
    + '     border-bottom: 1pt solid #003884; padding: 0 2mm 1.5mm }'
    + 'td { padding: 1.8mm 2mm; border-bottom: .4pt solid #dfe3e8; vertical-align: top }'
    + '.nr { font-weight: 700; white-space: nowrap }'
    + '.wz { display: inline-block; border: .5pt solid #9aa5b1; border-radius: 2mm;'
    + '      padding: 0 1.5mm; margin: 0 1mm .8mm 0; font-size: 9pt }'
    + '.wz i { font-style: normal; color: #667; font-size: 8pt }'
    + '.leiste { position: fixed; top: 10px; right: 12px }'
    + '.leiste button { font: inherit; padding: 7px 14px; margin-left: 6px;'
    + '  border: 1px solid #003884; background: #003884; color: #fff; border-radius: 6px;'
    + '  cursor: pointer }'
    + '@media print { .leiste { display: none } }'
    + '</style></head><body>'
    + '<div class="leiste"><button onclick="window.print()">Drucken</button>'
    + '<button onclick="window.close()">Schliessen</button></div>'
    + '<h1>Werkzeugwechsel</h1>'
    + '<div class="kopf">' + esc(maschine.name)
    + (maschine.machine_number ? " · " + esc(maschine.machine_number) : "")
    + (auftrag ? " · " + esc(auftrag.job_number || "") : "")
    + (auftrag && auftrag.fa_nr ? " · FA " + esc(auftrag.fa_nr) : "")
    + " · Stand " + esc(kurzDatum(isoDatum(new Date()))) + '</div>'
    + '<table><thead><tr><th>Stückzahl</th><th>Gewechselte Werkzeuge</th>'
    + '<th>Wann</th><th>Wer</th></tr></thead><tbody>'
    + runden.map((r) => '<tr>'
        + '<td class="nr">' + (r.stk === null || r.stk === undefined
            ? "—" : zahlText(r.stk)) + '</td>'
        + '<td>' + r.zeilen.map((z) => '<span class="wz">' + esc(z.tool_nr)
            + (z.gehalten_stk !== null && z.gehalten_stk !== undefined
                ? ' <i>' + zahlText(z.gehalten_stk) + ' Stk</i>' : "")
            + '</span>').join("")
        + (r.notiz ? '<div style="color:#667;font-size:9pt">' + esc(r.notiz) + '</div>' : "")
        + '</td>'
        + '<td>' + esc(datumZeitKurz(r.wann)) + '</td>'
        + '<td>' + esc(r.person || "") + '</td>'
        + '</tr>').join("")
    + '</tbody></table></body></html>');
  fenster.document.close();

  // Zusätzlich in der Ablage hinterlegen, damit die Historie später
  // neben der WBG steht — auch ohne das geöffnete Fenster.
  if (!auftrag) return;
  try {
    const inhalt = "<!doctype html>" + fenster.document.documentElement.outerHTML;
    const name = "wbg/wz-" + Date.now() + "-" + titel + ".html";
    const r = await db.storage.from("zeichnungen")
      .upload(name, new Blob([inhalt], { type: "text/html" }),
        { contentType: "text/html" });
    if (r.error) throw r.error;
    const adresse = db.storage.from("zeichnungen").getPublicUrl(name).data.publicUrl;
    const u = await db.from("jobs").update({ wz_historie_url: adresse })
      .eq("id", auftrag.id);
    if (u.error) throw u.error;
    meldung("Historie abgelegt — sie steht jetzt beim Auftrag neben der WBG.");
  } catch (f) {
    meldung("Im Fenster kannst du sie als PDF speichern. Ablegen ging nicht: "
      + fehlertext(f), "warn");
  }
}

// =================================================================
//  EINRICHTBLATT
//  Ein Blatt gilt je HOCO Nr. und Maschinentyp. Es übernimmt beim
//  Anlegen die Stammdaten des Teils und das Raster des Typs und ist
//  danach frei änderbar, ohne dass Stammdaten oder Typ sich ändern.
// =================================================================

// Überträgt die Stammdaten auf alle Aufträge, die noch nicht
// laufen. Gefüllt wird nur, was am Auftrag leer ist — Eingetipptes
// bleibt stehen, und bei laufenden oder fertigen Aufträgen wird
// nichts angefasst.
async function stammdatenAufPlanwand() {
  if (!darfSchreiben()) return 0;

  const offen = (plan.auftraege || []).filter((j) => j.job_number
    && ["geplant", "ruesten"].indexOf(j.plan_status || "geplant") !== -1
    && (!j.material_bez || !j.drawing_url));
  if (!offen.length) return 0;

  const nummern = [...new Set(offen.map((j) => j.job_number))];
  let teile = [];
  try {
    const r = await db.from("hoco_parts").select("*").in("hoco_nr", nummern);
    if (r.error) throw r.error;
    teile = r.data || [];
  } catch (f) { return 0; }
  if (!teile.length) return 0;

  const karte = {};
  teile.forEach((t) => { karte[t.hoco_nr] = t; });

  let geaendert = 0;
  const aufgaben = [];
  for (const j of offen) {
    const t = karte[j.job_number];
    if (!t) continue;

    const neu = {};
    if (!j.material_bez && t.material) neu.material_bez = t.material;
    if (!j.drawing_url && t.zeichnung_url) neu.drawing_url = t.zeichnung_url;
    if (!Object.keys(neu).length) continue;

    // Gleichzeitig statt einer nach dem anderen
    aufgaben.push(async () => {
      const u = await db.from("jobs").update(neu).eq("id", j.id);
      if (!u.error) { Object.assign(j, neu); geaendert++; }
      return u;
    });
  }
  try { await parallelSenden(aufgaben); } catch (f) { /* beim nächsten Öffnen wieder */ }
  return geaendert;
}

async function ladeHocoEins(hocoNr) {
  const { data } = await db.from("hoco_parts").select("*").eq("hoco_nr", hocoNr).limit(1);
  return (data || [])[0] || null;
}

// =================================================================
//  EINRICHTBLATT ALS PDF
//  Statt ein Blatt in der App zu bauen, wird eine fertige PDF
//  hinterlegt — wie bei der Zeichnung. Zwei Ebenen:
//    · am Maschinentyp   → gilt für alle Teile auf diesem Typ
//    · an der HOCO Nr.   → gilt nur für dieses Teil auf diesem Typ
//  Gibt es beides, gewinnt das Blatt der HOCO Nr.
// =================================================================

async function blattPdfSuchen(hocoNr, typId) {
  let eigenes = null, vorlage = null;

  if (hocoNr && typId) {
    try {
      const r = await db.from("hoco_type_data").select("blatt_url")
        .eq("hoco_nr", hocoNr).eq("type_id", typId).limit(1);
      eigenes = ((r.data || [])[0] || {}).blatt_url || null;
    } catch (f) { /* dann eben nur die Vorlage */ }
  }
  if (typId) {
    try {
      // Über die gewohnte Ladefunktion — die kennt die Typen samt
      // hinterlegtem Blatt und ist gemerkt.
      const typen = await ladeTypen();
      const t = (typen || []).find((x) => x.id === typId);
      vorlage = (t && t.blatt_url) || null;
    } catch (f) { /* dann eben keine */ }
  }
  return { eigenes: eigenes, vorlage: vorlage, adresse: eigenes || vorlage };
}

async function einrichtblattPdfOeffnen(hocoNr, typId, titel) {
  if (!typId) {
    meldung("Dieser Maschine ist kein Typ zugewiesen. "
      + "Den trägst du unter Produktion → Maschinen ein.", "warn");
    return;
  }
  let gefunden;
  try { gefunden = await blattPdfSuchen(hocoNr, typId); }
  catch (f) { meldung(fehlertext(f), "fehler"); return; }

  if (!gefunden.adresse) {
    meldung("Für diesen Typ ist noch kein Einrichtblatt hinterlegt. "
      + "Hinterlegen kannst du es beim Maschinentyp oder bei der HOCO Nr.", "warn");
    return;
  }
  betrachter(gefunden.adresse,
    "Einrichtblatt " + (titel || hocoNr || ""), true);
}

// Eine PDF auswählen, hochladen und die Adresse zurückgeben
function blattPdfWaehlen() {
  return new Promise((fertig) => {
    const feld = document.createElement("input");
    feld.type = "file";
    feld.accept = "application/pdf,image/*";
    feld.onchange = async () => {
      const datei = feld.files && feld.files[0];
      if (!datei) { fertig(null); return; }
      try {
        meldung("Wird hochgeladen …");
        const endung = (datei.name.split(".").pop() || "pdf").toLowerCase();
        const name = "blatt/" + Date.now() + "-"
          + Math.random().toString(36).slice(2, 8) + "." + endung;
        const hoch = await db.storage.from("zeichnungen")
          .upload(name, datei, { upsert: true, contentType: datei.type || undefined });
        if (hoch.error) throw hoch.error;
        fertig(db.storage.from("zeichnungen").getPublicUrl(name).data.publicUrl);
      } catch (f) {
        meldung(fehlertext(f), "fehler");
        fertig(null);
      }
    };
    feld.click();
  });
}

// Blatt am Maschinentyp hinterlegen — die Vorlage
async function blattPdfAmTyp(typId, adresse) {
  const r = await db.from("machine_types").update({ blatt_url: adresse }).eq("id", typId);
  if (r.error) throw r.error;
}

// Blatt an einer HOCO Nr. für genau einen Typ hinterlegen
async function blattPdfAnHoco(hocoNr, typId, adresse) {
  const r = await db.from("hoco_type_data")
    .upsert({ hoco_nr: hocoNr, type_id: typId, blatt_url: adresse },
            { onConflict: "hoco_nr,type_id" });
  if (r.error) throw r.error;
}

async function ladeBlattZeilen(sheetId) {
  const { data, error } = await zeitlimit(
    db.from("setup_sheet_slots").select("*, articles(article_number, name)")
      .eq("sheet_id", sheetId).order("sortierung").order("unter_nr"),
    12000, "Werkzeuge");
  if (error) throw error;
  return data || [];
}


// Trägt Plätze nach, die am Typ angelegt wurden, nachdem dieses Blatt
// entstanden ist. Bestehende Zeilen bleiben, wie sie sind.
// Fügt Zeilen ein und lässt Spalten weg, die es in der Tabelle nicht
// gibt. Die Datenbank meldet sie namentlich ("Could not find the 'x'
// column"), also nehmen wir sie heraus und versuchen es erneut. So
// läuft die App auch dort, wo eine Spalte fehlt oder anders heisst.
// Dasselbe fürs Ändern: unbekannte Spalten werden weggelassen.
async function aendernOhneUnbekannte(tabelle, daten, spalte, wert) {
  let satz = Object.assign({}, daten);
  const weggelassen = [];
  for (let versuch = 0; versuch < 6; versuch++) {
    const r = await db.from(tabelle).update(satz).eq(spalte, wert);
    if (!r.error) return { ok: true, weggelassen: weggelassen };
    const text = String((r.error && r.error.message) || "");
    const treffer = text.match(/find the '([^']+)' column/i)
      || text.match(/column "([^"]+)" of relation/i);
    if (!treffer) throw r.error;
    weggelassen.push(treffer[1]);
    delete satz[treffer[1]];
  }
  throw new Error("Zu viele unbekannte Spalten in " + tabelle);
}

async function einfuegenOhneUnbekannte(tabelle, zeilen) {
  let daten = Array.isArray(zeilen) ? zeilen : [zeilen];
  const weggelassen = [];

  for (let versuch = 0; versuch < 6; versuch++) {
    const r = await db.from(tabelle).insert(daten);
    if (!r.error) return { ok: true, weggelassen: weggelassen };

    const text = String((r.error && r.error.message) || "");
    const treffer = text.match(/find the '([^']+)' column/i)
      || text.match(/column "([^"]+)" of relation/i);
    if (!treffer) throw r.error;

    const spalte = treffer[1];
    weggelassen.push(spalte);
    daten = daten.map((z) => {
      const neu = Object.assign({}, z);
      delete neu[spalte];
      return neu;
    });
  }
  throw new Error("Zu viele unbekannte Spalten in " + tabelle);
}











// Auswahlliste mit Suchfeld. Gibt den gewählten Wert zurück,
// "__neu" für den Eintrag zum Anlegen, oder null beim Abbrechen.
function suchListe({ titel, eintraege, neuText, leerText }) {
  return new Promise((fertig) => {
    const h = document.createElement("div");
    h.className = "dialog-huelle";
    h.innerHTML = '<div class="dialog suchliste">'
      + '<h2>' + esc(titel) + '</h2>'
      + '<input type="search" class="suchliste__feld" placeholder="Suchen …" autocomplete="off">'
      + '<div class="suchliste__liste"></div>'
      + '<div class="dialog__knoepfe">'
      + (neuText ? '<button class="knopf" data-neu>' + esc(neuText) + '</button>' : "")
      + '<button class="knopf knopf--still" data-nein>Abbrechen</button></div></div>';
    document.body.appendChild(h);

    const feld = h.querySelector(".suchliste__feld");
    const liste = h.querySelector(".suchliste__liste");
    const ende = (w) => { h.remove(); fertig(w); };

    const zeigen = () => {
      const q = (feld.value || "").trim().toLowerCase();
      const treffer = eintraege.filter((e) => !q
        || (e.text + " " + (e.klein || "")).toLowerCase().indexOf(q) !== -1);
      liste.innerHTML = treffer.length
        ? treffer.map((e) => '<button class="suchliste__eintrag" data-w="' + esc(e.wert) + '">'
            + '<strong>' + esc(e.text) + '</strong>'
            + (e.klein ? '<span>' + esc(e.klein) + '</span>' : "") + '</button>').join("")
        : '<p class="hinweis">' + esc(q ? "Nichts gefunden." : (leerText || "Noch nichts vorhanden.")) + '</p>';
      liste.querySelectorAll("[data-w]").forEach((b) => { b.onclick = () => ende(b.dataset.w); });
    };
    feld.oninput = zeigen;
    zeigen();
    const neu = h.querySelector("[data-neu]");
    if (neu) neu.onclick = () => ende("__neu");
    h.querySelector("[data-nein]").onclick = () => ende(null);
    h.onclick = (e) => { if (e.target === h) ende(null); };
    setTimeout(() => feld.focus(), 50);
  });
}

// Werkzeug für einen Blattplatz wählen: zuerst Hersteller oder
// Lieferant, dann eines seiner Werkzeuge. Fehlt eines von beiden,
// wird es gleich hier angelegt.
async function werkzeugWaehlen(z) {
  // 1. Hersteller
  const l = await db.from("suppliers").select("id, name").order("name");
  if (l.error) throw l.error;
  const lieferanten = l.data || [];
  const lw = await suchListe({
    titel: "Hersteller für " + (z.tool_nr || "diesen Platz"),
    eintraege: lieferanten.map((x) => ({ wert: x.id, text: x.name })),
    neuText: "+ Neuer Hersteller",
    leerText: "Noch kein Hersteller angelegt." });
  if (!lw) return null;

  let lieferant;
  if (lw === "__neu") {
    // Dieselben Angaben wie beim Anlegen eines Lieferanten in den
    // Bestellungen — es ist ja auch derselbe Lieferant
    const w = await dialogFelder({ titel: "Neuer Hersteller",
      felder: [
        { name: "name", label: "Name", pflicht: true, platzhalter: "z. B. Sphinx, Iscar" },
        { name: "website", label: "Website", platzhalter: "www.beispiel.ch",
          hinweis: "Der Name wird dann überall in der App anklickbar." }],
      bestaetigen: "Anlegen" });
    if (!w) return null;
    let seite = (w.website || "").trim();
    if (seite && !/^https?:\/\//i.test(seite)) seite = "https://" + seite;
    const r = await db.from("suppliers")
      .insert({ name: w.name.trim(), website: seite || null }).select();
    if (r.error) throw r.error;
    lieferant = (r.data || [])[0];
  } else {
    lieferant = lieferanten.find((x) => x.id === lw);
  }
  if (!lieferant) return null;

  // 2. Werkzeug dieses Herstellers
  const a = await db.from("articles").select("id, article_number, name, description")
    .eq("supplier_id", lieferant.id).order("article_number");
  if (a.error) throw a.error;
  const artikel = (a.data || []).slice()
    .sort((x, y) => toolVergleich(x.article_number, y.article_number));
  const aw = await suchListe({
    titel: "Werkzeug von " + lieferant.name,
    eintraege: artikel.map((x) => ({ wert: x.id, text: x.article_number,
                                     klein: x.name || x.description || "" })),
    neuText: "+ Neues Werkzeug",
    leerText: "Von " + lieferant.name + " ist noch kein Werkzeug angelegt." });
  if (!aw) return null;

  let gewaehlt;
  if (aw === "__neu") {
    // Genau wie beim Bestellen: Artikelnummer, Beschreibung, Bezeichnung
    // aus der gepflegten Liste. Der Hersteller steht schon fest.
    gewaehlt = await artikelSchnellAnlegen("", lieferant.id);
    if (!gewaehlt) return null;
  } else {
    gewaehlt = artikel.find((x) => x.id === aw);
  }
  if (!gewaehlt) return null;
  return { lieferant: lieferant, artikel: gewaehlt };
}

// Die Ansicht der HOCO Nummern ist in src/hoco/.

// Anlegen und Bearbeiten in einem Dialog
async function hocoDialog(teil, vorgabe) {
  const v = vorgabe || {};
  const w = await dialogFelder({
    titel: teil ? "HOCO Nr. bearbeiten" : "Neue HOCO Nr.",
    felder: [
      ...(teil ? [] : [{ name: "nr", label: "HOCO Nr.", pflicht: true,
                        wert: v.hoco_nr || "",
                        platzhalter: "z. B. 10007-0414" }]),
      { name: "bez", label: "Artikelbezeichnung", wert: teil ? (teil.bezeichnung || "") : "" },
      { name: "mat", label: "Material",
        wert: teil ? (teil.material || "") : (v.material || ""),
        platzhalter: "z. B. X10CrNiS18-9 rd 011 mm h8",
        hinweis: "Alles in einem Feld, so wie es an der Stange steht" },
      { name: "zeichnung", label: "Zeichnungs Nr.", wert: teil ? (teil.zeichnungs_nr || "") : "" },
      { name: "infos", label: "Allgemeine Infos", wert: teil ? (teil.infos || "") : "" },
    ], bestaetigen: teil ? "Speichern" : "Anlegen" });
  if (!w) return false;

  const daten = {
    bezeichnung: w.bez || null,
    material: w.mat || null,
    zeichnungs_nr: w.zeichnung || null,
    infos: w.infos || null,
  };
  // Die Zeichnung gehört zum Teil und gilt für jeden Typ gleich.
  // Beim Anlegen wird sie aus dem Auftrag übernommen, falls dort eine hängt.
  if (!teil && v.zeichnung_url) daten.zeichnung_url = v.zeichnung_url;

  const nummer = teil ? teil.hoco_nr : (w.nr || "").trim();

  // Hängt an einem Auftrag mit dieser Nummer schon eine Zeichnung,
  // wird sie übernommen — sie ist für jeden Typ dieselbe.
  if (!teil && !v.zeichnung_url) {
    try {
      const r = await db.from("jobs").select("drawing_url")
        .eq("job_number", nummer).not("drawing_url", "is", null)
        .order("created_at", { ascending: false }).limit(1);
      const gefunden = ((r.data || [])[0] || {}).drawing_url;
      if (gefunden) v.zeichnung_url = gefunden;
    } catch (f) { /* geht auch ohne */ }
  }

  const { error } = teil
    ? await db.from("hoco_parts").update(daten).eq("hoco_nr", nummer)
    : await db.from("hoco_parts").insert({ ...daten, hoco_nr: nummer });

  if (error) { meldung(fehlertext(error), "fehler"); return false; }

  // Das Material auf die Aufträge übertragen, die noch nicht laufen.
  // Was läuft oder fertig ist, bleibt so, wie es damals war —
  // sonst würde sich Vergangenes rückwirkend ändern.
  let nachgezogen = 0;
  if (daten.material) {
    const u = await db.from("jobs")
      .update({ material_bez: daten.material })
      .eq("job_number", nummer)
      .is("ended_at", null)
      .in("plan_status", ["geplant", "ruesten"])
      .select();
    if (!u.error) nachgezogen = (u.data || []).length;
  }

  meldung(nachgezogen
    ? "Gespeichert. " + nachgezogen
      + (nachgezogen === 1 ? " geplanter Auftrag" : " geplante Aufträge")
      + " nachgezogen."
    : "Gespeichert.");
  return true;
}

// Parks und Maschinen verwalten ist in src/seiten/produktion/Maschinen.jsx.

function datumZeitKurz(iso) {
  if (!iso) return "";
  const d = new Date(iso);
  const p = (n) => String(n).padStart(2, "0");
  return p(d.getDate()) + "." + p(d.getMonth() + 1) + ". " + p(d.getHours()) + ":" + p(d.getMinutes());
}

// PDF so gross wie möglich: ganze Seite eingepasst, ohne Seitenleiste.
// Im Pad ohne Werkzeugleiste — Drucken und Speichern hat das Pad selbst.
function pdfGanz(adresse, ohneLeiste) {
  if (!adresse || String(adresse).indexOf("#") !== -1) return adresse;
  // Seitenbreite statt ganzer Seite: so füllt die Zeichnung den Bildschirm,
  // ohne dass man von Hand vergrössern muss
  return adresse + "#navpanes=0&view=FitH" + (ohneLeiste ? "&toolbar=0" : "");
}

// Zeigt ein PDF oder ein Bild in der App an, ohne Herunterladen.
function betrachter(adresse, titel, istPdf) {
  const huelle = document.createElement("div");
  huelle.className = "dialog-huelle betrachter-huelle";
  huelle.innerHTML = '<div class="betrachter">'
    + '<div class="betrachter__kopf">'
    + '<span class="betrachter__titel">' + esc(titel || "") + '</span>'
    + '<div class="betrachter__knoepfe">'
    + '<button class="knopf knopf--klein" data-drucken>Drucken</button>'
    + '<button class="knopf knopf--klein" data-speichern>Speichern</button>'
    + '<a class="knopf knopf--klein" href="' + esc(adresse) + '" target="_blank"'
    + ' rel="noopener">Neuer Tab</a>'
    + '<button class="knopf knopf--klein" data-zu>Schliessen</button>'
    + '</div></div>'
    + '<div class="betrachter__buehne">'
    + (istPdf
        ? '<iframe src="' + esc(pdfGanz(adresse)) + '" title="Zeichnung"></iframe>'
          + (isMobil() ? '<p class="betrachter__hinweis">Wird nichts angezeigt, öffne die Datei über '
          + '"Neuer Tab". Manche Handys zeigen PDFs nicht direkt in der App an.</p>' : "")
        : '<img src="' + esc(adresse) + '" alt="Foto">')
    + '</div></div>';
  document.body.appendChild(huelle);

  const zu = () => huelle.remove();
  huelle.querySelector("[data-zu]").onclick = zu;
  dialogSchliessen(huelle, zu);

  // Drucken: bei einem PDF über das eingebettete Fenster. Liegt die
  // Datei auf einem anderen Server, verweigert der Browser den
  // Zugriff darauf — dann bleibt der neue Tab als Weg.
  huelle.querySelector("[data-drucken]").onclick = () => {
    if (istPdf) {
      const rahmen = huelle.querySelector("iframe");
      try {
        rahmen.contentWindow.focus();
        rahmen.contentWindow.print();
        return;
      } catch (f) { /* andere Herkunft, also über den Umweg */ }
      const w = window.open(adresse, "_blank");
      if (!w) meldung("Zum Drucken bitte über \"Neuer Tab\" öffnen.", "warn");
      return;
    }
    // Bild: in einem eigenen Fenster, sonst würde die ganze App
    // mitgedruckt werden
    const w = window.open("", "_blank");
    if (!w) { meldung("Das Fenster wurde blockiert.", "warn"); return; }
    w.document.write('<!doctype html><html><head><meta charset="utf-8">'
      + '<title>' + esc(titel || "Bild") + '</title>'
      + '<style>@page{margin:10mm}body{margin:0}'
      + 'img{max-width:100%;height:auto;display:block}</style></head><body>'
      + '<img src="' + esc(adresse) + '" onload="window.print()"></body></html>');
    w.document.close();
  };

  // Speichern: erst versuchen, die Datei wirklich herunterzuladen.
  // Klappt das wegen der Herkunft nicht, öffnet sie sich stattdessen.
  huelle.querySelector("[data-speichern]").onclick = async () => {
    const name = (titel || "Datei").replace(/[^A-Za-z0-9._-]+/g, "_")
      + (istPdf ? ".pdf" : ".jpg");
    try {
      const antwort = await fetch(adresse);
      if (!antwort.ok) throw new Error("nicht erreichbar");
      const brocken = await antwort.blob();
      const url = URL.createObjectURL(brocken);
      const a = document.createElement("a");
      a.href = url; a.download = name;
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 4000);
    } catch (f) {
      const a = document.createElement("a");
      a.href = adresse; a.download = name; a.target = "_blank";
      a.rel = "noopener";
      document.body.appendChild(a); a.click(); a.remove();
    }
  };
}

