// Bezeichnung aus der Liste wählen oder eine neue anlegen
async function bezeichnungWaehlen(liste, aktuell) {
  const wahl = await auswahlSuchen("Bezeichnung wählen",
    (liste || []).map((z) => ({ wert: z.name, text: z.name }))
      .concat([{ wert: "__neu", text: "+ Neue Bezeichnung anlegen" }]));
  if (!wahl) return null;

  if (wahl !== "__neu") return wahl;

  const w = await dialogFelder({ titel: "Neue Bezeichnung",
    felder: [{ name: "name", label: "Bezeichnung", pflicht: true,
               wert: aktuell || "" }], bestaetigen: "Anlegen" });
  if (!w) return null;

  const { error } = await db.from("designations").insert({ name: w.name });
  if (error && !String(error.message || "").includes("duplicate")) {
    meldung(fehlertext(error), "fehler");
    return null;
  }
  meldung("Bezeichnung angelegt.");
  return w.name;
}

async function ladeBezeichnungen() {
  const { data, error } = await zeitlimit(
    db.from("designations").select("*").order("name"), 8000, "Bezeichnungen");
  if (error) throw error;
  return data || [];
}

async function ladeLieferanten() {
  const { data, error } = await zeitlimit(
    db.from("suppliers").select("*").order("name"), 10000, "Lieferanten");
  if (error) throw error;
  // Steht nichts drin, gilt der Lieferant als aktiv. Sonst
  // verschwinden alte Einträge stillschweigend aus der Auswahl.
  return (data || []).filter((l) => l.is_active !== false);
}

async function sucheArtikel(text) {
  const t = (text || "").trim();
  let abfrage = db.from("artikel_uebersicht").select("*");
  if (t) {
    abfrage = abfrage.or("article_number.ilike.%" + t + "%,name.ilike.%" + t
      + "%,supplier_name.ilike.%" + t + "%");
  }
  const { data, error } = await zeitlimit(abfrage.order("article_number").limit(50),
    12000, "Artikelsuche");
  if (error) throw error;
  return data || [];
}

