// =================================================================
//  C-ACHSE, POLARINTERPOLATION (Fanuc G12.1 / G13.1)
//  Vierkant, Sechskant, Rechteck und Torx auf der Drehmaschine
//  fräsen. Gerechnet wird die Bahn der Fräsermitte — mit Polar-
//  interpolation ist die Schneidenradiuskorrektur meist gesperrt.
// =================================================================

// Vor- und Nachspann gelten für alle Erzeuger. Hier gehört hinein,
// was die Maschine braucht und was ich nicht wissen kann: Programm-
// nummer, Nullpunkt, C-Achse zuschalten, Frässpindel einschalten.
const maschinenkopf = {
  vor: "",
  nach: "",
};

function kopfZeilen() {
  return (maschinenkopf.vor || "").split(/\r?\n/).filter((z) => z.trim());
}
function fussZeilen() {
  return (maschinenkopf.nach || "").split(/\r?\n/).filter((z) => z.trim());
}

function kopfFelder() {
  return '<details class="gc-kopf"><summary>Vor- und Nachspann für die Maschine</summary>'
    + '<p class="klein">Diese Zeilen werden unverändert vor und nach dem erzeugten '
    + 'Teil eingesetzt. Hier gehört hinein, was von der Maschine abhängt: '
    + 'Programmkopf, Nullpunkt, C-Achse zuschalten, Frässpindel ein und aus. '
    + 'Die Angaben bleiben für alle Erzeuger gleich.</p>'
    + '<label class="feld"><span>Vorspann</span>'
    + '<textarea data-gckopf="vor" rows="4" placeholder="z. B.&#10;M110 ( C-Achse ein )'
    + '&#10;M80 S3000 ( Fraesspindel )">' + esc(maschinenkopf.vor) + '</textarea></label>'
    + '<label class="feld"><span>Nachspann</span>'
    + '<textarea data-gckopf="nach" rows="3" placeholder="z. B.&#10;M81 ( Fraesspindel aus )'
    + '&#10;M111 ( C-Achse aus )">' + esc(maschinenkopf.nach) + '</textarea></label>'
    + '</details>';
}

function kopfBinden(ziel, neuZeichnen) {
  ziel.querySelectorAll("[data-gckopf]").forEach((el) => {
    let taste = null;
    el.oninput = () => {
      clearTimeout(taste);
      taste = setTimeout(() => {
        maschinenkopf[el.dataset.gckopf] = el.value;
        einstellungSetzenWert("gckopf" + el.dataset.gckopf, el.value);
        neuZeichnen();
      }, 600);
    };
  });
}

// Gespeicherte Angaben zurückholen
try {
  maschinenkopf.vor = einstellungWert("gckopfvor", "") || "";
  maschinenkopf.nach = einstellungWert("gckopfnach", "") || "";
} catch (f) { /* dann eben leer */ }

const caxis = {
  form: "vierkant",
  sw: 17,            // Schlüsselweite
  breite: 20,        // Rechteck
  hoehe: 12,
  torxA: 9.5,        // Torx aussen über die Spitzen
  torxB: 7.9,        // Torx über die Täler
  eckR: 0.4,         // Eckenradius
  fraeser: 8,        // Fräserdurchmesser
  tiefeZ: 6,         // Frästiefe in Z
  zustellung: 1.5,   // je Schnitt
  aufmass: 0,        // Schlichtaufmass
  vorschub: 60,      // mm/min
  drehzahl: 2000,    // Fräser
  sicher: 2,         // Sicherheitsabstand
  zStart: 0,         // Stirnfläche
  richtung: "gleich",
  schritt: 0,        // Stellung des Fräsers in der Vorschau, 0…1
  laeuft: false,
};

// ---------- Geometrie ----------

// Punkte der Fräsermitte für ein regelmässiges Vieleck mit
// Schlüsselweite sw, n Ecken und Eckenradius rc, aussen gefräst.
function caxisVieleck(n, sw, rc, rFraes) {
  const a = sw / 2;                      // Abstand Mitte zur Fläche
  const halb = Math.PI / n;
  // Mitte des Eckenradius, auf der Winkelhalbierenden
  const mEck = Math.max(0, (a - rc)) / Math.cos(halb);
  const stuecke = [];

  for (let i = 0; i < n; i++) {
    const w = (2 * Math.PI * i) / n + halb;   // Richtung zur Ecke
    stuecke.push({
      art: "ecke",
      cx: mEck * Math.cos(w),
      cy: mEck * Math.sin(w),
      r: rc + rFraes,
    });
  }
  return { stuecke: stuecke, aussen: a + rFraes };
}

// Dasselbe für ein Rechteck
function caxisRechteck(b, h, rc, rFraes) {
  const x = b / 2, y = h / 2;
  const ecken = [[1, 1], [-1, 1], [-1, -1], [1, -1]];
  // gegen den Uhrzeigersinn, beginnend rechts oben
  const stuecke = ecken.map(([sx, sy]) => ({
    art: "ecke",
    cx: sx * Math.max(0, x - rc),
    cy: sy * Math.max(0, y - rc),
    r: rc + rFraes,
  }));
  return { stuecke: stuecke, aussen: Math.hypot(x, y) + rFraes };
}

// Aus den Eckenkreisen die Bahn bauen: Tangente, Bogen, Tangente …
function caxisBahn(form) {
  const rF = caxis.fraeser / 2;
  const rc = Math.max(0, caxis.eckR);
  let g;

  if (form === "vierkant") g = caxisVieleck(4, caxis.sw, rc, rF);
  else if (form === "sechskant") g = caxisVieleck(6, caxis.sw, rc, rF);
  else if (form === "rechteck") g = caxisRechteck(caxis.breite, caxis.hoehe, rc, rF);
  else return caxisTorxBahn();

  const k = g.stuecke;
  const bahn = [];

  for (let i = 0; i < k.length; i++) {
    const a = k[i], b = k[(i + 1) % k.length];
    // Gemeinsame äussere Tangente zweier gleich grosser Kreise:
    // die Verbindung der Mitten, um den Radius nach aussen versetzt
    const dx = b.cx - a.cx, dy = b.cy - a.cy;
    const laenge = Math.hypot(dx, dy) || 1;
    // Nach aussen zeigt die Normale, die vom Mittelpunkt wegweist
    let nx = -dy / laenge, ny = dx / laenge;
    if (nx * (a.cx + b.cx) + ny * (a.cy + b.cy) < 0) { nx = -nx; ny = -ny; }

    bahn.push({ art: "gerade",
      von: [a.cx + nx * a.r, a.cy + ny * a.r],
      bis: [b.cx + nx * b.r, b.cy + ny * b.r] });
    bahn.push({ art: "bogen", mitte: [b.cx, b.cy], r: b.r });
  }
  return { bahn: bahn, aussen: g.aussen };
}

// Torx nur angenähert: sechs Lappen als weiche Kurve zwischen dem
// Kreis über die Spitzen und dem über die Täler. Kein Ersatz für
// eine geprüfte Lehre.
function caxisTorxBahn() {
  const rF = caxis.fraeser / 2;
  const gross = caxis.torxA / 2, klein = caxis.torxB / 2;
  const mitte = (gross + klein) / 2, welle = (gross - klein) / 2;
  const punkte = [];
  const schritte = 360;

  for (let i = 0; i <= schritte; i++) {
    const w = (2 * Math.PI * i) / schritte;
    const r = mitte + welle * Math.cos(6 * w);
    // Ableitung für die Normale, damit der Fräser sauber versetzt wird
    const dr = -6 * welle * Math.sin(6 * w);
    const px = r * Math.cos(w), py = r * Math.sin(w);
    const tx = dr * Math.cos(w) - r * Math.sin(w);
    const ty = dr * Math.sin(w) + r * Math.cos(w);
    const tl = Math.hypot(tx, ty) || 1;
    punkte.push([px + (ty / tl) * rF, py - (tx / tl) * rF]);
  }
  return { bahn: [{ art: "punkte", punkte: punkte }], aussen: gross + rF };
}

// ---------- G-Code ----------

// Passt der Fräser überhaupt in die engste Innenecke? Bei zu grossem
// Werkzeug überschneidet sich die Bahn und es entstehen Schleifen,
// die Material wegnehmen würden, das stehen bleiben soll.
function caxisPasst() {
  const rF = caxis.fraeser / 2;

  if (caxis.form === "torx") {
    const gross = caxis.torxA / 2, klein = caxis.torxB / 2;
    const m = (gross + klein) / 2, welle = (gross - klein) / 2;
    let engster = Infinity;
    for (let i = 0; i <= 360; i++) {
      const w = (Math.PI * i) / 180;
      const r = m + welle * Math.cos(6 * w);
      const r1 = -6 * welle * Math.sin(6 * w);
      const r2 = -36 * welle * Math.cos(6 * w);
      const oben = Math.pow(r * r + r1 * r1, 1.5);
      const unten = r * r + 2 * r1 * r1 - r * r2;
      if (unten > 0) engster = Math.min(engster, oben / unten);
    }
    if (rF > engster) {
      return { ok: false,
        text: "Der Fräser ist zu gross für die Täler. Dort sitzt ein Radius von "
          + engster.toFixed(2) + " mm, der Fräserradius misst " + rF.toFixed(2)
          + " mm. Höchstens Ø" + (engster * 2).toFixed(1)
          + " mm verwenden, sonst schneidet er die Lappen ab." };
    }
    return { ok: true };
  }

  const kurz = caxis.form === "rechteck"
    ? Math.min(caxis.breite, caxis.hoehe) : caxis.sw;
  if (caxis.fraeser > kurz) {
    return { ok: false,
      text: "Der Fräser ist breiter als die kürzeste Seite (" + kurz
        + " mm). Das geht nicht sauber — kleineres Werkzeug wählen." };
  }
  return { ok: true };
}

function caxisGcode() {
  const { bahn, aussen } = caxisBahn(caxis.form);
  const z = [];
  const f = caxis.vorschub;
  const anfahrt = aussen + caxis.sicher;
  const gegen = caxis.richtung === "gegen";

  z.push("( C-ACHSE " + caxis.form.toUpperCase() + " )");
  kopfZeilen().forEach((x) => z.push(x));
  z.push("( Fraeser D" + caxis.fraeser.toFixed(2)
    + "  Bahn = Fraesermitte, keine Radiuskorrektur )");
  // Steht ein eigener Vorspann da, gilt der — sonst wäre M3 auf der
  // Hauptspindel und damit auf einer Langdrehmaschine falsch.
  if (!kopfZeilen().length) {
    z.push("M" + (gegen ? "4" : "3") + "S" + Math.round(caxis.drehzahl)
      + "  ( Fraeser )");
  }
  z.push("G0X" + (anfahrt * 2).toFixed(3) + "C0.");
  z.push("G0Z" + (caxis.zStart + caxis.sicher).toFixed(3));
  z.push("G12.1  ( Polarinterpolation ein )");

  const schnitte = Math.max(1, Math.ceil(caxis.tiefeZ / Math.max(0.1, caxis.zustellung)));

  for (let s = 1; s <= schnitte; s++) {
    const tiefe = Math.min(caxis.tiefeZ, s * caxis.zustellung);
    z.push("( Schnitt " + s + " von " + schnitte + ", Z-"
      + tiefe.toFixed(2) + " )");
    z.push("G0Z" + (caxis.zStart - tiefe).toFixed(3));

    if (bahn[0].art === "punkte") {
      const p = bahn[0].punkte;
      z.push("G0X" + (p[0][0] * 2).toFixed(3) + "C" + p[0][1].toFixed(3));
      p.slice(1).forEach((q) => {
        z.push("G1X" + (q[0] * 2).toFixed(3) + "C" + q[1].toFixed(3) + "F" + f);
      });
    } else {
      const erst = bahn[0];
      z.push("G0X" + (erst.von[0] * 2).toFixed(3) + "C" + erst.von[1].toFixed(3));
      bahn.forEach((st, i) => {
        if (st.art === "gerade") {
          z.push("G1X" + (st.bis[0] * 2).toFixed(3) + "C" + st.bis[1].toFixed(3)
            + (i === 0 ? "F" + f : ""));
        } else {
          const naechste = bahn[(bahn.indexOf(st) + 1) % bahn.length];
          const ziel = naechste.art === "gerade" ? naechste.von : null;
          if (ziel) {
            // Aussenecke: die Fräsermitte fährt einen Bogen um die Ecke
            z.push("G3X" + (ziel[0] * 2).toFixed(3) + "C" + ziel[1].toFixed(3)
              + "R" + st.r.toFixed(3));
          }
        }
      });
    }
  }

  z.push("G0X" + (anfahrt * 2).toFixed(3));
  z.push("G13.1  ( Polarinterpolation aus )");
  z.push("G0Z" + (caxis.zStart + caxis.sicher + 5).toFixed(3));
  fussZeilen().forEach((x) => z.push(x));
  if (!fussZeilen().length) z.push("M5");
  return z.join("\n");
}

// ---------- Zeichnung ----------

// Die Bahn als durchgehende Punktfolge — daraus lässt sich der
// Fräser Schritt für Schritt durchschieben.
function caxisPunkte() {
  const { bahn } = caxisBahn(caxis.form);
  if (!bahn.length) return [];
  if (bahn[0].art === "punkte") return bahn[0].punkte.slice();

  const punkte = [];
  bahn.forEach((st, i) => {
    if (st.art === "gerade") {
      punkte.push(st.von, st.bis);
    } else {
      // Aussenecke: den Bogen in kleine Schritte zerlegen
      const vorher = punkte[punkte.length - 1];
      const naechste = bahn[(i + 1) % bahn.length];
      const nach = naechste.art === "gerade" ? naechste.von : null;
      if (!vorher || !nach) return;
      const w1 = Math.atan2(vorher[1] - st.mitte[1], vorher[0] - st.mitte[0]);
      let w2 = Math.atan2(nach[1] - st.mitte[1], nach[0] - st.mitte[0]);
      while (w2 < w1) w2 += 2 * Math.PI;
      const n = Math.max(3, Math.round(((w2 - w1) * 180) / Math.PI / 6));
      for (let k = 1; k <= n; k++) {
        const w = w1 + ((w2 - w1) * k) / n;
        punkte.push([st.mitte[0] + st.r * Math.cos(w),
                     st.mitte[1] + st.r * Math.sin(w)]);
      }
    }
  });
  return punkte;
}

function caxisNurBildNeu() {
  const alt = document.getElementById("cax-bild");
  if (!alt) return;
  const huelle = document.createElement("div");
  huelle.innerHTML = caxisBild();
  alt.replaceWith(huelle.firstElementChild);
}

function caxisAblauf() {
  if (!caxis.laeuft) return;
  caxis.schritt += 0.004;
  if (caxis.schritt > 1) caxis.schritt = 0;
  const schieber = document.getElementById("cax-schieber");
  if (schieber) schieber.value = Math.round(caxis.schritt * 1000);
  caxisNurBildNeu();
  requestAnimationFrame(caxisAblauf);
}

function caxisBild() {
  const { bahn, aussen } = caxisBahn(caxis.form);
  const gr = Math.max(aussen, 1) * 1.25;
  const s = 150 / gr;                       // Massstab auf 300 × 300
  const p = ([x, y]) => (150 + x * s).toFixed(1) + "," + (150 - y * s).toFixed(1);

  let form = "";
  if (caxis.form === "torx") {
    const punkte = bahn[0].punkte.map(p).join(" ");
    form = '<polyline points="' + punkte + '" class="cax-bahn"/>';
  } else {
    const teile = [];
    bahn.forEach((st) => {
      if (st.art === "gerade") {
        teile.push((teile.length ? "L" : "M") + p(st.von) + " L" + p(st.bis));
      }
    });
    // Ecken als Bögen dazwischen
    let d = "";
    bahn.forEach((st, i) => {
      if (st.art !== "gerade") return;
      d += (i === 0 ? "M" : "L") + p(st.von) + " L" + p(st.bis) + " ";
      const bogen = bahn[i + 1];
      const naechste = bahn[(i + 2) % bahn.length];
      if (bogen && naechste) {
        d += "A" + (bogen.r * s).toFixed(1) + "," + (bogen.r * s).toFixed(1)
          + " 0 0 0 " + p(naechste.von) + " ";
      }
    });
    form = '<path d="' + d + 'Z" class="cax-bahn"/>';
  }

  // Das fertige Teil, also die Bahn ohne Fräserradius
  const rF = caxis.fraeser / 2;
  let teil = "";
  if (caxis.form === "vierkant" || caxis.form === "sechskant") {
    const n = caxis.form === "vierkant" ? 4 : 6;
    const a = caxis.sw / 2, halb = Math.PI / n;
    const rEck = a / Math.cos(halb);
    const ecken = [];
    for (let i = 0; i < n; i++) {
      const w = (2 * Math.PI * i) / n + halb;
      ecken.push(p([rEck * Math.cos(w), rEck * Math.sin(w)]));
    }
    teil = '<polygon points="' + ecken.join(" ") + '" class="cax-teil"/>';
  } else if (caxis.form === "rechteck") {
    const x = caxis.breite / 2, y = caxis.hoehe / 2;
    teil = '<polygon points="' + [[x, y], [-x, y], [-x, -y], [x, -y]].map(p).join(" ")
      + '" class="cax-teil"/>';
  } else {
    const gross = caxis.torxA / 2, klein = caxis.torxB / 2;
    const m = (gross + klein) / 2, welle = (gross - klein) / 2;
    const pts = [];
    for (let i = 0; i <= 240; i++) {
      const w = (2 * Math.PI * i) / 240;
      const r = m + welle * Math.cos(6 * w);
      pts.push(p([r * Math.cos(w), r * Math.sin(w)]));
    }
    teil = '<polyline points="' + pts.join(" ") + '" class="cax-teil"/>';
  }

  // Massangabe
  let mass = "";
  if (caxis.form === "vierkant" || caxis.form === "sechskant") {
    const y = (caxis.sw / 2) * s;
    mass = '<line x1="150" y1="' + (150 - y) + '" x2="150" y2="' + (150 + y)
      + '" class="cax-mass"/>'
      + '<text x="156" y="150" class="cax-text">SW ' + caxis.sw + '</text>';
  } else if (caxis.form === "rechteck") {
    mass = '<text x="150" y="' + (150 - (caxis.hoehe / 2) * s - 6)
      + '" class="cax-text" text-anchor="middle">' + caxis.breite + ' × '
      + caxis.hoehe + '</text>';
  } else {
    mass = '<text x="150" y="16" class="cax-text" text-anchor="middle">A '
      + caxis.torxA + ' · B ' + caxis.torxB + '</text>';
  }

  // Fräser an seiner Stelle und der schon gefahrene Weg
  const folge = caxisPunkte();
  let werkzeug = "";
  if (folge.length) {
    const i = Math.min(folge.length - 1,
      Math.max(0, Math.round(caxis.schritt * (folge.length - 1))));
    const [wx, wy] = folge[i];
    werkzeug = '<polyline points="' + folge.slice(0, i + 1).map(p).join(" ")
      + '" class="dxf-gefahren"/>'
      + '<circle cx="' + (150 + wx * s).toFixed(1)
      + '" cy="' + (150 - wy * s).toFixed(1)
      + '" r="' + Math.max(2.5, (caxis.fraeser / 2) * s).toFixed(1)
      + '" class="dxf-fraeser"/>';
  }

  return '<svg viewBox="0 0 300 300" class="cax-bild" id="cax-bild">'
    + '<circle cx="150" cy="150" r="2" class="cax-mitte"/>'
    + teil + form + werkzeug + mass
    + '<text x="8" y="292" class="cax-legende">— Teil</text>'
    + '<text x="70" y="292" class="cax-legende cax-legende--bahn">— Fräsermitte</text>'
    + '</svg>';
}

// ---------- Seite ----------

function rechnerCachse(ziel) {
  const zahl = (name, text, schritt, hinweis) =>
    '<label class="feld"><span>' + text + '</span>'
    + '<input type="number" data-cax="' + name + '" step="' + (schritt || "0.1")
    + '" value="' + caxis[name] + '">'
    + (hinweis ? '<span class="feldhinweis">' + hinweis + '</span>' : "")
    + '</label>';

  const formfelder = caxis.form === "rechteck"
    ? zahl("breite", "Breite in mm") + zahl("hoehe", "Höhe in mm")
    : (caxis.form === "torx"
        ? zahl("torxA", "A über die Spitzen") + zahl("torxB", "B über die Täler")
        : zahl("sw", "Schlüsselweite SW"));

  ladeFertig(ziel);
  ziel.innerHTML = '<div class="karte">'
    + '<div class="moduswahl" id="cax-formen">'
    + [["vierkant", "Vierkant"], ["sechskant", "Sechskant"],
       ["rechteck", "Rechteck"], ["torx", "Torx"]]
      .map(([w, t]) => '<button type="button" class="moduswahl__knopf'
        + (caxis.form === w ? " aktiv" : "") + '" data-caxform="' + w + '">'
        + t + '</button>').join("")
    + '</div>'

    + '<div class="cax-raster">'
    + '<div class="cax-bildfeld">' + caxisBild()
    + '<div class="dxf-steuer">'
    + '<button class="knopf knopf--klein" id="cax-los">'
    + (caxis.laeuft ? "Halt" : "Ablauf zeigen") + '</button>'
    + '<input type="range" id="cax-schieber" min="0" max="1000" value="'
    + Math.round(caxis.schritt * 1000) + '">'
    + '</div></div>'
    + '<div class="cax-felder">'
    + formfelder
    + zahl("eckR", "Eckenradius am Teil")
    + zahl("fraeser", "Fräserdurchmesser")
    + zahl("tiefeZ", "Frästiefe in Z")
    + zahl("zustellung", "Zustellung je Schnitt")
    + zahl("zStart", "Z an der Stirnfläche")
    + zahl("sicher", "Sicherheitsabstand")
    + zahl("vorschub", "Vorschub mm/min", "1")
    + zahl("drehzahl", "Drehzahl Fräser", "50")
    + '<label class="feld"><span>Fräsrichtung</span>'
    + '<select data-cax="richtung">'
    + '<option value="gleich"' + (caxis.richtung === "gleich" ? " selected" : "")
    + '>Gleichlauf (M3)</option>'
    + '<option value="gegen"' + (caxis.richtung === "gegen" ? " selected" : "")
    + '>Gegenlauf (M4)</option></select></label>'
    + '</div></div>'

    + '<p class="klein">Ausgegeben wird die Bahn der Fräsermitte in X und C. '
    + 'Bei Polarinterpolation ist die Radiuskorrektur auf den meisten Steuerungen '
    + 'gesperrt, deshalb steht der Fräserradius schon in den Werten. '
    + 'X ist im Durchmesser programmiert.'
    + (caxis.form === "torx"
        ? ' <strong>Torx ist angenähert</strong> — sechs Lappen aus A und B, '
          + 'keine geprüfte Norm­geometrie. Vor dem Einsatz an der Lehre prüfen.'
        : "")
    + '</p>'
    + (() => {
        const pruef = caxisPasst();
        return pruef.ok ? ""
          : '<p class="karte karte--fehler cax-warnung">' + esc(pruef.text) + '</p>';
      })()
    + kopfFelder()
    + '<pre class="gcode">' + esc(caxisGcode()) + '</pre>'
    + '<button class="knopf knopf--klein" id="cax-kopieren">G-Code kopieren</button>'
    + '</div>';

  ziel.querySelectorAll("[data-caxform]").forEach((el) => {
    el.onclick = () => {
      caxis.form = el.dataset.caxform;
      caxis.laeuft = false;
      caxis.schritt = 0;
      rechnerCachse(ziel);
    };
  });
  ziel.querySelectorAll("[data-cax]").forEach((el) => {
    el.onchange = () => {
      const name = el.dataset.cax;
      caxis[name] = el.type === "number" ? Number(el.value) : el.value;
      caxis.laeuft = false;
      caxis.schritt = 0;
      rechnerCachse(ziel);
    };
  });
  const schieber = document.getElementById("cax-schieber");
  if (schieber) schieber.oninput = () => {
    caxis.schritt = Number(schieber.value) / 1000;
    caxisNurBildNeu();
  };

  const los = document.getElementById("cax-los");
  if (los) los.onclick = () => {
    caxis.laeuft = !caxis.laeuft;
    los.textContent = caxis.laeuft ? "Halt" : "Ablauf zeigen";
    if (caxis.laeuft) caxisAblauf();
  };

  kopfBinden(ziel, () => rechnerCachse(ziel));

  const kopieren = document.getElementById("cax-kopieren");
  if (kopieren) kopieren.onclick = async () => {
    try {
      await navigator.clipboard.writeText(caxisGcode());
      meldung("G-Code kopiert.");
    } catch (f) { meldung("Kopieren ging nicht. Bitte von Hand markieren.", "warn"); }
  };
}


// =================================================================
//  GRAVUR: TEXT ALS G-CODE
//  Der Text wird mit der gewählten Schrift auf eine unsichtbare
//  Leinwand gezeichnet, die Umrisse werden daraus abgetastet und in
//  Bahnen umgerechnet. Dadurch lässt sich jede Schrift benutzen,
//  die auf dem Rechner installiert ist.
//
//  Stirnseite  → G12.1, X und C wie X und Y
//  Mantel      → G07.1, Z und C, C im Winkel über den Umfang
// =================================================================

const gravur = {
  text: "HOFER",
  schrift: "Arial",
  fett: false,
  kursiv: false,
  hoehe: 4,          // Zeichenhöhe in mm
  laufweite: 0,      // zusätzlicher Abstand je Zeichen
  flaeche: "stirn",  // stirn oder mantel
  dm: 20,            // Durchmesser des Teils
  radius: 8,         // Abstand der Textmitte von der Achse, Stirnseite
  winkel: 0,         // Drehung auf der Stirnseite
  zStart: 0,
  tiefe: 0.2,
  schnitte: 1,
  vorschub: 80,
  eilgang: 1,        // Abhebehöhe zwischen den Zügen
  drehzahl: 6000,
  werkzeug: 0.4,     // Spitzendurchmesser, nur für die Warnung
  glaetten: 0.02,    // Toleranz beim Vereinfachen in mm
  art: "stichel",    // stichel oder fraeser
  ausraeumen: false, // beim Fräser die Buchstaben ganz ausräumen
  schritt: 0,        // Stellung des Werkzeugs in der Vorschau, 0…1
  laeuft: false,
};

const GRAVUR_SCHRIFTEN = [
  "Arial", "Arial Black", "Bahnschrift", "Calibri", "Cambria", "Candara",
  "Comic Sans MS", "Consolas", "Constantia", "Corbel", "Courier New",
  "Ebrima", "Franklin Gothic Medium", "Gabriola", "Georgia", "Impact",
  "Ink Free", "Lucida Console", "Lucida Sans Unicode", "Malgun Gothic",
  "Microsoft Sans Serif", "Palatino Linotype", "Segoe Print", "Segoe Script",
  "Segoe UI", "Sitka", "Sylfaen", "Tahoma", "Times New Roman",
  "Trebuchet MS", "Verdana",
];

// ---------- Umrisse aus der Schrift holen ----------

// Zeichnet den Text gross auf eine Leinwand und liest die Umrisse
// mit Marching Squares aus. Zurück kommen Linienzüge in Millimetern.
function gravurKonturen() {
  const text = (gravur.text || "").trim();
  if (!text) return { zuege: [], breite: 0, hoehe: 0 };

  // Gross rendern, damit die Kanten fein genug werden
  const px = 220;                       // Zeichenhöhe auf der Leinwand
  const stil = (gravur.kursiv ? "italic " : "") + (gravur.fett ? "bold " : "");
  const schriftart = stil + px + 'px "' + gravur.schrift + '", sans-serif';

  const mess = document.createElement("canvas").getContext("2d");
  mess.font = schriftart;
  const m = mess.measureText(text);
  const extra = gravur.laufweite > 0
    ? (text.length - 1) * (gravur.laufweite / gravur.hoehe) * px : 0;
  const breitePx = Math.ceil(m.width + extra) + 20;
  const obenPx = Math.ceil(m.actualBoundingBoxAscent || px * 0.8);
  const untenPx = Math.ceil(m.actualBoundingBoxDescent || px * 0.25);
  const hoehePx = obenPx + untenPx + 20;

  const c = document.createElement("canvas");
  c.width = breitePx; c.height = hoehePx;
  const g = c.getContext("2d");
  g.fillStyle = "#fff"; g.fillRect(0, 0, c.width, c.height);
  g.fillStyle = "#000";
  g.font = schriftart;
  g.textBaseline = "alphabetic";

  if (extra > 0) {
    // Buchstabe für Buchstabe, damit die Laufweite wirkt
    let x = 10;
    for (const zeichen of text) {
      g.fillText(zeichen, x, obenPx + 10);
      x += g.measureText(zeichen).width + (gravur.laufweite / gravur.hoehe) * px;
    }
  } else {
    g.fillText(text, 10, obenPx + 10);
  }

  const bild = g.getImageData(0, 0, c.width, c.height).data;
  const dunkel = (x, y) => {
    if (x < 0 || y < 0 || x >= c.width || y >= c.height) return 0;
    return bild[(y * c.width + x) * 4] < 128 ? 1 : 0;
  };

  // Marching Squares: Kanten zwischen hell und dunkel einsammeln
  const kanten = new Map();
  const schluessel = (x, y) => x + "," + y;
  const merken = (a, b) => {
    const k = schluessel(a[0], a[1]);
    if (!kanten.has(k)) kanten.set(k, []);
    kanten.get(k).push(b);
  };

  for (let y = 0; y < c.height - 1; y++) {
    for (let x = 0; x < c.width - 1; x++) {
      const fall = dunkel(x, y) * 8 + dunkel(x + 1, y) * 4
        + dunkel(x + 1, y + 1) * 2 + dunkel(x, y + 1);
      if (fall === 0 || fall === 15) continue;
      const o = [x + 0.5, y], r = [x + 1, y + 0.5];
      const u = [x + 0.5, y + 1], l = [x, y + 0.5];
      const strich = {
        1: [[l, u]], 2: [[u, r]], 3: [[l, r]], 4: [[r, o]],
        5: [[l, o], [u, r]], 6: [[u, o]], 7: [[l, o]],
        8: [[o, l]], 9: [[o, u]], 10: [[o, r], [u, l]], 11: [[o, r]],
        12: [[r, l]], 13: [[r, u]], 14: [[u, l]],
      }[fall] || [];
      strich.forEach(([a, b]) => merken(a, b));
    }
  }

  // Kanten zu geschlossenen Zügen verketten
  const zuege = [];
  const offen = new Map(kanten);
  while (offen.size) {
    const start = offen.keys().next().value;
    let jetzt = start;
    const zug = [];
    let schutz = 0;
    while (offen.has(jetzt) && schutz++ < 200000) {
      const liste = offen.get(jetzt);
      const naechste = liste.pop();
      if (!liste.length) offen.delete(jetzt);
      zug.push(naechste);
      jetzt = schluessel(naechste[0], naechste[1]);
    }
    if (zug.length > 8) zuege.push(zug);
  }

  // In Millimeter umrechnen und vereinfachen
  const skala = gravur.hoehe / px;
  const fein = zuege.map((z) => vereinfachen(
    z.map(([x, y]) => [x * skala, -y * skala]),
    Math.max(0.005, gravur.glaetten)));

  // Auf die Mitte legen
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  fein.forEach((z) => z.forEach(([x, y]) => {
    minX = Math.min(minX, x); maxX = Math.max(maxX, x);
    minY = Math.min(minY, y); maxY = Math.max(maxY, y);
  }));
  const mx = (minX + maxX) / 2, my = (minY + maxY) / 2;
  const mittig = fein.map((z) => z.map(([x, y]) => [x - mx, y - my]));

  return { zuege: mittig, breite: maxX - minX, hoehe: maxY - minY };
}

// Douglas-Peucker: entfernt Punkte, die kaum von der Linie abweichen
function vereinfachen(punkte, toleranz) {
  if (punkte.length < 3) return punkte;
  const abstand = (p, a, b) => {
    const dx = b[0] - a[0], dy = b[1] - a[1];
    const l = dx * dx + dy * dy;
    if (!l) return Math.hypot(p[0] - a[0], p[1] - a[1]);
    let t = ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / l;
    t = Math.max(0, Math.min(1, t));
    return Math.hypot(p[0] - (a[0] + t * dx), p[1] - (a[1] + t * dy));
  };
  const lauf = (von, bis) => {
    let weit = 0, wo = von;
    for (let i = von + 1; i < bis; i++) {
      const d = abstand(punkte[i], punkte[von], punkte[bis]);
      if (d > weit) { weit = d; wo = i; }
    }
    if (weit > toleranz) {
      return lauf(von, wo).slice(0, -1).concat(lauf(wo, bis));
    }
    return [punkte[von], punkte[bis]];
  };
  return lauf(0, punkte.length - 1);
}

// ---------- Bahn für einen Schaftfräser ----------

// Fläche mit Vorzeichen: sagt, ob ein Zug gegen oder im Uhrzeigersinn
// läuft. Daran erkennt man Aussenkontur und Loch — etwa im O.
function zugFlaeche(zug) {
  let a = 0;
  for (let i = 0; i < zug.length; i++) {
    const [x1, y1] = zug[i], [x2, y2] = zug[(i + 1) % zug.length];
    a += x1 * y2 - x2 * y1;
  }
  return a / 2;
}

// Versetzt einen geschlossenen Zug um abstand nach innen. Die Kanten
// werden parallel verschoben und an den Ecken geschnitten.
function zugVersetzen(zug, abstand) {
  const n = zug.length;
  if (n < 3 || Math.abs(abstand) < 1e-6) return zug;
  const innen = zugFlaeche(zug) > 0 ? 1 : -1;
  const raus = [];

  for (let i = 0; i < n; i++) {
    const p0 = zug[(i - 1 + n) % n], p1 = zug[i], p2 = zug[(i + 1) % n];

    const kante = (a, b) => {
      const dx = b[0] - a[0], dy = b[1] - a[1];
      const l = Math.hypot(dx, dy) || 1;
      const nx = (dy / l) * innen * -1, ny = (-dx / l) * innen * -1;
      return { a: [a[0] + nx * abstand, a[1] + ny * abstand],
               b: [b[0] + nx * abstand, b[1] + ny * abstand] };
    };

    const e1 = kante(p0, p1), e2 = kante(p1, p2);
    const d1 = [e1.b[0] - e1.a[0], e1.b[1] - e1.a[1]];
    const d2 = [e2.b[0] - e2.a[0], e2.b[1] - e2.a[1]];
    const nenner = d1[0] * d2[1] - d1[1] * d2[0];

    if (Math.abs(nenner) < 1e-9) { raus.push(e1.b); continue; }
    const t = ((e2.a[0] - e1.a[0]) * d2[1] - (e2.a[1] - e1.a[1]) * d2[0]) / nenner;
    const punkt = [e1.a[0] + d1[0] * t, e1.a[1] + d1[1] * t];

    // Spitze Ecken nicht ins Unendliche laufen lassen
    const weit = Math.hypot(punkt[0] - p1[0], punkt[1] - p1[1]);
    const grenze = Math.abs(abstand) * 2.5;
    raus.push(weit > grenze ? e1.b : punkt);
  }
  return raus;
}

// Dünnste Stelle der Schrift grob schätzen: der kleinste Abstand
// zwischen zwei Punkten desselben Zugs, die nicht benachbart sind.
function gravurDuennste(zuege) {
  let kleinster = Infinity;
  zuege.forEach((z) => {
    const schritt = Math.max(1, Math.floor(z.length / 60));
    for (let i = 0; i < z.length; i += schritt) {
      for (let k = i + 3; k < z.length; k += schritt) {
        if (Math.abs(i - k) < 4 || Math.abs(i - k) > z.length - 4) continue;
        const d = Math.hypot(z[i][0] - z[k][0], z[i][1] - z[k][1]);
        if (d < kleinster) kleinster = d;
      }
    }
  });
  return kleinster;
}

// ---------- G-Code ----------

function gravurGcode() {
  const roh = gravurKonturen();
  const zuege = gravurBahnen(roh.zuege);
  const breite = roh.breite;
  if (!zuege.length) return "( Kein Text )";

  const z = [];
  const f = gravur.vorschub;
  const mantel = gravur.flaeche === "mantel";
  const rad = gravur.dm / 2;

  z.push("( GRAVUR  " + gravur.text + " )");
  z.push("( Schrift " + gravur.schrift + (gravur.fett ? " fett" : "")
    + (gravur.kursiv ? " kursiv" : "") + ", Hoehe " + gravur.hoehe + " mm )");
  z.push("( " + zuege.length + " Zuege, "
    + zuege.reduce((a, x) => a + x.length, 0) + " Punkte )");
  kopfZeilen().forEach((x) => z.push(x));
  if (!kopfZeilen().length) {
    z.push("M3S" + Math.round(gravur.drehzahl) + "  ( Gravierstichel )");
  }

  // Auf der Stirnseite dreht der Text um die Achse, auf dem Mantel
  // wird die Breite in einen Winkel umgerechnet.
  const w = (gravur.winkel * Math.PI) / 180;
  const lage = ([x, y]) => {
    if (!mantel) {
      const px = x * Math.cos(w) - y * Math.sin(w);
      const py = x * Math.sin(w) + y * Math.cos(w) + gravur.radius;
      return { a: px, b: py };
    }
    // Mantel: x läuft um den Umfang, y in Z
    return { a: (x / (Math.PI * gravur.dm)) * 360, b: y };
  };

  if (mantel) {
    z.push("G0Z" + (gravur.zStart + 5).toFixed(3) + "C0.");
    z.push("G0X" + (gravur.dm + 2 * gravur.eilgang).toFixed(3));
    z.push("G07.1C" + rad.toFixed(3) + "  ( Zylinderinterpolation ein )");
  } else {
    z.push("G0X" + (gravur.dm + 4).toFixed(3) + "C0.");
    z.push("G0Z" + (gravur.zStart + gravur.eilgang).toFixed(3));
    z.push("G12.1  ( Polarinterpolation ein )");
  }

  const schnitte = Math.max(1, Math.round(gravur.schnitte));
  for (let s = 1; s <= schnitte; s++) {
    const tiefe = (gravur.tiefe / schnitte) * s;
    z.push("( Schnitt " + s + " von " + schnitte + " )");

    zuege.forEach((zug, i) => {
      const erst = lage(zug[0]);
      if (mantel) {
        z.push("G0X" + (gravur.dm + 2 * gravur.eilgang).toFixed(3));
        z.push("G0C" + erst.a.toFixed(3) + "Z" + (gravur.zStart + erst.b).toFixed(3));
        z.push("G1X" + (gravur.dm - 2 * tiefe).toFixed(3) + "F" + f);
      } else {
        z.push("G0Z" + (gravur.zStart + gravur.eilgang).toFixed(3));
        z.push("G0X" + (erst.a * 2).toFixed(3) + "C" + erst.b.toFixed(3));
        z.push("G1Z" + (gravur.zStart - tiefe).toFixed(3) + "F" + f);
      }

      zug.slice(1).forEach((p) => {
        const q = lage(p);
        z.push(mantel
          ? "G1C" + q.a.toFixed(3) + "Z" + (gravur.zStart + q.b).toFixed(3)
          : "G1X" + (q.a * 2).toFixed(3) + "C" + q.b.toFixed(3));
      });

      // Zug schliessen
      const zurueck = lage(zug[0]);
      z.push(mantel
        ? "G1C" + zurueck.a.toFixed(3) + "Z" + (gravur.zStart + zurueck.b).toFixed(3)
        : "G1X" + (zurueck.a * 2).toFixed(3) + "C" + zurueck.b.toFixed(3));
    });
  }

  if (mantel) {
    z.push("G0X" + (gravur.dm + 2 * gravur.eilgang).toFixed(3));
    // Zylinderinterpolation wird mit G07.1 C0 beendet. G13.1 gehört
    // zur Polarinterpolation und würde hier ins Leere laufen.
    z.push("G07.1C0  ( Zylinderinterpolation aus )");
  } else {
    z.push("G0Z" + (gravur.zStart + gravur.eilgang + 5).toFixed(3));
    z.push("G13.1  ( Polarinterpolation aus )");
  }
  z.push("M5");
  return z.join("\n");
}

// Aus den Umrissen die tatsächlichen Bahnen machen: beim Stichel
// die Kontur selbst, beim Schaftfräser um den Radius nach innen
// versetzt, auf Wunsch mit weiteren Bahnen zum Ausräumen.
function gravurBahnen(umrisse) {
  if (gravur.art !== "fraeser" || !umrisse.length) return umrisse;
  const r = gravur.werkzeug / 2;
  if (r < 1e-6) return umrisse;

  const bahnen = [];
  umrisse.forEach((zug) => {
    const erste = zugVersetzen(zug, r);
    if (erste.length > 2) bahnen.push(erste);

    if (gravur.ausraeumen) {
      let jetzt = erste;
      const schritt = Math.max(0.05, gravur.werkzeug * 0.6);
      for (let i = 0; i < 40; i++) {
        const naechste = zugVersetzen(jetzt, schritt);
        // Wird die Fläche zu klein oder kippt das Vorzeichen, ist
        // die Mitte erreicht und es geht nicht weiter hinein.
        const f = Math.abs(zugFlaeche(naechste));
        if (!naechste.length || f < gravur.werkzeug * gravur.werkzeug) break;
        if (Math.sign(zugFlaeche(naechste)) !== Math.sign(zugFlaeche(jetzt))) break;
        bahnen.push(naechste);
        jetzt = naechste;
      }
    }
  });
  return bahnen;
}

// ---------- Zeichnung ----------

function gravurBild() {
  const roh = gravurKonturen();
  const zuege = gravurBahnen(roh.zuege);
  const breite = roh.breite, hoehe = roh.hoehe;
  if (!zuege.length) {
    return '<svg viewBox="0 0 400 200" class="cax-bild" id="grav-bild">'
      + '<text x="200" y="100" text-anchor="middle" class="cax-text">Kein Text</text></svg>';
  }
  const rand = Math.max(breite, hoehe) * 0.12 + 1;
  const b2 = breite + rand * 2, h2 = hoehe + rand * 2;
  const s2 = Math.min(400 / b2, 170 / h2);
  const p = ([x, y]) => (200 + x * s2).toFixed(1) + "," + (90 - y * s2).toFixed(1);

  // Alle Züge hintereinander, damit sich das Werkzeug durchschieben lässt
  const alle = [];
  zuege.forEach((z, nr) => z.forEach((q) => alle.push({ p: q, zug: nr })));
  const i = Math.min(alle.length - 1,
    Math.max(0, Math.round(gravur.schritt * (alle.length - 1))));
  const jetzt = alle[i];
  const rW = Math.max(1.5, (gravur.werkzeug / 2) * s2);

  // Schon gefahren: ganze Züge davor, im laufenden bis hierher
  let gezaehlt = 0;
  const gefahren = zuege.map((z, nr) => {
    const start = gezaehlt;
    gezaehlt += z.length;
    if (nr > jetzt.zug) return "";
    const bis = nr < jetzt.zug ? z.length : (i - start + 1);
    if (bis < 2) return "";
    return '<polyline points="' + z.slice(0, bis).map(p).join(" ")
      + '" class="grav-gefahren"/>';
  }).join("");

  return '<svg viewBox="0 0 400 200" class="cax-bild" id="grav-bild">'
    + zuege.map((z) => '<polygon points="' + z.map(p).join(" ")
        + '" class="grav-zug"/>').join("")
    + gefahren
    + '<circle cx="' + (200 + jetzt.p[0] * s2).toFixed(1)
    + '" cy="' + (90 - jetzt.p[1] * s2).toFixed(1)
    + '" r="' + rW.toFixed(1) + '" class="grav-werkzeug"/>'
    + '<text x="200" y="192" text-anchor="middle" class="cax-legende">'
    + breite.toFixed(2) + ' × ' + hoehe.toFixed(2) + ' mm · '
    + zuege.length + ' Züge</text>'
    + '</svg>';
}

// Nur das Bild neu zeichnen, damit der Ablauf flüssig läuft
function gravurNurBildNeu() {
  const alt = document.getElementById("grav-bild");
  if (!alt) return;
  const huelle = document.createElement("div");
  huelle.innerHTML = gravurBild();
  alt.replaceWith(huelle.firstElementChild);
}

function gravurAblauf() {
  if (!gravur.laeuft) return;
  gravur.schritt += 0.003;
  if (gravur.schritt > 1) gravur.schritt = 0;
  const schieber = document.getElementById("grav-schieber");
  if (schieber) schieber.value = Math.round(gravur.schritt * 1000);
  gravurNurBildNeu();
  requestAnimationFrame(gravurAblauf);
}

// ---------- Seite ----------

function rechnerGravur(ziel) {
  const zahl = (name, text, schritt) =>
    '<label class="feld"><span>' + text + '</span>'
    + '<input type="number" data-grav="' + name + '" step="' + (schritt || "0.1")
    + '" value="' + gravur[name] + '"></label>';

  const mantel = gravur.flaeche === "mantel";

  ladeFertig(ziel);
  ziel.innerHTML = '<div class="karte">'
    + '<label class="feld"><span>Text</span>'
    + '<input type="text" data-grav="text" value="' + esc(gravur.text) + '"></label>'

    + '<div class="cax-raster">'
    + '<div class="cax-bildfeld">' + gravurBild()
    + '<div class="dxf-steuer">'
    + '<button class="knopf knopf--klein" id="grav-los">'
    + (gravur.laeuft ? "Halt" : "Ablauf zeigen") + '</button>'
    + '<input type="range" id="grav-schieber" min="0" max="1000" value="'
    + Math.round(gravur.schritt * 1000) + '">'
    + '</div></div>'
    + '<div class="cax-felder">'
    + '<label class="feld"><span>Schrift</span><select data-grav="schrift">'
    + GRAVUR_SCHRIFTEN.map((sn) => '<option value="' + esc(sn) + '"'
        + (gravur.schrift === sn ? " selected" : "") + '>' + esc(sn) + '</option>').join("")
    + '</select><span class="feldhinweis" id="grav-vorhanden"></span></label>'
    + '<div class="feld"><span class="feldlabel">Schnitt</span>'
    + '<label class="schalter schalter--eng"><input type="checkbox" data-grav="fett"'
    + (gravur.fett ? " checked" : "") + '><span>Fett</span></label>'
    + '<label class="schalter schalter--eng"><input type="checkbox" data-grav="kursiv"'
    + (gravur.kursiv ? " checked" : "") + '><span>Kursiv</span></label></div>'
    + zahl("hoehe", "Zeichenhöhe in mm")
    + zahl("laufweite", "Laufweite in mm", "0.05")
    + '<label class="feld"><span>Fläche</span><select data-grav="flaeche">'
    + '<option value="stirn"' + (!mantel ? " selected" : "") + '>Stirnseite (G12.1)</option>'
    + '<option value="mantel"' + (mantel ? " selected" : "") + '>Mantel (G07.1)</option>'
    + '</select></label>'
    + zahl("dm", "Durchmesser des Teils")
    + (mantel ? "" : zahl("radius", "Abstand von der Achse") + zahl("winkel", "Drehung in Grad", "1"))
    + zahl("zStart", "Z an der Fläche")
    + zahl("tiefe", "Gravurtiefe", "0.05")
    + zahl("schnitte", "Schnitte", "1")
    + zahl("vorschub", "Vorschub mm/min", "1")
    + zahl("drehzahl", "Drehzahl Stichel", "100")
    + zahl("eilgang", "Abhebehöhe", "0.5")
    + '<label class="feld"><span>Werkzeug</span><select data-grav="art">'
    + '<option value="stichel"' + (gravur.art === "stichel" ? " selected" : "")
    + '>Gravierstichel, auf der Linie</option>'
    + '<option value="fraeser"' + (gravur.art === "fraeser" ? " selected" : "")
    + '>Schaftfräser, versetzt</option></select></label>'
    + zahl("werkzeug", gravur.art === "fraeser" ? "Fräser Ø" : "Stichelspitze Ø", "0.05")
    + (gravur.art === "fraeser"
        ? '<div class="feld"><span class="feldlabel">Fräsen</span>'
          + '<label class="schalter schalter--eng">'
          + '<input type="checkbox" data-grav="ausraeumen"'
          + (gravur.ausraeumen ? " checked" : "") + '>'
          + '<span>Buchstaben ausräumen</span></label></div>'
        : "")
    + zahl("glaetten", "Glättung in mm", "0.005")
    + '</div></div>'

    + '<p class="klein">Die Umrisse werden aus der gewählten Schrift abgetastet, '
    + 'darum steht jede Schrift zur Verfügung, die auf diesem Rechner installiert ist. '
    + (gravur.art === "fraeser"
        ? 'Die Bahn ist um den Fräserradius nach innen versetzt, damit die '
          + 'Buchstaben ihre Kontur behalten.'
        : 'Gefahren wird auf der Kontur, nicht versetzt — mit einem Gravierstichel '
          + 'ist das richtig.')
    + ' X ist im Durchmesser programmiert. '
    + (mantel
        ? 'Auf dem Mantel läuft die Breite über den Umfang, C ist der Winkel.'
        : 'Auf der Stirnseite sind X und C wie X und Y zu lesen.')
    + ' Grössere Glättung bedeutet weniger Zeilen, aber eckigere Rundungen.</p>'
    + (() => {
        if (gravur.art !== "fraeser") return "";
        const duenn = gravurDuennste(gravurKonturen().zuege);
        if (!isFinite(duenn) || gravur.werkzeug <= duenn) return "";
        return '<p class="karte karte--fehler cax-warnung">Der Fräser ist zu dick: '
          + 'die dünnste Stelle der Schrift misst etwa ' + duenn.toFixed(2)
          + ' mm, der Fräser Ø' + gravur.werkzeug.toFixed(2) + ' mm. '
          + 'Dort bleibt nichts stehen. Kleineres Werkzeug, grössere Zeichenhöhe '
          + 'oder eine fettere Schrift wählen.</p>';
      })()
    + kopfFelder()
    + '<pre class="gcode">' + esc(gravurGcode()) + '</pre>'
    + '<button class="knopf knopf--klein" id="grav-kopieren">G-Code kopieren</button>'
    + '</div>';

  // Ist die Schrift auf diesem Rechner überhaupt da?
  const hinweis = document.getElementById("grav-vorhanden");
  if (hinweis) {
    let da = true;
    try { da = document.fonts.check('16px "' + gravur.schrift + '"'); }
    catch (f) { da = true; }
    hinweis.textContent = da ? ""
      : "Diese Schrift ist hier nicht installiert — es wird ersatzweise "
        + "eine andere gezeichnet.";
  }

  ziel.querySelectorAll("[data-grav]").forEach((el) => {
    const auslesen = () => {
      const name = el.dataset.grav;
      gravur[name] = el.type === "checkbox" ? el.checked
        : (el.type === "number" ? Number(el.value) : el.value);
      gravur.laeuft = false;
      gravur.schritt = 0;
      rechnerGravur(ziel);
    };
    if (el.type === "text") {
      let taste = null;
      el.oninput = () => { clearTimeout(taste); taste = setTimeout(auslesen, 500); };
    } else {
      el.onchange = auslesen;
    }
  });

  const schieber = document.getElementById("grav-schieber");
  if (schieber) schieber.oninput = () => {
    gravur.schritt = Number(schieber.value) / 1000;
    gravurNurBildNeu();
  };

  const los = document.getElementById("grav-los");
  if (los) los.onclick = () => {
    gravur.laeuft = !gravur.laeuft;
    los.textContent = gravur.laeuft ? "Halt" : "Ablauf zeigen";
    if (gravur.laeuft) gravurAblauf();
  };

  kopfBinden(ziel, () => rechnerGravur(ziel));

  const kopieren = document.getElementById("grav-kopieren");
  if (kopieren) kopieren.onclick = async () => {
    try {
      await navigator.clipboard.writeText(gravurGcode());
      meldung("G-Code kopiert.");
    } catch (f) { meldung("Kopieren ging nicht. Bitte von Hand markieren.", "warn"); }
  };
}


// =================================================================
//  DXF: KONTUR WÄHLEN UND MIT G12.1 FRÄSEN
//  Gelesen wird DXF im Textformat — Linien, Bögen, Kreise und
//  Polylinien. Die Elemente werden zu geschlossenen Konturen
//  verkettet, eine davon wird gewählt, und daraus entsteht die
//  Bahn der Fräsermitte samt G-Code.
// =================================================================

const dxf = {
  name: "",
  konturen: [],      // [{ punkte: [[x,y],…], geschlossen: bool }]
  gewaehlt: -1,
  seite: "aussen",   // aussen oder innen
  fraeser: 3,
  tiefeZ: 2,
  zustellung: 1,
  vorschub: 60,
  drehzahl: 3000,
  zStart: 0,
  sicher: 1,
  glaetten: 0.01,
  schritt: 0,        // Stellung des Fräsers in der Vorschau, 0…1
  laeuft: false,
  massstab: 100,     // Grösse in Prozent
  roh: [],           // Konturen so, wie sie in der Datei stehen
};

// ---------- Einlesen ----------

function dxfLesen(inhalt) {
  const zeilen = inhalt.split(/\r\n|\r|\n/);
  const paare = [];
  for (let i = 0; i + 1 < zeilen.length; i += 2) {
    paare.push([Number(zeilen[i].trim()), zeilen[i + 1].trim()]);
  }

  const teile = [];
  let jetzt = null;
  let inEntities = false;

  const ablegen = () => { if (jetzt) teile.push(jetzt); jetzt = null; };

  for (let i = 0; i < paare.length; i++) {
    const [code, wert] = paare[i];

    if (code === 2 && wert === "ENTITIES") { inEntities = true; continue; }
    if (code === 0 && wert === "ENDSEC" && inEntities) { ablegen(); inEntities = false; }
    if (!inEntities) continue;

    if (code === 0) {
      ablegen();
      if (["LINE", "ARC", "CIRCLE", "LWPOLYLINE", "POLYLINE", "VERTEX", "SEQEND"]
          .indexOf(wert) !== -1) {
        jetzt = { art: wert, werte: {}, ecken: [] };
      }
      continue;
    }
    if (!jetzt) continue;

    // Polylinien liefern mehrere Punkte mit denselben Codes
    if (jetzt.art === "LWPOLYLINE" && code === 10) {
      jetzt.ecken.push([Number(wert), 0]);
      continue;
    }
    if (jetzt.art === "LWPOLYLINE" && code === 20 && jetzt.ecken.length) {
      jetzt.ecken[jetzt.ecken.length - 1][1] = Number(wert);
      continue;
    }
    jetzt.werte[code] = wert;
  }
  ablegen();

  // VERTEX-Punkte zur vorangehenden POLYLINE schlagen
  const sauber = [];
  teile.forEach((t) => {
    if (t.art === "VERTEX") {
      const letzte = sauber[sauber.length - 1];
      if (letzte && letzte.art === "POLYLINE") {
        letzte.ecken.push([Number(t.werte[10] || 0), Number(t.werte[20] || 0)]);
      }
      return;
    }
    if (t.art === "SEQEND") return;
    sauber.push(t);
  });

  // In Linienzüge umrechnen
  const stuecke = [];
  const bogen = (cx, cy, r, a1, a2, gegen) => {
    const punkte = [];
    let spanne = a2 - a1;
    while (spanne <= 0) spanne += 360;
    const n = Math.max(6, Math.ceil(spanne / 4));
    for (let i = 0; i <= n; i++) {
      const w = ((a1 + (spanne * i) / n) * Math.PI) / 180;
      punkte.push([cx + r * Math.cos(w), cy + r * Math.sin(w)]);
    }
    return punkte;
  };

  sauber.forEach((t) => {
    const z = (c) => Number(t.werte[c] || 0);
    if (t.art === "LINE") {
      stuecke.push({ punkte: [[z(10), z(20)], [z(11), z(21)]], geschlossen: false });
    } else if (t.art === "CIRCLE") {
      stuecke.push({ punkte: bogen(z(10), z(20), z(40), 0, 360), geschlossen: true });
    } else if (t.art === "ARC") {
      stuecke.push({ punkte: bogen(z(10), z(20), z(40), z(50), z(51)),
                     geschlossen: false });
    } else if (t.art === "LWPOLYLINE" || t.art === "POLYLINE") {
      const zu = (Number(t.werte[70] || 0) & 1) === 1;
      if (t.ecken.length > 1) {
        stuecke.push({ punkte: t.ecken.slice(), geschlossen: zu });
      }
    }
  });

  return dxfVerketten(stuecke);
}

// Offene Stücke aneinanderhängen, bis eine Kontur geschlossen ist
function dxfVerketten(stuecke) {
  const toleranz = 0.02;
  const nah = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1]) < toleranz;

  const fertig = stuecke.filter((s) => s.geschlossen)
    .map((s) => ({ punkte: s.punkte, geschlossen: true }));
  const offen = stuecke.filter((s) => !s.geschlossen).map((s) => s.punkte.slice());

  while (offen.length) {
    let kette = offen.shift();
    let gefunden = true;
    while (gefunden) {
      gefunden = false;
      for (let i = 0; i < offen.length; i++) {
        const k = offen[i];
        const ende = kette[kette.length - 1], anfang = kette[0];
        if (nah(ende, k[0])) { kette = kette.concat(k.slice(1)); }
        else if (nah(ende, k[k.length - 1])) {
          kette = kette.concat(k.slice().reverse().slice(1));
        } else if (nah(anfang, k[k.length - 1])) {
          kette = k.slice(0, -1).concat(kette);
        } else if (nah(anfang, k[0])) {
          kette = k.slice().reverse().slice(0, -1).concat(kette);
        } else continue;
        offen.splice(i, 1);
        gefunden = true;
        break;
      }
    }
    fertig.push({ punkte: kette,
                  geschlossen: nah(kette[0], kette[kette.length - 1]) });
  }

  return fertig
    .map((k) => {
      let punkte = vereinfachen(k.punkte, dxf.glaetten);
      // Bei einer geschlossenen Kontur steht der Anfangspunkt am Ende
      // noch einmal. Bleibt er drin, knickt der Versatz an der Naht ab.
      if (k.geschlossen && punkte.length > 2
          && nah(punkte[0], punkte[punkte.length - 1])) {
        punkte = punkte.slice(0, -1);
      }
      return { punkte: punkte, geschlossen: k.geschlossen };
    })
    .filter((k) => k.punkte.length > 2)
    .sort((a, b) => Math.abs(zugFlaeche(b.punkte)) - Math.abs(zugFlaeche(a.punkte)));
}

// Die Konturen im gewählten Massstab bereitstellen. Die Werte aus
// der Datei bleiben unangetastet, damit mehrfaches Ändern nicht
// aufsummiert.
function dxfSkalieren() {
  const k = dxf.massstab / 100;
  dxf.konturen = (dxf.roh || []).map((z) => ({
    punkte: z.punkte.map(([x, y]) => [x * k, y * k]),
    geschlossen: z.geschlossen,
  }));
}

// Grösse der gewählten Kontur, sonst der ganzen Zeichnung
function dxfMasse(nurGewaehlte) {
  const liste = (nurGewaehlte && dxf.konturen[dxf.gewaehlt])
    ? [dxf.konturen[dxf.gewaehlt]] : dxf.konturen;
  if (!liste.length) return null;
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  liste.forEach((k) => k.punkte.forEach(([x, y]) => {
    minX = Math.min(minX, x); maxX = Math.max(maxX, x);
    minY = Math.min(minY, y); maxY = Math.max(maxY, y);
  }));
  return { breite: maxX - minX, hoehe: maxY - minY,
           minX: minX, maxX: maxX, minY: minY, maxY: maxY };
}

// ---------- Bahn und G-Code ----------

function dxfBahn() {
  const k = dxf.konturen[dxf.gewaehlt];
  if (!k) return null;
  const r = dxf.fraeser / 2;
  // zugVersetzen versetzt nach innen; für aussen dreht das Vorzeichen
  return zugVersetzen(k.punkte, dxf.seite === "innen" ? r : -r);
}

function dxfGcode() {
  const bahn = dxfBahn();
  if (!bahn) return "( Keine Kontur gewählt )";

  const z = [];
  const f = dxf.vorschub;
  const weit = Math.max(...bahn.map((p) => Math.hypot(p[0], p[1]))) + dxf.sicher;

  z.push("( DXF " + (dxf.name || "Kontur") + " )");
  z.push("( " + (dxf.seite === "innen" ? "innen" : "aussen") + ", Fraeser D"
    + dxf.fraeser.toFixed(2) + ", Bahn = Fraesermitte )");
  kopfZeilen().forEach((x) => z.push(x));
  if (!kopfZeilen().length) z.push("M3S" + Math.round(dxf.drehzahl));
  z.push("G0X" + (weit * 2).toFixed(3) + "C0.");
  z.push("G0Z" + (dxf.zStart + dxf.sicher).toFixed(3));
  z.push("G12.1  ( Polarinterpolation ein )");

  const schnitte = Math.max(1, Math.ceil(dxf.tiefeZ / Math.max(0.1, dxf.zustellung)));
  for (let s = 1; s <= schnitte; s++) {
    const tiefe = Math.min(dxf.tiefeZ, s * dxf.zustellung);
    z.push("( Schnitt " + s + " von " + schnitte + " )");
    z.push("G0X" + (bahn[0][0] * 2).toFixed(3) + "C" + bahn[0][1].toFixed(3));
    z.push("G1Z" + (dxf.zStart - tiefe).toFixed(3) + "F" + f);
    bahn.slice(1).forEach((p) => {
      z.push("G1X" + (p[0] * 2).toFixed(3) + "C" + p[1].toFixed(3));
    });
    z.push("G1X" + (bahn[0][0] * 2).toFixed(3) + "C" + bahn[0][1].toFixed(3));
    z.push("G0Z" + (dxf.zStart + dxf.sicher).toFixed(3));
  }

  z.push("G13.1  ( Polarinterpolation aus )");
  z.push("G0X" + (weit * 2).toFixed(3));
  fussZeilen().forEach((x) => z.push(x));
  if (!fussZeilen().length) z.push("M5");
  return z.join("\n");
}

// ---------- Ansicht ----------

function dxfBild() {
  if (!dxf.konturen.length) {
    return '<svg viewBox="0 0 460 320" class="cax-bild">'
      + '<text x="230" y="160" text-anchor="middle" class="cax-text">'
      + 'Noch keine Datei geladen</text></svg>';
  }

  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  dxf.konturen.forEach((k) => k.punkte.forEach(([x, y]) => {
    minX = Math.min(minX, x); maxX = Math.max(maxX, x);
    minY = Math.min(minY, y); maxY = Math.max(maxY, y);
  }));
  const rand = Math.max(maxX - minX, maxY - minY) * 0.1 + 1;
  const b = maxX - minX + rand * 2, h = maxY - minY + rand * 2;
  const s = Math.min(460 / b, 320 / h);
  const mx = (minX + maxX) / 2, my = (minY + maxY) / 2;
  const p = ([x, y]) => (230 + (x - mx) * s).toFixed(1) + ","
    + (160 - (y - my) * s).toFixed(1);

  const teile = dxf.konturen.map((k, i) => '<polyline points="'
    + k.punkte.map(p).join(" ") + '" class="dxf-kontur'
    + (i === dxf.gewaehlt ? " dxf-kontur--an" : "") + '" data-dxfk="' + i + '"/>').join("");

  const bahn = dxfBahn();
  const bahnBild = bahn
    ? '<polygon points="' + bahn.map(p).join(" ") + '" class="dxf-bahn"/>' : "";

  // Der Fräser an seiner Stelle auf der Bahn
  let werkzeug = "";
  if (bahn) {
    const i = Math.min(bahn.length - 1,
      Math.max(0, Math.round(dxf.schritt * (bahn.length - 1))));
    const [x, y] = bahn[i];
    const rr = (dxf.fraeser / 2) * s;
    werkzeug = '<circle cx="' + (230 + (x - mx) * s).toFixed(1)
      + '" cy="' + (160 - (y - my) * s).toFixed(1)
      + '" r="' + Math.max(3, rr).toFixed(1) + '" class="dxf-fraeser"/>'
      + '<polyline points="' + bahn.slice(0, i + 1).map(p).join(" ")
      + '" class="dxf-gefahren"/>';
  }

  return '<svg viewBox="0 0 460 320" class="cax-bild" id="dxf-bild">'
    + teile + bahnBild + werkzeug + '</svg>';
}

function rechnerDxf(ziel) {
  const zahl = (name, text, schritt) =>
    '<label class="feld"><span>' + text + '</span>'
    + '<input type="number" data-dxf="' + name + '" step="' + (schritt || "0.1")
    + '" value="' + dxf[name] + '"></label>';

  ladeFertig(ziel);
  ziel.innerHTML = '<div class="karte">'
    + '<div class="dxf-kopf">'
    + '<label class="knopf knopf--klein bildknopf">DXF wählen'
    + '<input type="file" id="dxf-datei" accept=".dxf,text/plain" hidden></label>'
    + '<span class="klein">' + (dxf.name
        ? esc(dxf.name) + ' · ' + dxf.konturen.length + ' Konturen'
        : 'Aus dem CAD als DXF speichern, Linien, Bögen, Kreise und Polylinien') + '</span>'
    + '</div>'

    + '<div class="cax-raster dxf-raster">'
    + '<div class="cax-bildfeld">' + dxfBild()
    + (dxfBahn()
        ? '<div class="dxf-steuer">'
          + '<button class="knopf knopf--klein" id="dxf-los">'
          + (dxf.laeuft ? "Halt" : "Ablauf zeigen") + '</button>'
          + '<input type="range" id="dxf-schieber" min="0" max="1000" value="'
          + Math.round(dxf.schritt * 1000) + '">'
          + '</div>' : "")
    + '</div>'
    + '<div class="cax-felder">'
    + (dxf.konturen.length
        ? '<label class="feld"><span>Massstab in Prozent</span>'
          + '<input type="number" data-dxf="massstab" step="1" min="1" value="'
          + dxf.massstab.toFixed(1) + '"></label>'
          + '<label class="feld"><span>oder Breite in mm</span>'
          + '<input type="number" id="dxf-zielbreite" step="0.1" value="'
          + ((dxfMasse(dxf.gewaehlt >= 0) || dxfMasse(false)
              || { breite: 0 }).breite).toFixed(2)
          + '"><span class="feldhinweis">setzt den Massstab passend</span></label>'
        : "")
    + (dxf.konturen.length
        ? '<label class="feld"><span>Kontur</span><select data-dxf="gewaehlt">'
          + '<option value="-1">— wählen —</option>'
          + dxf.konturen.map((k, i) => '<option value="' + i + '"'
              + (dxf.gewaehlt === i ? " selected" : "") + '>Kontur ' + (i + 1)
              + ' · ' + k.punkte.length + ' Punkte'
              + (k.geschlossen ? "" : " · offen") + '</option>').join("")
          + '</select></label>'
        : "")
    + '<label class="feld"><span>Seite</span><select data-dxf="seite">'
    + '<option value="aussen"' + (dxf.seite === "aussen" ? " selected" : "")
    + '>Aussen herum</option>'
    + '<option value="innen"' + (dxf.seite === "innen" ? " selected" : "")
    + '>Innen, als Tasche</option></select></label>'
    + zahl("fraeser", "Fräserdurchmesser")
    + zahl("tiefeZ", "Frästiefe in Z")
    + zahl("zustellung", "Zustellung je Schnitt")
    + zahl("zStart", "Z an der Fläche")
    + zahl("sicher", "Sicherheitsabstand")
    + zahl("vorschub", "Vorschub mm/min", "1")
    + zahl("drehzahl", "Drehzahl Fräser", "50")
    + zahl("glaetten", "Glättung in mm", "0.005")
    + '</div></div>'

    + (() => {
        const ganz = dxfMasse(false);
        if (!ganz) return "";
        const eine = dxfMasse(true);
        const bahn = dxfBahn();
        let bm = "";
        if (bahn) {
          let a = Infinity, b = -Infinity, c = Infinity, d = -Infinity;
          bahn.forEach(([x, y]) => {
            a = Math.min(a, x); b = Math.max(b, x);
            c = Math.min(c, y); d = Math.max(d, y);
          });
          bm = ' · Bahn ' + (b - a).toFixed(2) + ' × ' + (d - c).toFixed(2)
            + ' mm, grösster Durchmesser '
            + (2 * Math.max(...bahn.map((q) => Math.hypot(q[0], q[1])))).toFixed(2)
            + ' mm';
        }
        return '<p class="dxf-masse">Zeichnung ' + ganz.breite.toFixed(2) + ' × '
          + ganz.hoehe.toFixed(2) + ' mm'
          + (eine && dxf.gewaehlt >= 0
              ? ' · gewählte Kontur ' + eine.breite.toFixed(2) + ' × '
                + eine.hoehe.toFixed(2) + ' mm' : "")
          + bm + '</p>';
      })()
    + '<p class="klein">Blau sind die Konturen aus der Datei, rot ist die Bahn der '
    + 'Fräsermitte. Eine Kontur lässt sich auch direkt im Bild antippen. '
    + 'X ist im Durchmesser programmiert, C entspricht Y.</p>'
    + kopfFelder()
    + '<pre class="gcode">' + esc(dxfGcode()) + '</pre>'
    + '<button class="knopf knopf--klein" id="dxf-kopieren">G-Code kopieren</button>'
    + '</div>';

  const datei = document.getElementById("dxf-datei");
  if (datei) datei.onchange = async (e) => {
    const f2 = (e.target.files || [])[0];
    if (!f2) return;
    try {
      const inhalt = await f2.text();
      dxf.roh = dxfLesen(inhalt);
      dxf.massstab = 100;
      dxfSkalieren();
      dxf.name = f2.name;
      dxf.gewaehlt = dxf.konturen.length ? 0 : -1;
      dxf.schritt = 0;
      if (!dxf.konturen.length) {
        meldung("In dieser Datei sind keine brauchbaren Konturen. "
          + "Linien, Bögen, Kreise und Polylinien werden gelesen.", "warn");
      } else {
        meldung(dxf.konturen.length + " Konturen gelesen.");
      }
      rechnerDxf(ziel);
    } catch (g) { meldung(fehlertext(g), "fehler"); }
  };

  ziel.querySelectorAll("[data-dxf]").forEach((el) => {
    el.onchange = () => {
      const name = el.dataset.dxf;
      dxf[name] = el.type === "number" ? Number(el.value)
        : (name === "gewaehlt" ? Number(el.value) : el.value);
      if (name === "massstab") {
        dxf.massstab = Math.max(1, dxf.massstab || 100);
        dxfSkalieren();
      }
      dxf.schritt = 0;
      rechnerDxf(ziel);
    };
  });

  ziel.querySelectorAll("[data-dxfk]").forEach((el) => {
    el.onclick = () => { dxf.gewaehlt = Number(el.dataset.dxfk); rechnerDxf(ziel); };
  });

  // Statt am Massstab zu drehen, lässt sich die Breite direkt setzen
  const zielbreite = document.getElementById("dxf-zielbreite");
  if (zielbreite) zielbreite.onchange = () => {
    const soll = Number(zielbreite.value);
    const jetzt = dxfMasse(dxf.gewaehlt >= 0) || dxfMasse(false);
    if (!jetzt || !jetzt.breite || !soll || soll <= 0) return;
    dxf.massstab = Math.max(1, (dxf.massstab * soll) / jetzt.breite);
    dxfSkalieren();
    dxf.schritt = 0;
    rechnerDxf(ziel);
  };

  const schieber = document.getElementById("dxf-schieber");
  if (schieber) schieber.oninput = () => {
    dxf.schritt = Number(schieber.value) / 1000;
    dxfNurBildNeu();
  };

  const los = document.getElementById("dxf-los");
  if (los) los.onclick = () => {
    dxf.laeuft = !dxf.laeuft;
    los.textContent = dxf.laeuft ? "Halt" : "Ablauf zeigen";
    if (dxf.laeuft) dxfAblauf();
  };

  kopfBinden(ziel, () => rechnerDxf(ziel));

  const kopieren = document.getElementById("dxf-kopieren");
  if (kopieren) kopieren.onclick = async () => {
    try {
      await navigator.clipboard.writeText(dxfGcode());
      meldung("G-Code kopiert.");
    } catch (g) { meldung("Kopieren ging nicht. Bitte von Hand markieren.", "warn"); }
  };
}

// Nur das Bild neu zeichnen, damit der Fräser flüssig läuft
function dxfNurBildNeu() {
  const alt = document.getElementById("dxf-bild");
  if (!alt) return;
  const huelle = document.createElement("div");
  huelle.innerHTML = dxfBild();
  alt.replaceWith(huelle.firstElementChild);
  document.querySelectorAll("[data-dxfk]").forEach((el) => {
    el.onclick = () => {
      dxf.gewaehlt = Number(el.dataset.dxfk);
      dxf.laeuft = false;
      rechnerDxf(document.getElementById("rech-inhalt"));
    };
  });
}

function dxfAblauf() {
  if (!dxf.laeuft) return;
  dxf.schritt += 0.004;
  if (dxf.schritt > 1) dxf.schritt = 0;
  const schieber = document.getElementById("dxf-schieber");
  if (schieber) schieber.value = Math.round(dxf.schritt * 1000);
  dxfNurBildNeu();
  requestAnimationFrame(dxfAblauf);
}

// ---------- G-Code für Fase und Radius ----------

const gcode = {
  richtung: "stirn",     // stirn = von der Fläche auf den Durchmesser
  dm: "20",              // Enddurchmesser
  zStart: "0",           // Z am Anfang
  fase: "1",             // Fasenbreite
  winkel: "45",
  radius: "0.2",
  radienAn: true,
  ohneA: false,
  vorschub: "0.03",
  vorschubFein: "0.02",
  ueberlauf: "0.5",
  laenge: "2",
};

// Zeichnung: zeigt, was das Programm macht
// Feste Zeichnung, nur die Zahlen ändern sich.
// Links das Rohteil im Schnitt, oben die Mittellinie, dazu die
// Startstellung des Drehstahls.
function bildGcode(g) {
  const dm = parseFloat(g.dm) || 20;
  const fase = parseFloat(g.fase) || 1;
  const winkel = parseFloat(g.winkel) || 45;
  const rad = g.radienAn ? (parseFloat(g.radius) || 0) : 0;
  const z0 = parseFloat(g.zStart) || 0;
  const stirn = g.richtung === "stirn";

  const z = (x) => (Math.round(x * 100) / 100).toLocaleString("de-CH");

  // Feste Geometrie in der Zeichnung, unabhängig von den Werten
  const links = 120, rechts = 400, mitte = 200;
  const oben = 120;                 // Aussendurchmesser
  const fb = 26;                    // Fasenbreite in der Zeichnung
  const ft = 26;                    // Fasentiefe in der Zeichnung

  const kontur = stirn
    ? 'M' + links + ',' + mitte
      + ' L' + links + ',' + (oben + fb)
      + ' L' + (links + ft) + ',' + oben
      + ' L' + rechts + ',' + oben
      + ' L' + rechts + ',' + mitte + ' Z'
    : 'M' + links + ',' + mitte
      + ' L' + links + ',' + oben
      + ' L' + (rechts - ft) + ',' + oben
      + ' L' + rechts + ',' + (oben + fb)
      + ' L' + rechts + ',' + mitte + ' Z';

  const fasenLinie = stirn
    ? '<line x1="' + links + '" y1="' + (oben + fb) + '" x2="' + (links + ft)
      + '" y2="' + oben + '" stroke="var(--gefahr)" stroke-width="3"/>'
    : '<line x1="' + (rechts - ft) + '" y1="' + oben + '" x2="' + rechts
      + '" y2="' + (oben + fb) + '" stroke="var(--gefahr)" stroke-width="3"/>';

  // Startstellung des Werkzeugs: über dem Material, vor der Stirnfläche
  const wx = stirn ? links - 34 : rechts + 34;
  const wy = oben - 46;

  return '<svg viewBox="0 0 520 260" class="zeichnung" role="img"'
    + ' aria-label="Drehteil mit Fase und Startstellung des Werkzeugs">'

    // Mittellinie
    + '<line x1="60" y1="' + mitte + '" x2="470" y2="' + mitte + '"'
    + ' stroke="var(--linie-stark)" stroke-width="1" stroke-dasharray="10 4 2 4"/>'
    + '<text x="474" y="' + (mitte + 4) + '" class="zbeschriftung">Mitte</text>'

    // Werkstück
    + '<path d="' + kontur + '" fill="var(--marke-hell)"'
    + ' stroke="var(--marke)" stroke-width="2.5"/>'
    + fasenLinie

    // Durchmesser links
    + '<line x1="88" y1="' + oben + '" x2="88" y2="' + mitte + '"'
    + ' stroke="var(--tinte)" stroke-width="1"/>'
    + '<line x1="82" y1="' + oben + '" x2="94" y2="' + oben + '"'
    + ' stroke="var(--tinte)" stroke-width="1"/>'
    + '<line x1="82" y1="' + mitte + '" x2="94" y2="' + mitte + '"'
    + ' stroke="var(--tinte)" stroke-width="1"/>'
    + '<text x="78" y="' + (oben + 34) + '" class="zbeschriftung" text-anchor="end">Ø'
    + z(dm) + '</text>'

    // Fasenmass oben
    + '<text x="' + (links + ft + 14) + '" y="' + (oben - 12) + '" class="zbeschriftung">'
    + z(fase) + ' × ' + z(winkel) + '°' + (rad > 0 ? '   R' + z(rad) : "") + '</text>'

    // Z-Angabe
    + '<text x="' + links + '" y="' + (mitte + 26) + '" class="zbeschriftung"'
    + ' text-anchor="middle">Z' + z(z0) + '</text>'

    // Werkzeug in Startstellung
    + '<polygon points="' + wx + ',' + wy + ' ' + (wx - 14) + ',' + (wy - 24)
    + ' ' + (wx + 14) + ',' + (wy - 24) + '" fill="var(--gedaempft)"/>'
    + '<line x1="' + wx + '" y1="' + wy + '" x2="' + wx + '" y2="' + (oben - 6) + '"'
    + ' stroke="var(--gedaempft)" stroke-width="1" stroke-dasharray="4 3"/>'
    + '<text x="' + (wx + (stirn ? -20 : 20)) + '" y="' + (wy - 32) + '"'
    + ' class="zbeschriftung" text-anchor="' + (stirn ? "end" : "start") + '">Start</text>'

    // Bewegungsrichtung
    + '<text x="260" y="242" class="zbeschriftung" text-anchor="middle">'
    + (stirn ? "von der Stirnfläche auf den Durchmesser"
             : "vom Durchmesser auf die Stirnfläche") + '</text>'
    + '</svg>';
}

function baueGcode(g) {
  const dm = parseFloat(g.dm) || 0;
  const z0 = parseFloat(g.zStart) || 0;
  const fase = parseFloat(g.fase) || 0;
  const winkel = parseFloat(g.winkel) || 45;
  const rad = g.radienAn ? (parseFloat(g.radius) || 0) : 0;
  const f = (parseFloat(g.vorschub) || 0.03).toFixed(2);
  const ff = (parseFloat(g.vorschubFein) || 0.02).toFixed(2);
  const ueber = parseFloat(g.ueberlauf) || 0.5;
  const laenge = parseFloat(g.laenge) || 2;

  const anfahrDm = (dm + 2).toFixed(2);
  const tiefe = fase / Math.tan(bogenGrad(winkel));
  const zEnde = (z0 + tiefe).toFixed(3);
  const dmNachFase = (dm - 2 * fase).toFixed(3);

  const zeilen = [];

  if (g.richtung === "stirn") {
    // Von der Stirnfläche auf den Durchmesser
    zeilen.push("G0X" + anfahrDm + "Z" + z0.toFixed(2));
    zeilen.push("G1X-0.5F" + f);
    zeilen.push("G1X0.00");
    zeilen.push("G1,A90.," + (rad > 0 ? "R" + rad.toFixed(2) : "R0") + "F" + ff);
    zeilen.push(",A" + winkel.toFixed(0) + ".X" + dmNachFase + "Z" + zEnde
      + (rad > 0 ? ",R" + rad.toFixed(2) : "") + "F" + ff);
    zeilen.push("G1X" + dm.toFixed(3) + "Z" + (z0 + laenge).toFixed(2) + "F" + f);
  } else {
    // Vom Durchmesser auf die Stirnfläche, also Kantenbruch aussen
    zeilen.push("G0X" + anfahrDm + "Z" + (z0 + laenge).toFixed(2));
    zeilen.push("G1X" + dm.toFixed(3) + "F" + f);
    zeilen.push("G1Z" + zEnde + "F" + f);
    zeilen.push("G1,A" + (180 - winkel).toFixed(0) + ".X" + dmNachFase + "Z" + z0.toFixed(3)
      + (rad > 0 ? ",R" + rad.toFixed(2) : "") + "F" + ff);
    zeilen.push("G1X-0.5F" + ff);
    zeilen.push("G0X" + anfahrDm);
  }

  zeilen.push("G0X" + (dm + 4).toFixed(2) + "Z" + (z0 + laenge + ueber).toFixed(2));
  return zeilen.join("\n");
}

// Dieselbe Kontur, aber ohne A-Programmierung: jeder Punkt ist
// ausgerechnet. Ein Radius wird dabei in einen G2-Bogen aufgelöst.
// Steuerungen, die ",A" und ",R" nicht kennen, fahren damit gleich.
function baueGcodeEinfach(g) {
  const dm = parseFloat(g.dm) || 0;
  const z0 = parseFloat(g.zStart) || 0;
  const fase = parseFloat(g.fase) || 0;
  const winkel = parseFloat(g.winkel) || 45;
  const rad = g.radienAn ? (parseFloat(g.radius) || 0) : 0;
  const f = (parseFloat(g.vorschub) || 0.03).toFixed(2);
  const ff = (parseFloat(g.vorschubFein) || 0.02).toFixed(2);
  const ueber = parseFloat(g.ueberlauf) || 0.5;
  const laenge = parseFloat(g.laenge) || 2;

  const anfahrDm = (dm + 2).toFixed(2);
  const tiefe = fase / Math.tan(bogenGrad(winkel));
  const dmNachFase = dm - 2 * fase;

  // Der Radius sitzt am Übergang von der Stirnfläche in die Fase.
  // Sein Anfang liegt auf der Stirnfläche, sein Ende auf der Fase.
  const halb = bogenGrad(winkel) / 2;
  const abstand = rad > 0 ? rad * Math.tan(halb) : 0;
  const zeilen = [];

  if (g.richtung === "stirn") {
    const zRadEnde = z0 + abstand * Math.sin(bogenGrad(winkel));
    const dmRadEnde = dmNachFase - 2 * (tiefe - abstand * Math.cos(bogenGrad(winkel)))
      * Math.tan(bogenGrad(winkel));

    zeilen.push("G0X" + anfahrDm + "Z" + z0.toFixed(3));
    zeilen.push("G1X-0.500F" + f);
    zeilen.push("G1X0.000");
    if (rad > 0) {
      zeilen.push("G1X" + (2 * abstand).toFixed(3) + "F" + ff);
      zeilen.push("G3X" + (2 * (abstand + rad * Math.sin(bogenGrad(winkel)))).toFixed(3)
        + "Z" + (z0 + rad * (1 - Math.cos(bogenGrad(winkel)))).toFixed(3)
        + "R" + rad.toFixed(3) + "F" + ff);
    }
    zeilen.push("G1X" + dmNachFase.toFixed(3) + "Z" + (z0 + tiefe).toFixed(3) + "F" + ff);
    zeilen.push("G1X" + dm.toFixed(3) + "Z" + (z0 + tiefe).toFixed(3) + "F" + f);
    zeilen.push("G1Z" + (z0 + laenge).toFixed(3) + "F" + f);
  } else {
    zeilen.push("G0X" + anfahrDm + "Z" + (z0 + laenge).toFixed(3));
    zeilen.push("G1X" + dm.toFixed(3) + "F" + f);
    zeilen.push("G1Z" + (z0 + tiefe).toFixed(3) + "F" + f);
    zeilen.push("G1X" + dmNachFase.toFixed(3) + "Z" + z0.toFixed(3) + "F" + ff);
    if (rad > 0) {
      zeilen.push("G2X" + Math.max(0, dmNachFase - 2 * abstand).toFixed(3)
        + "Z" + z0.toFixed(3) + "R" + rad.toFixed(3) + "F" + ff);
    }
    zeilen.push("G1X-0.500F" + ff);
    zeilen.push("G0X" + anfahrDm);
  }

  zeilen.push("G0X" + (dm + 4).toFixed(2) + "Z" + (z0 + laenge + ueber).toFixed(3));
  return zeilen.join("\n");
}

function rechnerGcode(ziel) {
  const text = gcode.ohneA ? baueGcodeEinfach(gcode) : baueGcode(gcode);
  const fassung = gcode.ohneA
    ? "Alle Punkte ausgerechnet — läuft auf jeder Steuerung"
    : "Mit A- und R-Programmierung — kurz, braucht eine Steuerung, die das kennt";

  ladeFertig(ziel);
  ziel.innerHTML = ''
    + '<section class="karte"><h2>Was soll gedreht werden?</h2>'
    + bildGcode(gcode)
    + '<div class="moduswahl">'
    + '<button class="moduswahl__knopf' + (gcode.richtung === "stirn" ? " aktiv" : "")
    + '" data-gr="stirn">Stirn zum Durchmesser</button>'
    + '<button class="moduswahl__knopf' + (gcode.richtung === "aussen" ? " aktiv" : "")
    + '" data-gr="aussen">Durchmesser zur Stirn</button>'
    + '</div>'

    + '<div class="zeitraumwahl">'
    + '<label class="feld"><span>Durchmesser in mm</span>'
    + '<input type="number" id="g-dm" step="0.01" value="' + esc(gcode.dm) + '"></label>'
    + '<label class="feld"><span>Z am Anfang</span>'
    + '<input type="number" id="g-z" step="0.01" value="' + esc(gcode.zStart) + '"></label>'
    + '</div>'

    + '<div class="zeitraumwahl">'
    + '<label class="feld"><span>Fasenbreite in mm</span>'
    + '<input type="number" id="g-fase" step="0.05" value="' + esc(gcode.fase) + '"></label>'
    + '<label class="feld"><span>Winkel in Grad</span>'
    + '<input type="number" id="g-winkel" step="1" value="' + esc(gcode.winkel) + '"></label>'
    + '</div>'

    + '<label class="schalter"><input type="checkbox" id="g-radan"'
    + (gcode.radienAn ? " checked" : "") + '>'
    + '<span>Übergänge verrunden</span></label>'

    // Manche Steuerungen kennen ",A" und ",R" nicht. Dann rechnet
    // die App jeden Punkt aus und gibt reine G1- und G2-Sätze aus.
    + '<label class="schalter"><input type="checkbox" id="g-ohnea"'
    + (gcode.ohneA ? " checked" : "") + '>'
    + '<span>Ohne A-Programmierung, alle Punkte ausgerechnet</span></label>'
    + (gcode.radienAn
      ? '<label class="feld"><span>Radius in mm</span>'
        + '<input type="number" id="g-radius" step="0.05" value="' + esc(gcode.radius) + '"></label>'
      : "")

    + '<div class="zeitraumwahl">'
    + '<label class="feld"><span>Vorschub grob</span>'
    + '<input type="number" id="g-f" step="0.005" value="' + esc(gcode.vorschub) + '"></label>'
    + '<label class="feld"><span>Vorschub fein</span>'
    + '<input type="number" id="g-ff" step="0.005" value="' + esc(gcode.vorschubFein) + '"></label>'
    + '</div>'

    + '<label class="feld"><span>Länge des Zylinders in mm</span>'
    + '<input type="number" id="g-laenge" step="0.1" value="' + esc(gcode.laenge) + '"></label>'
    + '</section>'

    + '<section class="karte"><div class="karte__kopf"><h2>Programm</h2>'
    + '<button class="linkknopf" id="g-kopieren">Kopieren</button></div>'
    + '<p class="klein">' + esc(fassung) + '</p>'
    + '<pre class="gcode">' + esc(text) + '</pre>'
    + '<p class="hinweis">Fanuc-Schreibweise mit Winkel- und Radiusangaben. '
    + 'Bitte vor dem ersten Lauf am Simulator prüfen. Werkzeugaufruf, Drehzahl und '
    + 'Kühlung fehlen bewusst, die stehen bei euch im Rahmenprogramm.</p>'
    + '</section>';

  const binde = (id, feld) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.onchange = () => { gcode[feld] = el.value; rechnerGcode(ziel); };
  };
  binde("g-dm", "dm"); binde("g-z", "zStart"); binde("g-fase", "fase");
  binde("g-winkel", "winkel"); binde("g-radius", "radius");
  binde("g-f", "vorschub"); binde("g-ff", "vorschubFein"); binde("g-laenge", "laenge");

  ziel.querySelectorAll("[data-gr]").forEach((el) => {
    el.onclick = () => { gcode.richtung = el.dataset.gr; rechnerGcode(ziel); };
  });

  const ohneA = document.getElementById("g-ohnea");
  if (ohneA) ohneA.onchange = () => { gcode.ohneA = ohneA.checked; rechnerGcode(ziel); };

  const radAn = document.getElementById("g-radan");
  if (radAn) radAn.onchange = () => { gcode.radienAn = radAn.checked; rechnerGcode(ziel); };

  document.getElementById("g-kopieren").onclick = async () => {
    try {
      await navigator.clipboard.writeText(text);
      meldung("Programm kopiert.");
    } catch (f) {
      meldung("Kopieren nicht möglich. Bitte von Hand markieren.", "warn");
    }
  };
}

// ---------- Winkel und Fase ----------

const wink = { a: "", g: "", h: "", winkel: "" };
const fase = { d: "", b: "1", winkel: "45" };

function bogenGrad(grad) { return grad * Math.PI / 180; }

// Zeichnung 1: rechtwinkliges Dreieck mit Beschriftung
function bildDreieck(a, g, h, w) {
  const z = (x, e) => (x === undefined || x === null || isNaN(x))
    ? e : (Math.round(x * 100) / 100).toLocaleString("de-CH");

  return '<svg viewBox="0 0 300 190" class="zeichnung" role="img"'
    + ' aria-label="Rechtwinkliges Dreieck mit Ankathete a, Gegenkathete b, Hypotenuse c und Winkel">'
    + '<polygon points="40,150 250,150 250,45" fill="var(--marke-hell)"'
    + ' stroke="var(--marke)" stroke-width="2.5"/>'
    // rechter Winkel
    + '<path d="M250,132 L233,132 L233,150" fill="none" stroke="var(--marke)" stroke-width="1.5"/>'
    // Winkelbogen unten links
    + '<path d="M78,150 A38,38 0 0,0 74,133" fill="none" stroke="var(--tinte)" stroke-width="2"/>'
    + '<text x="84" y="141" class="zbeschriftung">' + z(w, "β") + '°</text>'
    // Seiten
    + '<text x="145" y="170" class="zbeschriftung" text-anchor="middle">a = ' + z(a, "a") + '</text>'
    + '<text x="262" y="102" class="zbeschriftung">b = ' + z(g, "b") + '</text>'
    + '<text x="130" y="88" class="zbeschriftung" text-anchor="middle">c = ' + z(h, "c") + '</text>'
    + '</svg>';
}

// Zeichnung 2: Fase an einer Bohrung, im Schnitt
function bildBohrung(d, b, w, t) {
  const z = (x, e) => (x === undefined || x === null || isNaN(x))
    ? e : (Math.round(x * 100) / 100).toLocaleString("de-CH");

  return '<svg viewBox="0 0 300 190" class="zeichnung" role="img"'
    + ' aria-label="Fase an einer Bohrung im Schnitt">'
    // Werkstück links und rechts, dazwischen die Bohrung
    + '<path d="M20,40 L110,40 L140,70 L140,170 L20,170 Z" fill="var(--grund)"'
    + ' stroke="var(--tinte)" stroke-width="2"/>'
    + '<path d="M280,40 L190,40 L160,70 L160,170 L280,170 Z" fill="var(--grund)"'
    + ' stroke="var(--tinte)" stroke-width="2"/>'
    // Schraffur andeuten
    + '<g stroke="var(--linie-stark)" stroke-width="1">'
    + '<line x1="30" y1="170" x2="80" y2="120"/><line x1="50" y1="170" x2="100" y2="120"/>'
    + '<line x1="70" y1="170" x2="120" y2="120"/><line x1="200" y1="170" x2="250" y2="120"/>'
    + '<line x1="220" y1="170" x2="270" y2="120"/><line x1="240" y1="170" x2="280" y2="130"/>'
    + '</g>'
    // Fasenflächen hervorheben
    + '<line x1="110" y1="40" x2="140" y2="70" stroke="var(--marke)" stroke-width="3"/>'
    + '<line x1="190" y1="40" x2="160" y2="70" stroke="var(--marke)" stroke-width="3"/>'
    // Massangabe b (Fasenbreite, radial)
    + '<line x1="160" y1="26" x2="190" y2="26" stroke="var(--marke)" stroke-width="1.5"/>'
    + '<line x1="160" y1="20" x2="160" y2="46" stroke="var(--marke)" stroke-width="1"/>'
    + '<line x1="190" y1="20" x2="190" y2="46" stroke="var(--marke)" stroke-width="1"/>'
    + '<text x="175" y="17" class="zbeschriftung" text-anchor="middle">b = ' + z(b, "b") + '</text>'
    // Massangabe t (Tiefe, axial)
    + '<line x1="205" y1="40" x2="205" y2="70" stroke="var(--marke)" stroke-width="1.5"/>'
    + '<line x1="196" y1="40" x2="214" y2="40" stroke="var(--marke)" stroke-width="1"/>'
    + '<line x1="196" y1="70" x2="214" y2="70" stroke="var(--marke)" stroke-width="1"/>'
    + '<text x="219" y="60" class="zbeschriftung">t = ' + z(t, "t") + '</text>'
    // Winkel
    + '<path d="M126,40 A16,16 0 0,0 121,51" fill="none" stroke="var(--tinte)" stroke-width="1.5"/>'
    + '<text x="130" y="57" class="zbeschriftung">' + z(w, "β") + '°</text>'
    // Bohrungsdurchmesser
    + '<line x1="140" y1="150" x2="160" y2="150" stroke="var(--tinte)" stroke-width="1.5"/>'
    + '<text x="150" y="186" class="zbeschriftung" text-anchor="middle">Ø ' + z(d, "d") + '</text>'
    + '</svg>';
}

function rechnerWinkel(ziel) {
  // Rechtwinkliges Dreieck:
  //   a = Ankathete, g = Gegenkathete, h = Hypotenuse, w = Winkel
  const a = parseFloat(wink.a);
  const g = parseFloat(wink.g);
  const h = parseFloat(wink.h);
  const w = parseFloat(wink.winkel);

  let ra = a, rg = g, rh = h, rw = w;
  const da = !isNaN(a), dg = !isNaN(g), dh = !isNaN(h), dw = !isNaN(w);
  const grad = (x) => x * 180 / Math.PI;

  if (da && dg) { rh = Math.sqrt(a * a + g * g); rw = grad(Math.atan(g / a)); }
  else if (da && dh && h > a) { rg = Math.sqrt(h * h - a * a); rw = grad(Math.acos(a / h)); }
  else if (dg && dh && h > g) { ra = Math.sqrt(h * h - g * g); rw = grad(Math.asin(g / h)); }
  else if (dw && da) { rg = a * Math.tan(bogenGrad(w)); rh = a / Math.cos(bogenGrad(w)); }
  else if (dw && dg) { ra = g / Math.tan(bogenGrad(w)); rh = g / Math.sin(bogenGrad(w)); }
  else if (dw && dh) { ra = h * Math.cos(bogenGrad(w)); rg = h * Math.sin(bogenGrad(w)); }
  else { ra = rg = rh = rw = NaN; }

  const z = (x) => (x === undefined || x === null || isNaN(x)) ? "–"
    : (Math.round(x * 1000) / 1000).toLocaleString("de-CH");

  // Fase an der Bohrung
  const fd = parseFloat(fase.d);
  const fb = parseFloat(fase.b);
  const fw = parseFloat(fase.winkel);
  const ft = (!isNaN(fb) && !isNaN(fw) && fw > 0 && fw < 90)
    ? fb / Math.tan(bogenGrad(fw)) : NaN;
  const fdAussen = (!isNaN(fd) && !isNaN(fb)) ? fd + 2 * fb : NaN;
  const fs = (!isNaN(fb) && !isNaN(ft)) ? Math.sqrt(fb * fb + ft * ft) : NaN;

  ladeFertig(ziel);
  ziel.innerHTML = ''
    // ---------- Dreieck ----------
    + '<section class="karte"><h2>Rechtwinkliges Dreieck</h2>'
    + bildDreieck(ra, rg, rh, rw)
    + '<p class="hinweis">Zwei Werte eingeben, die anderen werden berechnet.</p>'
    + '<div class="zeitraumwahl">'
    + '<label class="feld"><span>Ankathete a in mm</span>'
    + '<input type="number" id="w-a" inputmode="decimal" step="0.01" value="' + esc(wink.a) + '"></label>'
    + '<label class="feld"><span>Gegenkathete b in mm</span>'
    + '<input type="number" id="w-g" inputmode="decimal" step="0.01" value="' + esc(wink.g) + '"></label>'
    + '</div>'
    + '<div class="zeitraumwahl">'
    + '<label class="feld"><span>Hypotenuse c in mm</span>'
    + '<input type="number" id="w-h" inputmode="decimal" step="0.01" value="' + esc(wink.h) + '"></label>'
    + '<label class="feld"><span>Winkel β in Grad</span>'
    + '<input type="number" id="w-w" inputmode="decimal" step="0.1" value="' + esc(wink.winkel) + '"></label>'
    + '</div>'
    + '<button class="linkknopf" id="w-leer">Alles zurücksetzen</button>'
    + '</section>'

    + '<section class="karte karte--ergebnis"><div class="ergebnisreihe">'
    + '<div class="ergebnis"><div class="ergebnis__titel">a</div>'
    + '<div class="ergebnis__wert ergebnis__wert--klein">' + z(ra) + '<span>mm</span></div></div>'
    + '<div class="ergebnis"><div class="ergebnis__titel">b</div>'
    + '<div class="ergebnis__wert ergebnis__wert--klein">' + z(rg) + '<span>mm</span></div></div>'
    + '<div class="ergebnis"><div class="ergebnis__titel">c</div>'
    + '<div class="ergebnis__wert ergebnis__wert--klein">' + z(rh) + '<span>mm</span></div></div>'
    + '<div class="ergebnis"><div class="ergebnis__titel">Winkel β</div>'
    + '<div class="ergebnis__wert ergebnis__wert--klein">' + z(rw) + '<span>°</span></div></div>'
    + '</div></section>'

    // ---------- Fase an der Bohrung ----------
    + '<section class="karte"><h2>Fase an einer Bohrung</h2>'
    + bildBohrung(fd, fb, fw, ft)
    + '<p class="hinweis">b ist die Fasenbreite am Rand, t die Tiefe in Achsrichtung. '
    + 'β ist der Winkel zwischen Fase und Stirnfläche. Bei 45° sind b und t gleich gross.</p>'
    + '<div class="zeitraumwahl">'
    + '<label class="feld"><span>Bohrung Ø in mm</span>'
    + '<input type="number" id="f-d" inputmode="decimal" step="0.1" value="' + esc(fase.d)
    + '"></label>'
    + '<label class="feld"><span>Fasenbreite b in mm</span>'
    + '<input type="number" id="f-b" inputmode="decimal" step="0.05" value="' + esc(fase.b) + '"></label>'
    + '</div>'
    + '<label class="feld"><span>Winkel β in Grad</span>'
    + '<input type="number" id="f-w" inputmode="decimal" step="1" value="' + esc(fase.winkel) + '"></label>'
    + '<div class="wahlgitter">'
    + [30, 45, 60, 90].map((gr) => '<button class="wahlknopf'
        + (Number(fase.winkel) === gr ? " aktiv" : "") + '" data-fwinkel="' + gr + '">'
        + gr + '°</button>').join("")
    + '</div>'
    + '</section>'

    + '<section class="karte karte--ergebnis"><div class="ergebnisreihe">'
    + '<div class="ergebnis"><div class="ergebnis__titel">Tiefe t</div>'
    + '<div class="ergebnis__wert ergebnis__wert--klein">' + z(ft) + '<span>mm</span></div></div>'
    + '<div class="ergebnis"><div class="ergebnis__titel">Fasen Ø aussen</div>'
    + '<div class="ergebnis__wert ergebnis__wert--klein">' + z(fdAussen) + '<span>mm</span></div></div>'
    + '<div class="ergebnis"><div class="ergebnis__titel">Fasenlänge</div>'
    + '<div class="ergebnis__wert ergebnis__wert--klein">' + z(fs) + '<span>mm</span></div></div>'
    + '</div>'
    + '<p class="hinweis">Auf so viel Durchmesser musst du senken. '
    + 'Die Fasenlänge ist die schräge Strecke, also der Weg des Werkzeugs.</p>'
    + '</section>'

    // ---------- Tabelle ----------
    + '<section class="karte"><h2>Häufige Fasen</h2><table class="tabelle">'
    + '<thead><tr><th>Angabe</th><th class="mitte">b</th>'
    + '<th class="mitte">t</th><th class="mitte">Länge</th></tr></thead><tbody>'
    + [[0.2, 45], [0.3, 45], [0.5, 45], [1, 45], [1.5, 45], [2, 45], [0.5, 30], [1, 30], [1, 60]]
        .map(([m, gr]) => {
          const tt = m / Math.tan(bogenGrad(gr));
          const ss = Math.sqrt(m * m + tt * tt);
          return '<tr><td class="stark">' + m + ' × ' + gr + '°</td>'
            + '<td class="mitte">' + m + '</td>'
            + '<td class="mitte">' + (Math.round(tt * 100) / 100) + '</td>'
            + '<td class="mitte">' + (Math.round(ss * 100) / 100) + '</td></tr>';
        }).join("")
    + '</tbody></table></section>';

  const binde = (id, obj, feld) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.onchange = () => { obj[feld] = el.value; rechnerWinkel(ziel); };
  };
  binde("w-a", wink, "a"); binde("w-g", wink, "g");
  binde("w-h", wink, "h"); binde("w-w", wink, "winkel");
  binde("f-d", fase, "d"); binde("f-b", fase, "b"); binde("f-w", fase, "winkel");

  ziel.querySelectorAll("[data-fwinkel]").forEach((el) => {
    el.onclick = () => { fase.winkel = el.dataset.fwinkel; rechnerWinkel(ziel); };
  });

  document.getElementById("w-leer").onclick = () => {
    wink.a = wink.g = wink.h = wink.winkel = "";
    rechnerWinkel(ziel);
  };
}

