const best = {
  ansicht: "offen",
  artikelSuche: "",
  artikelBez: "",
  lieferantId: null,
  offenSuche: "",
  historieSuche: "",
  bezSuche: "",
  liefSuche: "",
  // Alle Maschinen für die Zuweisung einer Lieferung, unabhängig
  // von der Parkzuweisung der angemeldeten Person
  alleMaschinen: [],
};

const BESTELLSTATUS = {
  offen: "Offen",
  bestellt: "Bestellt",
  teilweise_geliefert: "Teilweise geliefert",
  geliefert: "Geliefert",
};

// Reihenfolge der Abschnitte in der Übersicht
const OFFENE_STATUS = ["offen", "bestellt", "teilweise_geliefert"];

// Seit wann eine Position ihren jetzigen Status hat. Genau, wenn die
// Datenbank das Feld status_am kennt; sonst aus den bisherigen Zeiten.
function statusZeit(z) {
  if (z.status_am) return z.status_am;
  if (z.status === "geliefert") return z.delivered_at || z.completed_at || z.created_at || "";
  if (z.status === "bestellt" || z.status === "teilweise_geliefert") return z.ordered_at || z.created_at || "";
  return z.created_at || "";
}
function statusZeitText(z) {
  const t = statusZeit(z);
  return t ? (BESTELLSTATUS[z.status] || z.status) + " am " + datumZeitKurz(t) : "";
}

// Was zu einem Statuswechsel gehört: der Zeitpunkt, und beim Weg
// zurück aus "geliefert" fallen die Lieferzeiten wieder weg
function statusDaten(neuStatus, alterStatus) {
  const jetzt = new Date().toISOString();
  const daten = { status: neuStatus, status_am: jetzt };
  // Das Bestelldatum gilt ab dem ersten Bestellen — ein Zurücksetzen
  // aus "geliefert" lässt es stehen, der Wechsel steht in status_am
  if (neuStatus === "bestellt" && (!alterStatus || alterStatus === "offen")) daten.ordered_at = jetzt;
  if (neuStatus === "geliefert") { daten.delivered_at = jetzt; daten.completed_at = jetzt; }
  if (neuStatus !== "geliefert" && alterStatus === "geliefert") {
    daten.delivered_at = null; daten.completed_at = null;
  }
  return daten;
}

// Status einer Position ändern — derselbe Weg aus Offen, Bestellt und
// Historie, damit sich ein Versehen überall rückgängig machen lässt
function bestStatusDialog(z, b) {
  const huelle = document.createElement("div");
  huelle.className = "dialog-huelle";
  huelle.innerHTML = '<div class="dialog"><h2>Status ändern</h2>'
    + (statusZeit(z) ? '<p class="klein">Jetzt: ' + esc(statusZeitText(z)) + '</p>' : "")
    + '<div class="statuswahl">'
    + Object.keys(BESTELLSTATUS).map((st) => '<button class="knopf'
          + (z.status === st ? " knopf--haupt" : "") + '" data-neu="' + st + '">'
          + BESTELLSTATUS[st] + '</button>').join("")
    + '</div><div class="dialog__knoepfe">'
    + '<button class="knopf knopf--still" data-nein>Abbrechen</button></div></div>';
  document.body.appendChild(huelle);

  huelle.querySelector("[data-nein]").onclick = () => huelle.remove();
  huelle.onclick = (e) => { if (e.target === huelle) huelle.remove(); };

  huelle.querySelectorAll("[data-neu]").forEach((k) => {
    k.onclick = async () => {
      const neuStatus = k.dataset.neu;
      if (neuStatus === z.status && neuStatus !== "teilweise_geliefert") { huelle.remove(); return; }
      let daten = statusDaten(neuStatus, z.status);

      if (neuStatus === "teilweise_geliefert") {
        // Bei einer Teillieferung zählt, wie viel schon da ist
        const w = await dialogFelder({ titel: "Teilweise geliefert",
          hinweis: "Bestellt: " + zahlText(z.quantity) + " Stück",
          felder: [{ name: "menge", label: "Wie viel ist geliefert?", typ: "number",
                     wert: z.geliefert_menge || "", pflicht: true }],
          bestaetigen: "Speichern" });
        if (!w) return;
        const menge = Number(w.menge);
        if (!(menge > 0)) { meldung("Bitte eine Menge eingeben.", "warn"); return; }
        if (menge >= Number(z.quantity || 0)) {
          const ganz = await nachfragen({ titel: "Alles da?",
            text: "Das ist die ganze bestellte Menge. Als geliefert abschliessen?",
            bestaetigen: "Ja, geliefert", abbrechen: "Nein, teilweise lassen" });
          if (ganz) daten = statusDaten("geliefert", z.status);
        }
        daten.geliefert_menge = menge;
      } else {
        const ok = await nachfragen({ titel: "Status ändern",
          text: 'Wirklich auf "' + BESTELLSTATUS[neuStatus] + '" setzen?',
          bestaetigen: "Ja, ändern" });
        if (!ok) return;
      }

      huelle.remove();
      try {
        const r = await aendernOhneUnbekannte("order_items", daten, "id", z.id);
        meldung(r.weggelassen && r.weggelassen.indexOf("geliefert_menge") !== -1
          ? "Status geändert. Die Menge braucht noch teillieferung.sql in der Datenbank."
          : "Status geändert.");
        stammVergessen("bestellungen");
        seiteBestellungen(b);
      } catch (f) { meldung(fehlertext(f), "fehler"); }
    };
  });
}

async function ladeBestellungen(offen) {
  // Beim Suchen und Blättern wird nicht neu geholt. Nach jeder
  // Änderung (Bestellen, Liefern, Löschen) wird das Gedächtnis
  // verworfen, siehe seiteBestellungen.
  return stammGemerkt("bestellungen" + (offen ? "-offen" : ""),
    () => ladeBestellungenFrisch(offen));
}

async function ladeBestellungenFrisch(offen) {
  let a = db.from("order_items")
    .select("*, articles(article_number, name, unit, supplier_id, description, suppliers(name, website, email, adresse, bestellweg)), suppliers(name, website, email, adresse, bestellweg), profiles!order_items_created_by_fkey(full_name, email)")
    .order("needed_by", { ascending: true, nullsFirst: false })
    .order("created_at");
  if (offen) a = a.in("status", OFFENE_STATUS);
  else a = a.eq("status", "geliefert").limit(200)
             .order("created_at", { ascending: false });

  const { data, error } = await zeitlimit(a, 12000, "Bestellungen");
  if (error) throw error;
  return data || [];
}

// Die Seite ist in src/seiten/Bestellungen.jsx. Wer hier
// seiteBestellungen(b) aufruft, frischt sie auf.
const seiteBestellungen = reactSeite(Bestellungen);

// Reiter Offen und Bestellt: src/seiten/bestellungen/Offen.jsx

// Beim Liefern nur noch den Status setzen. Eine Lagerhaltung
// gibt es nicht mehr.
async function lieferungEinlagern(z, b) {
  const a = z.articles || {};

  const ok = await nachfragen({
    titel: "Lieferung eingetroffen",
    text: (a.article_number || "") + " " + (a.name || "")
        + " · " + zahlText(z.quantity) + " Stück. Position auf geliefert setzen?",
    bestaetigen: "Ja, geliefert" });
  if (!ok) return;

  let error = null;
  try { await aendernOhneUnbekannte("order_items", statusDaten("geliefert", z.status), "id", z.id); }
  catch (f) { error = f; }
  stammVergessen("bestellungen");

  if (error) meldung(fehlertext(error), "fehler");
  else { meldung("Als geliefert gebucht."); seiteBestellungen(b); }
}

// ---------- Neue Position ----------

// Legt einen Artikel mit den nötigsten Angaben an und gibt ihn zurück.
// lieferantVorgabe: ist der Lieferant schon gewählt — etwa im
// Einrichtblatt, wo man zuerst den Hersteller aussucht —, wird er
// nicht noch einmal abgefragt.
async function artikelSchnellAnlegen(vorgabe, lieferantVorgabe) {
  let lieferanten = [], bezeichnungen = [];
  try { lieferanten = await ladeLieferanten(); } catch (f) { /* geht auch ohne */ }
  try { bezeichnungen = await ladeBezeichnungen(); } catch (f) { /* geht auch ohne */ }

  const w = await dialogFelder({
    titel: "Neuen Artikel anlegen",
    felder: [
      { name: "nummer", label: "Artikelnummer", pflicht: true, wert: vorgabe || "" },
      { name: "beschreibung", label: "Beschreibung", typ: "textarea",
        platzhalter: "nur falls nötig, kann leer bleiben" },
    ],
    bestaetigen: "Weiter",
  });
  if (!w) return null;

  // Bezeichnung aus der gepflegten Liste wählen
  const bez = await bezeichnungWaehlen(bezeichnungen);
  if (bez === null) return null;
  w.name = bez;

  let lieferantId = null;
  // Ein Lieferant ist Pflicht. Die Abfrage wiederholt sich,
  // bis wirklich einer gewählt oder neu angelegt wurde.
  let wahl = lieferantVorgabe || null;
  while (!wahl) {
    const auswahlListe = lieferanten.map((l) => ({ wert: l.id, text: l.name, such: l.name }))
      .concat([{ wert: "__neu", text: "+ Neuen Lieferanten anlegen", such: "neu" }]);

    wahl = auswahlListe.length > 12
      ? await auswahlSuchen("Lieferant wählen (Pflicht)", auswahlListe)
      : await auswahlDialog("Lieferant wählen (Pflicht)", auswahlListe);

    if (wahl === null) return null;   // ganz abgebrochen
    if (!wahl) { wahl = null; continue; }   // leer gewählt, nochmal fragen
  }

  if (wahl === "__neu") {
    const nw = await dialogFelder({ titel: "Neuer Lieferant",
      felder: [
        { name: "name", label: "Name", pflicht: true },
        { name: "website", label: "Website", platzhalter: "www.beispiel.ch",
          hinweis: "Der Name wird dann überall in der App anklickbar." },
      ], bestaetigen: "Anlegen" });
    if (nw) {
      let seite = (nw.website || "").trim();
      if (seite && !/^https?:\/\//i.test(seite)) seite = "https://" + seite;
      const r = await db.from("suppliers")
        .insert({ name: nw.name, website: seite || null }).select().single();
      if (r.error) meldung(fehlertext(r.error), "fehler");
      else { lieferantId = r.data.id; lieferanten.push(r.data); meldung("Lieferant angelegt."); }
    } else {
      return null;
    }
  } else {
    lieferantId = wahl;
  }

  if (!lieferantId) {
    meldung("Ohne Lieferant lässt sich der Artikel nicht anlegen.", "warn");
    return null;
  }

  const { data, error } = await db.from("articles").insert({
    article_number: w.nummer, name: w.name,
    description: (w.beschreibung || "").trim() || null,
    unit: "Stück", supplier_id: lieferantId,
  }).select().single();

  if (error) {
    const m = String(error.message || "").toLowerCase();
    if (m.includes("duplicate") || m.includes("unique")) {
      // Der Artikel gibt es schon, taucht aber vielleicht nicht in der
      // Liste auf, weil er ausgeblendet ist. Also holen und anbieten.
      const alt = await db.from("articles").select("*")
        .eq("article_number", w.nummer).maybeSingle();

      if (alt.data) {
        const ok = await nachfragen({
          titel: "Artikel gibt es bereits",
          text: alt.data.article_number + " · " + (alt.data.name || "")
              + (alt.data.is_active === false
                  ? " — er ist zurzeit ausgeblendet, deshalb siehst du ihn nicht in der Liste."
                  : "")
              + " Soll dieser Artikel verwendet werden?",
          bestaetigen: "Diesen verwenden" });

        if (!ok) return null;

        if (alt.data.is_active === false) {
          await db.from("articles").update({ is_active: true }).eq("id", alt.data.id);
        }

        const lief2 = lieferanten.find((l) => l.id === alt.data.supplier_id);
        return { id: alt.data.id, article_number: alt.data.article_number,
                 name: alt.data.name, supplier_id: alt.data.supplier_id,
                 supplier_name: lief2 ? lief2.name : null, unit: "Stück" };
      }
    }
    meldung(fehlertext(error), "fehler");
    return null;
  }
  meldung("Artikel angelegt.");

  const lief = lieferanten.find((l) => l.id === lieferantId);
  return { id: data.id, article_number: data.article_number, name: data.name,
           supplier_id: data.supplier_id, supplier_name: lief ? lief.name : null,
           unit: data.unit, gesamtbestand: 0 };
}

// Einfache Auswahl aus einer Liste. Gibt den gewählten Wert zurück.
// Auswahl mit Suchfeld, für lange Listen
function auswahlSuchen(titel, optionen, mindestens) {
  return new Promise((fertig) => {
    const h = document.createElement("div");
    h.className = "dialog-huelle";
    h.innerHTML = '<div class="dialog"><h2>' + esc(titel) + '</h2>'
      + '<div class="suchleiste"><input type="search" id="as-suche"'
      + ' placeholder="Suchen" autocomplete="off"></div>'
      + '<div class="statuswahl" id="as-liste"></div>'
      + '<div class="dialog__knoepfe">'
      + '<button class="knopf knopf--still" data-nein>Abbrechen</button></div></div>';
    document.body.appendChild(h);

    const zu = (v) => { h.remove(); fertig(v); };
    h.querySelector("[data-nein]").onclick = () => zu(null);
    dialogSchliessen(h, () => zu(null));

    const liste = h.querySelector("#as-liste");
    const feld = h.querySelector("#as-suche");

    const zeichnen = () => {
      const t = (feld.value || "").trim().toLowerCase();
      const treffer = optionen.filter((o) => !t || o.text.toLowerCase().includes(t));
      liste.innerHTML = treffer.length
        ? treffer.slice(0, 40).map((o) => '<button class="knopf" data-w="' + esc(o.wert)
            + '">' + esc(o.text) + '</button>').join("")
        : '<p class="hinweis">Nichts gefunden.</p>';
      liste.querySelectorAll("[data-w]").forEach((k) => { k.onclick = () => zu(k.dataset.w); });
    };

    feld.oninput = zeichnen;
    zeichnen();
    feld.focus();
  });
}

async function positionDialog(b) {
  const huelle = document.createElement("div");
  huelle.className = "dialog-huelle";
  huelle.innerHTML = '<div class="dialog"><h2>Neue Bestellposition</h2>'
    + '<div class="suchleiste">'
    + '<input type="text" id="pd-such" placeholder="Suchen" autocomplete="off">'
    + '</div>'
    + '<div id="pd-treffer" class="pd-treffer"></div>'
    + '<div id="pd-rest" hidden>'
    + '<div class="pd-gewaehlt" id="pd-gewaehlt"></div>'
    + '<div class="zeitraumwahl">'
    + '<label class="feld"><span>Menge</span>'
    + '<input id="pd-menge" type="number" min="1" step="1" value="1"></label>'
    + '<label class="feld"><span>Bis wann</span><input id="pd-frist" type="date"></label>'
    + '</div>'
    + '<div class="feld"><span class="feldlabel">Wohin nach dem Eintreffen</span>'
    + '<div class="moduswahl" id="pd-zielwahl">'
    // Lager ist der Normalfall und deshalb vorgewählt. Es wird nicht
    // verbucht, sondern steht wie jedes andere Ziel in der Historie.
    + '<button type="button" class="moduswahl__knopf aktiv" data-ziel="lager">Lager</button>'
    + '<button type="button" class="moduswahl__knopf" data-ziel="maschine">Maschine</button>'
    + '<button type="button" class="moduswahl__knopf" data-ziel="person">Person</button>'
    + '<button type="button" class="moduswahl__knopf" data-ziel="andere">Anderes</button>'
    + '</div>'
    + '<select id="pd-zielauswahl" class="auswahl" hidden></select>'
    + '<input type="text" id="pd-zielfrei" hidden>'
    + '</div>'

    + '<label class="feld"><span>Notiz</span>'
    + '<textarea id="pd-notiz" rows="2"></textarea></label>'
    + '</div>'
    + '<div class="dialog__knoepfe">'
    + '<button class="knopf knopf--still" id="pd-nein">Abbrechen</button>'
    + '<button class="knopf knopf--haupt" id="pd-ja" disabled>Hinzufügen</button>'
    + '</div></div>';
  document.body.appendChild(huelle);

  const $ = (kennung) => huelle.querySelector("#" + kennung);

  // Ziel der Lieferung
  let zielArt = "lager";
  const zielAuswahl = $("pd-zielauswahl");
  const zielFrei = $("pd-zielfrei");

  const zielFuellen = async () => {
    zielAuswahl.hidden = true;
    zielFrei.hidden = true;
    if (zielArt === "lager") return;      // Lager braucht keine weitere Angabe

    if (zielArt === "maschine") {
      zielAuswahl.hidden = false;
      const liste = best.alleMaschinen || [];
      zielAuswahl.innerHTML = '<option value="">'
        + (liste.length ? "Maschine wählen" : "Wird geladen …") + '</option>'
        + liste.map((m) => '<option value="' + esc(maschineZielText(m)) + '">'
            + esc(m.name) + (m.machine_number ? " · " + esc(m.machine_number) : "")
            + '</option>').join("");

      if (!liste.length) {
        try {
          best.alleMaschinen = await ladeAlleMaschinen();
          zielFuellen();
        } catch (f) { meldung(fehlertext(f), "fehler"); }
      }
      return;
    }

    if (zielArt === "person") {
      zielAuswahl.hidden = false;
      zielAuswahl.innerHTML = '<option value="">Wird geladen …</option>';
      try {
        const a = await db.from("profiles").select("full_name, email")
          .eq("is_active", true).order("full_name");
        const namen = (a.data || []).map((u) => u.full_name || u.email);
        try {
          const c = await db.from("people").select("name").order("name");
          (c.data || []).forEach((m) => namen.push(m.name));
        } catch (f) { /* Tabelle gibt es vielleicht nicht */ }

        zielAuswahl.innerHTML = '<option value="">Person wählen</option>'
          + namen.sort().map((n) => '<option value="' + esc(n) + '">'
              + esc(n) + '</option>').join("");
      } catch (f) {
        zielAuswahl.innerHTML = '<option value="">Konnte nicht geladen werden</option>';
      }
      return;
    }

    if (zielArt === "andere") { zielFrei.hidden = false; zielFrei.focus(); }
  };

  huelle.querySelectorAll("[data-ziel]").forEach((k) => {
    k.onclick = () => {
      zielArt = k.dataset.ziel;
      huelle.querySelectorAll("[data-ziel]").forEach((x) =>
        x.classList.toggle("aktiv", x === k));
      zielFuellen();
    };
  });
  // Ohne Lager ist Maschine der Ausgangspunkt — die Auswahl gleich zeigen
  zielFuellen();

  let gewaehlt = null;
  const zu = () => huelle.remove();
  $("pd-nein").onclick = zu;
  dialogSchliessen(huelle, zu);

  const feld = $("pd-such");
  const trefferBox = $("pd-treffer");
  feld.focus();

  const suchen = async () => {
    const t = feld.value.trim();
    if (t.length < 1) { trefferBox.innerHTML = ""; return; }
    trefferBox.innerHTML = '<div class="laedt">Wird gesucht …</div>';
    try {
      const liste = await sucheArtikel(t);
      trefferBox.innerHTML = (liste.length
        ? liste.slice(0, 8).map((a) => '<button class="pd-zeile" data-w="' + esc(a.id) + '">'
            + '<strong>' + esc(a.article_number) + '</strong> ' + esc(a.name)
            + '<span class="klein"> ' + esc(a.supplier_name || "ohne Lieferant") + '</span>'
            + '</button>').join("")
        : '<p class="hinweis">Kein Artikel gefunden.</p>')
        + (darfSchreiben()
            ? '<button class="pd-zeile pd-zeile--neu" data-neuartikel>'
              + '+ Artikel "' + esc(t) + '" neu anlegen</button>' : "");

      const neuArt = trefferBox.querySelector("[data-neuartikel]");
      if (neuArt) neuArt.onclick = async () => {
        const a = await artikelSchnellAnlegen(feld.value.trim());
        if (!a) return;
        gewaehlt = a;
        trefferBox.innerHTML = "";
        feld.value = "";
        $("pd-rest").hidden = false;
        $("pd-gewaehlt").innerHTML =
          '<strong>' + esc(a.article_number) + '</strong> ' + esc(a.name)
          + '<div class="klein">Lieferant: ' + esc(a.supplier_name || "keiner hinterlegt") + '</div>';
        $("pd-ja").disabled = false;
        $("pd-menge").focus();
      };

      trefferBox.querySelectorAll("[data-w]").forEach((el) => {
        el.onclick = () => {
          gewaehlt = liste.find((x) => x.id === el.dataset.w);
          trefferBox.innerHTML = "";
          feld.value = "";
          $("pd-rest").hidden = false;
          $("pd-gewaehlt").innerHTML =
            '<strong>' + esc(gewaehlt.article_number) + '</strong> ' + esc(gewaehlt.name)
            + '<div class="klein">Lieferant: ' + esc(gewaehlt.supplier_name || "keiner hinterlegt")
            + ' · Bestand ' + zahlText(gewaehlt.gesamtbestand) + '</div>';
          $("pd-ja").disabled = false;
          $("pd-menge").focus();
        };
      });
    } catch (f) { trefferBox.innerHTML = '<p class="hinweis">' + esc(fehlertext(f)) + '</p>'; }
  };

  let taste = null;
  feld.oninput = () => { clearTimeout(taste); taste = setTimeout(suchen, 300); };
  feld.onkeydown = (e) => { if (e.key === "Enter") { e.preventDefault(); clearTimeout(taste); suchen(); } };

  $("pd-ja").onclick = async () => {
    if (!gewaehlt) return;
    const menge = Math.round(Number($("pd-menge").value));
    if (!Number.isFinite(menge) || menge < 1) { meldung("Menge muss mindestens 1 sein.", "warn"); return; }

    // Ziel zusammensetzen
    let zielText = "";
    if (zielArt === "lager") zielText = "Lager";
    else if (zielArt === "andere") zielText = (zielFrei.value || "").trim();
    else zielText = zielAuswahl.value || "";

    if (!zielText) {
      meldung("Bitte noch angeben, wohin die Lieferung soll.", "warn");
      return;
    }

    const { error } = await db.from("order_items").insert({
      article_id: gewaehlt.id,
      supplier_id: gewaehlt.supplier_id || null,
      quantity: menge,
      needed_by: $("pd-frist").value || null,
      note: ($("pd-notiz").value || "").trim() || null,
      ziel_art: zielArt,
      ziel_text: zielText,
    });

    if (error) meldung(fehlertext(error), "fehler");
    else { zu(); meldung("Position hinzugefügt."); seiteBestellungen(b); }
  };
}

