// ---------- Artikel ----------

// Reiter Artikel: src/seiten/bestellungen/Artikel.jsx

async function artikelBearbeiten(artikel, b) {
  if (!artikel) return;

  let lieferanten = [], bezeichnungen = [];
  try { lieferanten = await ladeLieferanten(); } catch (f) { /* geht auch ohne */ }
  try { bezeichnungen = await ladeBezeichnungen(); } catch (f) { /* geht auch ohne */ }

  const huelle = document.createElement("div");
  huelle.className = "dialog-huelle";
  huelle.innerHTML = '<div class="dialog">'
    + '<h2>Artikel bearbeiten</h2>'

    + '<label class="feld"><span>Artikelnummer</span>'
    + '<input type="text" id="ab-nr" autocapitalize="characters" value="'
    + esc(artikel.article_number || "") + '"></label>'

    + '<label class="feld"><span>Bezeichnung</span>'
    + '<select id="ab-bez">'
    + bezeichnungen.map((z) => '<option value="' + esc(z.name) + '"'
        + (z.name === artikel.name ? " selected" : "") + '>' + esc(z.name) + '</option>').join("")
    + (bezeichnungen.some((z) => z.name === artikel.name) || !artikel.name
        ? "" : '<option value="' + esc(artikel.name) + '" selected>'
               + esc(artikel.name) + '  (nicht in der Liste)</option>')
    + '<option value="__neu">+ Neue Bezeichnung anlegen</option>'
    + '</select></label>'

    + '<label class="feld"><span>Lieferant (Pflicht)</span>'
    + '<select id="ab-lief">'
    + (artikel.supplier_id ? "" : '<option value="">– bitte wählen –</option>')
    + lieferanten.map((l) => '<option value="' + esc(l.id) + '"'
        + (l.id === artikel.supplier_id ? " selected" : "") + '>' + esc(l.name)
        + '</option>').join("")
    + '<option value="__neu">+ Neuer Lieferant …</option>'
    + '</select></label>'

    + '<label class="feld"><span>Beschreibung</span>'
    + '<textarea id="ab-beschreibung" rows="2">'
    + esc(artikel.description || "") + '</textarea></label>' 

    + '<div class="dialog__knoepfe">'
    + '<button class="knopf knopf--gefahr" id="ab-weg">Löschen</button>'
    + '<button class="knopf knopf--still" id="ab-nein">Abbrechen</button>'
    + '<button class="knopf knopf--haupt" id="ab-ja">Speichern</button>'
    + '</div></div>';
  document.body.appendChild(huelle);
  plan.imDialog = true;

  const $ = (k) => huelle.querySelector("#" + k);
  const zu = () => { plan.imDialog = false; huelle.remove(); };
  $("ab-nein").onclick = zu;
  dialogSchliessen(huelle, zu);
  $("ab-nr").focus();

  // Neue Bezeichnung direkt hier anlegen
  const bezFeld = $("ab-bez");
  bezFeld.onchange = async () => {
    if (bezFeld.value !== "__neu") return;
    bezFeld.value = artikel.name || "";
    const w = await dialogFelder({ titel: "Neue Bezeichnung",
      felder: [{ name: "name", label: "Bezeichnung", pflicht: true }],
      bestaetigen: "Anlegen" });
    if (!w) return;
    const { error } = await db.from("designations").insert({ name: w.name });
    if (error && !String(error.message || "").includes("duplicate")) {
      meldung(fehlertext(error), "fehler");
      return;
    }
    const opt = document.createElement("option");
    opt.value = w.name; opt.textContent = w.name; opt.selected = true;
    bezFeld.insertBefore(opt, bezFeld.lastElementChild);
    meldung("Bezeichnung angelegt.");
  };

  // Neuen Lieferanten direkt hier anlegen
  const liefFeld = $("ab-lief");
  liefFeld.onchange = async () => {
    if (liefFeld.value !== "__neu") return;
    liefFeld.value = artikel.supplier_id || "";
    const w = await dialogFelder({ titel: "Neuer Lieferant",
      felder: [
        { name: "name", label: "Name", pflicht: true },
        { name: "website", label: "Website", platzhalter: "www.beispiel.ch" }],
      bestaetigen: "Anlegen" });
    if (!w) return;
    let seite = (w.website || "").trim();
    if (seite && !/^https?:\/\//i.test(seite)) seite = "https://" + seite;
    const r = await db.from("suppliers")
      .insert({ name: w.name, website: seite || null }).select().single();
    if (r.error) { meldung(fehlertext(r.error), "fehler"); return; }
    const opt = document.createElement("option");
    opt.value = r.data.id; opt.textContent = r.data.name; opt.selected = true;
    liefFeld.insertBefore(opt, liefFeld.lastElementChild);
    meldung("Lieferant angelegt.");
  };

  $("ab-ja").onclick = async () => {
    const nummer = ($("ab-nr").value || "").trim();
    const name = bezFeld.value === "__neu" ? (artikel.name || "") : bezFeld.value;
    if (!nummer || !name) {
      meldung("Artikelnummer und Bezeichnung werden benötigt.", "warn");
      return;
    }
    if (!liefFeld.value || liefFeld.value === "__neu") {
      meldung("Bitte einen Lieferanten wählen.", "warn");
      return;
    }

    const lieferantNeu = liefFeld.value;
    const lieferantAlt = artikel.supplier_id || null;

    const r = await db.from("articles").update({
      article_number: nummer,
      name: name,
      description: ($("ab-beschreibung").value || "").trim() || null,
      unit: "Stück",
      supplier_id: lieferantNeu,
    }).eq("id", artikel.id).select();

    // Wechselt der Lieferant, ziehen alle noch offenen Bestellpositionen
    // dieses Artikels mit. Die Position merkt sich sonst den Lieferanten
    // vom Tag der Erfassung und bleibt beim falschen stehen.
    // Bereits gelieferte bleiben unangetastet — deren Geschichte soll
    // sich nicht rückwirkend ändern.
    let mitgezogen = 0;
    if (!r.error && lieferantNeu !== lieferantAlt) {
      const u = await db.from("order_items")
        .update({ supplier_id: lieferantNeu })
        .eq("article_id", artikel.id)
        .in("status", OFFENE_STATUS)
        .select();
      if (!u.error) mitgezogen = (u.data || []).length;
    }

    zu();
    if (r.error) meldung(fehlertext(r.error), "fehler");
    else if ((r.data || []).length === 0)
      meldung("Nichts geändert. Vermutlich fehlen die Rechte in der Datenbank.", "fehler");
    else {
      meldung(mitgezogen
        ? "Gespeichert. " + mitgezogen
          + (mitgezogen === 1 ? " offene Position" : " offene Positionen")
          + " beim neuen Lieferanten."
        : "Gespeichert.");
      seiteBestellungen(b);
    }
  };

  $("ab-weg").onclick = async () => {
    const ok = await nachfragen({
      titel: "Artikel löschen",
      text: '"' + artikel.article_number + '" wird gelöscht. Bestellpositionen, '
          + "die daran hängen, verschwinden mit.",
      bestaetigen: "Löschen", gefahr: true });
    if (!ok) return;

    await db.from("order_items").delete().eq("article_id", artikel.id);
    const r = await db.from("articles").delete().eq("id", artikel.id).select();

    zu();
    if (r.error) meldung(fehlertext(r.error), "fehler");
    else if ((r.data || []).length === 0)
      meldung("Nichts gelöscht. Vermutlich fehlen die Rechte in der Datenbank.", "fehler");
    else meldung("Artikel gelöscht.");

    seiteBestellungen(b);
  };
}

