// =================================================================
//  11. Reaktion: grünes Licht
// =================================================================
function spielReaktion(b) {
  b.innerHTML = spielRahmen("Grünlicht",
    "Warte, bis das Feld grün wird, und tipp dann so schnell wie möglich. "
    + "Zu früh gedrückt zählt als Fehlstart.",
    '<div class="spass-ampel" id="sp-ampel">Warten …</div>', "Starten");

  const st = spielStand("reaktion");
  st.rekordZeigen();
  const feld = document.getElementById("sp-ampel");
  let bereit = false, start = 0, warte = null, runden = 0, summe = 0;

  const neueRunde = () => {
    bereit = false;
    feld.className = "spass-ampel spass-ampel--rot";
    feld.textContent = "Noch nicht …";
    warte = setTimeout(() => {
      bereit = true;
      start = Date.now();
      feld.className = "spass-ampel spass-ampel--gruen";
      feld.textContent = "JETZT";
    }, 900 + zufall(2600));
  };

  feld.onclick = () => {
    if (!st.laeuft) return;
    if (!bereit) {
      clearTimeout(warte);
      st.setzeFehler(st.fehler + 1);
      st.sag("Fehlstart. Nerven behalten.");
      if (st.fehler >= 3) {
        st.laeuft = false; st.knopf("Nochmal");
        feld.className = "spass-ampel"; feld.textContent = "Vorbei";
        return;
      }
      neueRunde();
      return;
    }
    const zeit = Date.now() - start;
    runden++; summe += zeit;
    const schnitt = Math.round(summe / runden);
    st.setzePunkte(Math.max(1, Math.round(30000 / schnitt)));
    st.sag(zeit + " ms, Schnitt " + schnitt + " ms." + (st.rekordPruefen() ? " Rekord!" : ""));
    neueRunde();
  };

  document.getElementById("sp-knopf").onclick = () => {
    st.laeuft = true; st.setzePunkte(0); st.setzeFehler(0);
    runden = 0; summe = 0;
    st.knopf("Neu"); st.sag("Achtung.");
    neueRunde();
  };
}

// =================================================================
//  12. Gewinde raten
// =================================================================
function spielGewinde(b) {
  const TABELLE = [
    ["M3", 2.5], ["M4", 3.3], ["M5", 4.2], ["M6", 5.0], ["M8", 6.8],
    ["M10", 8.5], ["M12", 10.2], ["M16", 14.0], ["M20", 17.5],
  ];

  b.innerHTML = spielRahmen("Kernloch raten",
    "Welcher Bohrer gehört zum Gewinde? Drei Fehler und Schluss.",
    '<div class="spass-frage" id="sp-frage"></div>'
    + '<div class="spass-antworten" id="sp-antworten"></div>', "Starten");

  const st = spielStand("gewinde");
  st.rekordZeigen();

  const neueFrage = () => {
    const eintrag = auswahlZufall(TABELLE);
    const richtig = eintrag[1];
    const wahl = [richtig];
    while (wahl.length < 4) {
      const f = TABELLE[zufall(TABELLE.length)][1];
      if (!wahl.includes(f)) wahl.push(f);
    }
    wahl.sort(() => Math.random() - 0.5);

    document.getElementById("sp-frage").innerHTML =
      'Gewinde <strong>' + eintrag[0] + '</strong> — welcher Kernlochbohrer?';
    document.getElementById("sp-antworten").innerHTML = wahl.map((z) =>
      '<button class="knopf" data-z="' + z + '">' + z.toFixed(1) + ' mm</button>').join("");

    document.querySelectorAll("[data-z]").forEach((k) => {
      k.onclick = () => {
        if (!st.laeuft) return;
        if (Number(k.dataset.z) === richtig) {
          st.setzePunkte(st.punkte + 1);
          st.sag(auswahlZufall(["Sitzt.", "Genau der.", "Auswendig gelernt."]));
        } else {
          st.setzeFehler(st.fehler + 1);
          st.sag("Nein, " + richtig.toFixed(1) + " mm wären richtig.");
          if (st.fehler >= 3) {
            st.laeuft = false; st.knopf("Nochmal");
            st.sag("Schluss. " + st.punkte + " richtig."
              + (st.rekordPruefen() ? " Rekord!" : ""));
            return;
          }
        }
        neueFrage();
      };
    });
  };

  document.getElementById("sp-knopf").onclick = () => {
    st.laeuft = true; st.setzePunkte(0); st.setzeFehler(0);
    st.knopf("Neu"); st.sag("Los.");
    neueFrage();
  };
}

