// =================================================================
//  15. Späne ausweichen
// =================================================================
function spielAusweichen(b) {
  b.innerHTML = spielRahmen("Späne ausweichen",
    "Steuer das Werkstück mit dem Finger oder der Maus. Weich den Spänen aus, "
    + "so lange du kannst.",
    '<div class="spass-feld" id="sp-feld">'
    + '<div class="spass-korb" id="sp-held">🔩</div></div>', "Loslegen");

  const st = spielStand("ausweichen");
  st.rekordZeigen();
  const feld = document.getElementById("sp-feld");
  const held = document.getElementById("sp-held");
  let x = 50, takt = null, spawn = null, uhr = null, teile = [], tempo = 1.4;

  const setze = (v) => { x = Math.max(4, Math.min(96, v)); held.style.left = x + "%"; };
  setze(50);

  const ende = () => {
    clearInterval(takt); clearInterval(spawn); clearInterval(uhr);
    teile.forEach((t) => t.el.remove()); teile = [];
    st.laeuft = false; st.knopf("Nochmal");
    st.sag("Erwischt. " + st.punkte + " Sekunden durchgehalten."
      + (st.rekordPruefen() ? " Rekord!" : ""));
  };

  const schritt = () => {
    teile.forEach((t) => {
      t.y += tempo;
      t.el.style.top = t.y + "%";
      if (t.y >= 80 && t.y <= 92 && Math.abs(t.x - x) < 8) { t.getroffen = true; }
      if (t.y > 100) t.weg = true;
    });
    if (teile.some((t) => t.getroffen)) return ende();
    teile.filter((t) => t.weg).forEach((t) => t.el.remove());
    teile = teile.filter((t) => !t.weg);
    tempo = Math.min(4, tempo + 0.003);
  };

  const neuesTeil = () => {
    const el = document.createElement("div");
    el.className = "spass-ei";
    el.textContent = "🌀";
    const px = 4 + zufall(92);
    el.style.left = px + "%"; el.style.top = "0%";
    feld.appendChild(el);
    teile.push({ el: el, x: px, y: 0 });
  };

  feld.onpointermove = (e) => {
    if (!st.laeuft) return;
    const r = feld.getBoundingClientRect();
    setze((e.clientX - r.left) / r.width * 100);
  };

  document.getElementById("sp-knopf").onclick = () => {
    if (st.laeuft) return ende();
    st.laeuft = true; st.setzePunkte(0); st.setzeFehler(0);
    tempo = 1.4; teile = [];
    feld.querySelectorAll(".spass-ei").forEach((e) => e.remove());
    st.knopf("Abbrechen"); st.sag("Ausweichen!");
    takt = setInterval(schritt, 24);
    spawn = setInterval(neuesTeil, 520);
    uhr = setInterval(() => st.setzePunkte(st.punkte + 1), 1000);
  };
}

// =================================================================
//  16. Hühner sortieren
// =================================================================
function spielSortieren(b) {
  b.innerHTML = spielRahmen("Hühner nach Grösse",
    "Tipp die Hühner von klein nach gross an. Ein Fehler und die Runde ist futsch.",
    '<div class="spass-wiese" id="sp-wiese"></div>', "Starten");

  const st = spielStand("sortieren");
  st.rekordZeigen();
  const wiese = document.getElementById("sp-wiese");
  let runde = 0;

  const neueRunde = () => {
    runde++;
    const anzahl = Math.min(8, 3 + Math.floor(runde / 2));
    const groessen = [];
    while (groessen.length < anzahl) {
      const g = 1 + zufall(28);
      if (!groessen.includes(g)) groessen.push(g);
    }
    const sortiert = groessen.slice().sort((a, c) => a - c);
    let naechste = 0;

    wiese.innerHTML = groessen.map((g, i) =>
      '<button class="spass-huhn spass-huhn--gross" data-g="' + g + '"'
      + ' style="left:' + (4 + i * (88 / anzahl)) + '%;top:' + (20 + zufall(40))
      + '%;font-size:' + (1.1 + g / 14) + 'rem">🐔</button>').join("");

    wiese.querySelectorAll("[data-g]").forEach((h) => {
      h.onclick = () => {
        if (!st.laeuft) return;
        if (Number(h.dataset.g) !== sortiert[naechste]) {
          st.setzeFehler(st.fehler + 1);
          st.sag("Das war nicht das kleinste.");
          if (st.fehler >= 3) {
            st.laeuft = false; st.knopf("Nochmal"); wiese.innerHTML = "";
            st.sag("Schluss. " + st.punkte + " Runden."
              + (st.rekordPruefen() ? " Rekord!" : ""));
            return;
          }
          neueRunde();
          return;
        }
        h.remove();
        naechste++;
        if (naechste >= anzahl) {
          st.setzePunkte(st.punkte + 1);
          st.sag(auswahlZufall(["Sauber sortiert.", "Alle im Stall."]));
          setTimeout(neueRunde, 500);
        }
      };
    });
  };

  document.getElementById("sp-knopf").onclick = () => {
    st.laeuft = true; st.setzePunkte(0); st.setzeFehler(0);
    runde = 0; st.knopf("Neu"); st.sag("Von klein nach gross.");
    neueRunde();
  };
}

// =================================================================
//  17. Toleranz schätzen
// =================================================================
function spielToleranz(b) {
  b.innerHTML = spielRahmen("Im Toleranzfeld?",
    "Sollmass mit Toleranz, daneben das gemessene Mass. Gut oder Ausschuss?",
    '<div class="spass-frage" id="sp-frage"></div>'
    + '<div class="spass-antworten">'
    + '<button class="knopf knopf--haupt" data-gut>Gutteil</button>'
    + '<button class="knopf knopf--gefahr" data-schlecht>Ausschuss</button></div>', "Starten");

  const st = spielStand("toleranz");
  st.rekordZeigen();
  let istGut = false;

  const neueFrage = () => {
    const soll = 10 + zufall(80);
    const tol = auswahlZufall([0.02, 0.05, 0.1, 0.2]);
    const abweichung = (Math.random() * 2 - 1) * tol * 2;
    const gemessen = soll + abweichung;
    istGut = Math.abs(abweichung) <= tol;

    document.getElementById("sp-frage").innerHTML =
      'Soll <strong>' + soll.toFixed(2) + '</strong> ± ' + tol.toFixed(2) + ' mm<br>'
      + 'Gemessen <strong>' + gemessen.toFixed(3) + '</strong> mm';
  };

  const pruefen = (antwort) => {
    if (!st.laeuft) return;
    if (antwort === istGut) {
      st.setzePunkte(st.punkte + 1);
      st.sag(auswahlZufall(SPRUECHE));
    } else {
      st.setzeFehler(st.fehler + 1);
      st.sag(istGut ? "Das war noch im Feld." : "Das war draussen.");
      if (st.fehler >= 3) {
        st.laeuft = false; st.knopf("Nochmal");
        st.sag("Schluss. " + st.punkte + " richtig." + (st.rekordPruefen() ? " Rekord!" : ""));
        return;
      }
    }
    neueFrage();
  };

  b.querySelector("[data-gut]").onclick = () => pruefen(true);
  b.querySelector("[data-schlecht]").onclick = () => pruefen(false);

  document.getElementById("sp-knopf").onclick = () => {
    st.laeuft = true; st.setzePunkte(0); st.setzeFehler(0);
    st.knopf("Neu"); st.sag("Messen und entscheiden.");
    neueFrage();
  };
}

// =================================================================
//  18. Eier stapeln
// =================================================================
function spielStapeln(b) {
  b.innerHTML = spielRahmen("Eier stapeln",
    "Die Eierschachtel fährt hin und her. Tipp, wenn sie über dem Stapel steht. "
    + "Je genauer, desto höher kommst du.",
    '<div class="spass-stapel" id="sp-stapel">'
    + '<div class="spass-stapel__wagen" id="sp-wagen">🥚</div>'
    + '<div class="spass-stapel__turm" id="sp-turm"></div></div>', "Starten");

  const st = spielStand("stapeln");
  st.rekordZeigen();
  const wagen = document.getElementById("sp-wagen");
  const turm = document.getElementById("sp-turm");
  let x = 0, richtung = 1, takt = null, ziel = 50, tempo = 1.4;

  const ende = () => {
    clearInterval(takt);
    st.laeuft = false; st.knopf("Nochmal");
    st.sag("Umgefallen bei " + st.punkte + " Eiern."
      + (st.rekordPruefen() ? " Rekord!" : ""));
  };

  document.getElementById("sp-knopf").onclick = () => {
    if (st.laeuft) {
      const abstand = Math.abs(x - ziel);
      if (abstand > 12) {
        st.setzeFehler(st.fehler + 1);
        st.sag(auswahlZufall(["Daneben, alles kippt.", "Rührei."]));
        return ende();
      }
      st.setzePunkte(st.punkte + 1);
      ziel = x;
      const ei = document.createElement("div");
      ei.className = "spass-stapel__ei";
      ei.style.left = x + "%";
      ei.style.bottom = (st.punkte * 16) + "px";
      ei.textContent = "🥚";
      turm.appendChild(ei);
      tempo = Math.min(3.4, tempo + 0.15);
      st.sag(auswahlZufall(["Sitzt.", "Weiter so.", "Ruhige Hand."]));
      return;
    }

    st.laeuft = true; st.setzePunkte(0); st.setzeFehler(0);
    turm.innerHTML = ""; ziel = 50; x = 0; richtung = 1; tempo = 1.4;
    st.knopf("Ablegen"); st.sag("Timing.");
    clearInterval(takt);
    takt = setInterval(() => {
      x += richtung * tempo;
      if (x >= 92) { x = 92; richtung = -1; }
      if (x <= 0) { x = 0; richtung = 1; }
      wagen.style.left = x + "%";
    }, 16);
  };
}

// =================================================================
//  19. Buchstabensalat
// =================================================================
function spielSalat(b) {
  const WOERTER = ["DREHEN", "FRAESEN", "SPANNEN", "MESSEN", "BOHRER", "SPINDEL",
    "SUPPORT", "REITSTOCK", "WENDEPLATTE", "TOLERANZ", "MESSING", "TITAN",
    "SPAENE", "KUEHLUNG", "GEWINDE", "PLANDREHEN"];

  b.innerHTML = spielRahmen("Buchstabensalat",
    "Welches Werkstattwort steckt dahinter? Drei Fehler und Schluss.",
    '<div class="spass-frage" id="sp-frage"></div>'
    + '<div class="spass-antworten" id="sp-antworten"></div>', "Starten");

  const st = spielStand("salat");
  st.rekordZeigen();

  const neueFrage = () => {
    const richtig = auswahlZufall(WOERTER);
    const salat = richtig.split("").sort(() => Math.random() - 0.5).join(" ");
    const wahl = [richtig];
    while (wahl.length < 4) {
      const f = auswahlZufall(WOERTER);
      if (!wahl.includes(f)) wahl.push(f);
    }
    wahl.sort(() => Math.random() - 0.5);

    document.getElementById("sp-frage").innerHTML =
      '<span class="spass-salat">' + esc(salat) + '</span>';
    document.getElementById("sp-antworten").innerHTML = wahl.map((w) =>
      '<button class="knopf" data-w="' + esc(w) + '">' + esc(w) + '</button>').join("");

    document.querySelectorAll("[data-w]").forEach((k) => {
      k.onclick = () => {
        if (!st.laeuft) return;
        if (k.dataset.w === richtig) {
          st.setzePunkte(st.punkte + 1);
          st.sag(auswahlZufall(["Erkannt.", "Genau das."]));
        } else {
          st.setzeFehler(st.fehler + 1);
          st.sag("Es war " + richtig + ".");
          if (st.fehler >= 3) {
            st.laeuft = false; st.knopf("Nochmal");
            st.sag("Schluss. " + st.punkte + " richtig."
              + (st.rekordPruefen() ? " Rekord!" : ""));
            return;
          }
        }
        neueFrage();
      };
    });
  };

  document.getElementById("sp-knopf").onclick = () => {
    st.laeuft = true; st.setzePunkte(0); st.setzeFehler(0);
    st.knopf("Neu"); st.sag("Kombinieren.");
    neueFrage();
  };
}

// =================================================================
//  20. Der Hühnerhof
// =================================================================
function spielHuehnerhof(b) {
  b.innerHTML = spielRahmen("Der Hühnerhof",
    "Nur die braunen Hühner gehören in den Stall. Weisse antippen gibt Abzug. "
    + "Zwanzig Sekunden.",
    '<div class="spass-wiese" id="sp-wiese"></div>', "Tor auf");

  const st = spielStand("huehnerhof");
  st.rekordZeigen();
  const wiese = document.getElementById("sp-wiese");
  let spawn = null, uhr = null, sekunden = 20;

  const neuesTier = () => {
    const braun = Math.random() < 0.65;
    const el = document.createElement("button");
    el.className = "spass-huhn";
    el.textContent = braun ? "🐔" : "🕊️";
    el.style.left = zufall(86) + "%";
    el.style.top = zufall(74) + "%";
    el.onclick = () => {
      if (!st.laeuft) return;
      if (braun) {
        st.setzePunkte(st.punkte + 1);
        st.sag(auswahlZufall(["Rein damit.", "Eins mehr.", "Gutes Huhn."]));
      } else {
        st.setzeFehler(st.fehler + 1);
        st.setzePunkte(Math.max(0, st.punkte - 2));
        st.sag("Das war eine Taube. Minus zwei.");
      }
      el.remove();
    };
    wiese.appendChild(el);
    setTimeout(() => el.remove(), 1500);
  };

  const ende = () => {
    clearInterval(spawn); clearInterval(uhr);
    wiese.innerHTML = "";
    st.laeuft = false; st.knopf("Nochmal");
    st.sag("Feierabend im Stall. " + st.punkte + " Punkte."
      + (st.rekordPruefen() ? " Rekord!" : ""));
  };

  document.getElementById("sp-knopf").onclick = () => {
    if (st.laeuft) return ende();
    st.laeuft = true; st.setzePunkte(0); st.setzeFehler(0);
    sekunden = 20; wiese.innerHTML = "";
    st.knopf("Abbrechen"); st.sag("Noch 20 Sekunden.");
    spawn = setInterval(neuesTier, 400);
    uhr = setInterval(() => {
      sekunden--;
      st.sag("Noch " + sekunden + " Sekunden.");
      if (sekunden <= 0) ende();
    }, 1000);
  };
}

