// Top fünf je Spiel, gespeichert in der Datenbank
async function bestenlisteZeigen() {
  const ziel = document.getElementById("sp-bestenliste");
  if (!ziel || !spass.aktuell) return;

  ladeFertig(ziel);
  ziel.innerHTML = '<div class="laedt">Bestenliste …</div>';
  try {
    const { data, error } = await zeitlimit(
      db.from("game_scores").select("*").eq("spiel", spass.aktuell.name)
        .order("punkte", { ascending: false }).limit(5), 8000, "Bestenliste");
    if (error) throw error;

    const liste = data || [];
    ziel.innerHTML = '<h3 class="untertitel">Top 5 · ' + esc(spass.aktuell.titel) + '</h3>'
      + (liste.length
        ? '<table class="tabelle"><tbody>' + liste.map((z, i) =>
            '<tr><td class="stark">' + (i + 1) + '.</td>'
            + '<td>' + esc(z.person) + '</td>'
            + '<td class="rechts stark">' + zahlText(z.punkte) + '</td></tr>').join("")
          + '</tbody></table>'
        : '<p class="hinweis">Noch keine Ergebnisse. Sei der Erste.</p>');
  } catch (f) {
    ziel.innerHTML = '<p class="hinweis">Bestenliste nicht verfügbar.</p>';
  }
}

// Ergebnis eintragen, wenn es besser ist als der eigene bisherige Wert
async function ergebnisSpeichern(spielName, punkte) {
  if (!punkte || punkte <= 0 || !profil) return;
  const person = profil.full_name || profil.email || "unbekannt";
  try {
    const { data } = await db.from("game_scores").select("id, punkte")
      .eq("spiel", spielName).eq("person", person).maybeSingle();

    if (data && data.punkte >= punkte) return;
    if (data) await db.from("game_scores").update({ punkte: punkte }).eq("id", data.id);
    else await db.from("game_scores").insert({ spiel: spielName, person: person, punkte: punkte });

    bestenlisteZeigen();
  } catch (f) { /* Bestenliste ist Beiwerk, Fehler stören das Spiel nicht */ }
}

function seiteSpass(b) {
  // Jedes Mal ein anderes Spiel als beim letzten Aufruf
  let i = zufall(SPIELE.length);
  if (SPIELE.length > 1) {
    while (i === spass.zuletzt) i = zufall(SPIELE.length);
  }
  spass.zuletzt = i;

  b.innerHTML = '<h1 class="seitentitel">Timeout Area</h1>'
    + '<div id="sp-spiel"></div>'
    + '<section class="karte"><div id="sp-bestenliste"></div></section>'
    + '<section class="karte"><h2>Werkstattweisheit</h2>'
    + '<p class="spass-weisheit" id="sp-weisheit"></p>'
    + '<button class="linkknopf" id="sp-weisheit-neu">Noch eine</button></section>';

  spass.aktuell = SPIELE[i];
  SPIELE[i].fn(document.getElementById("sp-spiel"));
  bestenlisteZeigen();

  const anderes = document.getElementById("sp-anderes");
  if (anderes) anderes.onclick = () => seiteSpass(b);

  const zeigen = () => {
    document.getElementById("sp-weisheit").textContent = auswahlZufall(WEISHEITEN);
  };
  zeigen();
  document.getElementById("sp-weisheit-neu").onclick = zeigen;
}

