// =================================================================
//  FORTSCHRITT
//  Wie stehen die Aufträge zeitlich? Für jeden laufenden Auftrag
//  wird verglichen, wie viel bis heute hätte fertig sein sollen und
//  wie viel es wirklich ist. Die Abweichung in Stück wird über die
//  Tagesleistung in Tage umgerechnet.
// =================================================================

function fortschrittRechnen(j) {
  const heute = isoDatum(new Date());
  const tage = Math.max(1, j.planned_days || 1);
  const ziel = Number(j.target_quantity) || 0;
  const stand = Number(j.stand) || 0;
  const proTag = ziel / tage;

  const fertig = !!j.ended_at || j.plan_status === "fertig";
  const laeuft = j.plan_status === "laeuft";

  // Noch nicht angefangen, obwohl der Start vorbei ist
  if (!laeuft && !fertig && j.planned_from && j.planned_from < heute) {
    const spaet = arbeitstageZwischen(j.planned_from, heute) - 1;
    return { art: "nichtgestartet", tage: -spaet, stueck: -Math.round(spaet * proTag),
             soll: 0, proTag: proTag };
  }

  if (!laeuft || !ziel) return null;

  // Wie viele Arbeitstage laufen schon?
  const seit = j.planned_from && j.planned_from <= heute
    ? arbeitstageZwischen(j.planned_from, heute) : 0;
  const gelaufen = Math.min(tage, Math.max(0, seit));
  const soll = Math.round(proTag * gelaufen);
  const abweichung = stand - soll;

  return { art: "laeuft", tage: proTag > 0 ? abweichung / proTag : 0,
           stueck: abweichung, soll: soll, proTag: proTag, gelaufen: gelaufen };
}

