// =================================================================
//  LAUFENDER ABGLEICH
//  Jede Seite wird im Hintergrund aufgefrischt, ohne dass die
//  Seite neu lädt. Läuft nur, wenn gerade niemand tippt und kein
//  Fenster offen ist.
// =================================================================

const sync = { takt: null, pfad: null, stempel: null, kanal: null };

function syncStoppen() {
  if (sync.takt) { clearInterval(sync.takt); sync.takt = null; }
  if (sync.kanal) { db.removeChannel(sync.kanal); sync.kanal = null; }
  sync.stempel = null;
}

// Kurzer Fingerabdruck der Daten, die eine Seite anzeigt.
// Nur wenn er sich ändert, wird neu gezeichnet.
// Ob sich auf einer Seite etwas geändert hat, rechnet die Datenbank
// selbst aus und schickt nur einen kurzen Fingerabdruck zurück. Vorher
// lud jede offene App alle 45 Sekunden ganze Tabellen herunter — in der
// Produktion alle Zählerstände seit Beginn, und die werden jeden Tag
// mehr. Das machte die App mit der Zeit immer träger.
let serverStempelFehlt = false;

async function serverStempel(tabellen) {
  if (serverStempelFehlt || !tabellen || !tabellen.length) return null;
  try {
    const r = await zeitlimit(db.rpc("stempel", { tabellen: tabellen }), 8000, "Stempel");
    if (r.error || typeof r.data !== "string" || !r.data) throw r.error || new Error("leer");
    return r.data;
  } catch (f) {
    serverStempelFehlt = true;   // dann wie bisher, bis zum nächsten Laden der Seite
    return null;
  }
}

async function seitenStempel(pfad) {
  // Zuerst der schnelle Weg über die Datenbank
  const schnell = await serverStempel(syncTabellen(pfad));
  if (schnell) return schnell;

  const teile = [];
  const hole = async (tabelle, felder) => {
    try {
      // Feste Sortierung ist Pflicht. Ohne sie kommen die Zeilen in
      // wechselnder Reihenfolge, und der Abdruck ändert sich grundlos.
      const r = await db.from(tabelle).select(felder).order("id");
      if (!r.error) teile.push(JSON.stringify(r.data));
    } catch (f) { /* eine fehlende Tabelle darf nicht stören */ }
  };

  if (pfad === "dashboard") {
    await hole("jobs", "id,problem,problem_at,fa_erstellt,material_ok,planned_from,plan_status");
    await hole("todos", "id,text,is_done,due_date");
    await hole("shopping_items", "id,text,is_done,prio");
    await hole("order_items", "id,status,quantity,needed_by");
    // ohne Personen: dort stehen auch die persönlichen Einstellungen
  } else if (pfad === "produktion") {
    await hole("production_records", "id,machine_id,record_date,quantity");
    await hole("jobs", "id,machine_id,job_number,ended_at,plan_status,target_quantity");
    await hole("machines", "id,name,machine_number,sort_order,is_active");
  } else if (pfad === "bestellungen") {
    await hole("order_items", "id,status,quantity,needed_by,note,ziel_art,ziel_text,article_id");
    await hole("articles", "id,article_number,name,supplier_id,is_active");
    await hole("suppliers", "id,name,website,is_active");
    await hole("designations", "id,name");
  } else if (pfad === "einkauf") {
    await hole("shopping_items", "id,text,menge,laden,prio,is_done");
  } else if (pfad === "einstellungen") {
    await hole("profiles", "id,full_name,role,is_active,geburtstag,darf_bearbeiten,parks,bild_url");
    await hole("people", "id,name,geburtstag,bild_url");
  } else {
    return null;   // Rechner und Timeout haben keine gemeinsamen Daten
  }

  return teile.join("|");
}

// Welche Tabellen für eine Seite wichtig sind, für die Realtime-Anmeldung
function syncTabellen(pfad) {
  // Ohne profiles: dort landen auch die persönlichen Einstellungen. Jeder
  // Regler, den jemand im Betrieb verschob, liess sonst alle Startseiten
  // neu aufbauen. Geburtstage kommen beim nächsten Öffnen.
  if (pfad === "dashboard") return ["jobs", "todos", "shopping_items", "order_items"];
  if (pfad === "produktion") return ["production_records", "jobs", "machines"];
  if (pfad === "bestellungen") return ["order_items", "articles", "suppliers", "designations"];
  if (pfad === "einkauf") return ["shopping_items"];
  if (pfad === "einstellungen") return ["profiles", "people"];
  return [];
}

// Prüft, ob sich etwas geändert hat, und zeichnet nur dann neu.
// Wird sowohl vom Zeittakt als auch von Realtime aufgerufen.
async function syncPruefen() {
  if (document.hidden) return;
  if (document.querySelector(".dialog-huelle")) return;

  const a = document.activeElement;
  if (a && (a.tagName === "INPUT" || a.tagName === "TEXTAREA"
            || a.tagName === "SELECT" || a.isContentEditable)) return;

  const bereich = document.getElementById("inhalt");
  if (!bereich) { syncStoppen(); return; }

  const jetzt = await seitenStempel(sync.pfad);
  if (jetzt === null) return;

  if (sync.stempel === null) { sync.stempel = jetzt; return; }
  if (jetzt === sync.stempel) return;
  sync.stempel = jetzt;

  // Produktion und Startseite sind React-Seiten: Sie frischen sich
  // über seite.zeige still auf, ohne Reiter und Felder neu aufzubauen.

  const seite = SEITEN.find((x) => x.pfad === sync.pfad);
  if (!seite) return;

  const y = window.scrollY;
  seite.zeige(bereich);
  setTimeout(() => window.scrollTo(0, y), 60);
}

function syncStarten(pfad) {
  syncStoppen();
  sync.pfad = pfad;

  // Die Planwand hat ihren eigenen Abgleich
  if (pfad === "planwand") return;

  seitenStempel(pfad).then((w) => { sync.stempel = w; });

  // Realtime: sofortige Nachricht der Datenbank bei einer Änderung.
  // Mehrere Änderungen kurz hintereinander werden gesammelt.
  const tabellen = syncTabellen(pfad);
  if (tabellen.length && db && typeof db.channel === "function") {
    let kanal = db.channel("sync-" + pfad + "-" + Date.now());
    let entpreller = null;
    tabellen.forEach((t) => {
      kanal = kanal.on("postgres_changes", { event: "*", schema: "public", table: t }, () => {
        clearTimeout(entpreller);
        entpreller = setTimeout(syncPruefen, 500);
      });
    });
    kanal.subscribe();
    sync.kanal = kanal;
  }

  // Langsamer Zeittakt als Netz, falls Realtime einmal ausfällt
  sync.takt = setInterval(syncPruefen, 45000);
}

