async function eierStandLaden() {
  try {
    const r = await db.from("eier_zaehler").select("wert").eq("id", true).maybeSingle();
    eier.wert = (r.data && Number(r.data.wert)) || 0;
  } catch (f) { eier.wert = 0; }
  eierAnzeigen();
}

// Sechs Eier ergeben eine Schachtel. Angezeigt werden immer beide
// Zahlen: volle Schachteln und die losen Eier obendrauf.
function eierSchachteln() {
  return { schachteln: Math.floor(eier.wert / 6), rest: eier.wert % 6 };
}

// Zeichnet eine Schachtel mit sechs Mulden, gefüllt nach Anzahl
function eierSchachtelBild(gefuellt, klasse) {
  let felder = "";
  for (let i = 0; i < 6; i++) {
    felder += '<span class="eier-mulde' + (i < gefuellt ? " eier-mulde--voll" : "") + '"></span>';
  }
  return '<span class="' + (klasse || "eier-schachtel") + '">' + felder + '</span>';
}

function eierAnzeigen() {
  const s2 = eierSchachteln();

  const gross = document.getElementById("eier-grossbild");
  if (gross) gross.innerHTML = eierSchachtelBild(s2.rest, "eier-schachtel eier-schachtel--gross");

  const text = document.getElementById("eier-grosszahl");
  if (text) {
    text.innerHTML = '<strong>' + s2.schachteln + '</strong> '
      + (s2.schachteln === 1 ? "volle Schachtel" : "volle Schachteln")
      + ' <span class="klein">und ' + s2.rest
      + (s2.rest === 1 ? " Ei" : " Eier") + ' lose</span>';
  }
}

async function eierSpeichern(neuerWert) {
  eier.wert = Math.max(0, neuerWert);
  eierAnzeigen();
  const { error } = await db.from("eier_zaehler").upsert({ id: true, wert: eier.wert });
  if (error) meldung(fehlertext(error), "fehler");
}

