// Beim Abmelden alles sauber beenden, damit nach dem nächsten
// Anmelden nicht zwei Verbindungen gleichzeitig laufen.
// =================================================================
//  FAHRZEUGE
//  Buchen, Historie, Probleme melden, Verwaltung — alles in
//  diesem einen schwebenden Fenster.
// =================================================================

const fahrzeugZustand = { reiter: "buchen" };

// Erzeugt eine Termindatei, die Outlook und jeder andere Kalender
// öffnen kann. Beim Doppelklick landet der Termin im Kalender.
function kalendereintrag(buchung) {
  const fahrzeug = buchung.fahrzeuge ? buchung.fahrzeuge.name : "Fahrzeug";

  // Wer das Fahrzeug braucht, und wer es bewilligt hat
  const nutzer = buchung.profiles
    ? personName(buchung.profiles)
    : ((profil && (profil.full_name || profil.email)) || "");
  const bewilliger = buchung.entscheider
    ? (buchung.entscheider.full_name || buchung.entscheider.email) : "";

  // Zeitstempel im Format, das Kalender erwarten: 20260415T081500Z
  const stempel = (wert) => {
    const d = new Date(wert);
    return d.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, "");
  };

  // Zeilenumbrüche und Sonderzeichen müssen maskiert werden
  const sauber = (t) => String(t || "")
    .replace(/\\/g, "\\\\").replace(/;/g, "\\;")
    .replace(/,/g, "\\,").replace(/\n/g, "\\n");

  const zeilen = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "PRODID:-//Hofer Tool//Fahrzeuge//DE",
    "CALSCALE:GREGORIAN",
    "METHOD:PUBLISH",
    "BEGIN:VEVENT",
    "UID:" + buchung.id + "@hofer-tool",
    "DTSTAMP:" + stempel(new Date()),
    "DTSTART:" + stempel(buchung.von),
    "DTEND:" + stempel(buchung.bis),
    "SUMMARY:" + sauber(fahrzeug + " — " + (nutzer || "reserviert")),
    "DESCRIPTION:" + sauber(
      "Fahrzeug: " + fahrzeug
      + "\nWer: " + (nutzer || "unbekannt")
      + "\nWofür: " + (buchung.grund || "—")
      + "\nBewilligt von: " + (bewilliger || "—")),
    "LOCATION:" + sauber("Hofer + Co. Präzisionsdrehteile"),
    "END:VEVENT",
    "END:VCALENDAR",
  ];

  // Kalender verlangen Zeilenenden mit Wagenrücklauf
  const inhalt = zeilen.join("\r\n");
  const datei = new Blob([inhalt], { type: "text/calendar;charset=utf-8" });
  const adresse = URL.createObjectURL(datei);

  const a = document.createElement("a");
  a.href = adresse;
  a.download = fahrzeug.replace(/[^\wäöüÄÖÜß -]/g, "") + ".ics";
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(adresse), 2000);

  meldung("Termindatei erstellt. Zum Eintragen in Outlook öffnen.");
}

