// Die Anmeldeseite bleibt immer blau. Dunkler Modus, Themenfarbe und
// schmale Leiste kommen erst nach dem Anmelden — und zwar die der
// Person, die sich anmeldet, nicht die des Vorgängers am Gerät.

try {
  stand("Verbindung wird aufgebaut …");
  db = await verbinden();

  stand("Anmeldung wird geprüft …");
  const p = await profilLaden();

  BOOT.hidden = true;
  WURZEL.hidden = false;

  if (!p) {
    zeigeLogin();
  } else if (p.is_active === false) {
    await db.auth.signOut();
    profil = null;
    zeigeLogin();
    meldung("Dieses Konto ist deaktiviert. Bitte an den Besitzer wenden.", "fehler");
  } else {
    zeichneGeruest();
  }
} catch (fehler) {
  console.error(fehler);
  startFehler(esc(fehler.message || String(fehler)));
}
